    function _snapshotModulesForEscrow(uint256 workflowId) internal {
        address resModule = address(_getResolutionModule(workflowId));
        address incentiveMod = ModuleSnapshotLibrary.getIncentiveModule(resModule);
        moduleSnapshots[workflowId] = ModuleSnapshot({
            resolutionModule: resModule,
            releaseStrategy: address(_getReleaseStrategy(workflowId)),
            yieldGenerationModule: address(_getYieldGenerationModule(workflowId)),
            yieldDistributionModule: address(_getYieldDistributionModule(workflowId)),
            incentiveModule: incentiveMod,
            yieldProtocolFeeBps: yieldProtocolFeeBps,
            appealBondProtocolFeeBps: appealBondProtocolFeeBps,
            escrowFeeBps: escrowFee,
            defaultAutoReleaseDelay: timeoutConfig.defaultAutoReleaseDelay,
            defaultAutoCancelDelay: timeoutConfig.defaultAutoCancelDelay,
            maxDisputeDuration: timeoutConfig.maxDisputeDuration,
            appealWindowDuration: timeoutConfig.appealWindowDuration
        });
    }

    function automateTimedActions(uint256 workflowId) external nonReentrant returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        ModuleSnapshot storage snap = moduleSnapshots[workflowId];
        if (address(settlementOps) == address(0)) return false;
        SettlementOps.SettlementPendingSettlement memory pendingMem = _convertPendingSettlement(pendingSettlements[workflowId]);

        // Use snapshotted timeout config
        TimeoutConfig memory snappedTimeoutConfig = TimeoutConfig({
            defaultAutoReleaseDelay: snap.defaultAutoReleaseDelay,
            defaultAutoCancelDelay: snap.defaultAutoCancelDelay,
            maxDisputeDuration: snap.maxDisputeDuration,
            appealWindowDuration: snap.appealWindowDuration
        });

        (uint8 actionType, bool isRelease) = settlementOps.computeTimedActions(workflowId, et, pendingMem, snappedTimeoutConfig);
        if (actionType == ACTION_NONE) return false;

        ExecutionSource source = hasRole(ROLE_TIMELOCK, _msgSender()) ? ExecutionSource.GOVERNANCE : ExecutionSource.KEEPER;
        // If participant calls it, it's USER authority
        if (_msgSender() == et.from || _msgSender() == et.to) source = ExecutionSource.USER;

        if (actionType == ACTION_EXECUTE_PENDING) {
            delete pendingSettlements[workflowId];
            _finalizeDisputeInModule(workflowId);
            if (isRelease) _releaseEscrowTransfer(workflowId);
            else _cancelAndRefund(workflowId);
            emit PendingSettlementExecuted(workflowId, isRelease);
            emit TimedActionTriggered(workflowId, ACTION_EXECUTE_PENDING, source, _msgSender());
            return true;
        } else if (actionType == ACTION_AUTO_RELEASE) {
            _releaseEscrowTransfer(workflowId);
            emit TimedActionTriggered(workflowId, ACTION_AUTO_RELEASE, source, _msgSender());
            return true;
        } else if (actionType == ACTION_AUTO_CANCEL) {
            _cancelAndRefund(workflowId);
            emit TimedActionTriggered(workflowId, ACTION_AUTO_CANCEL, source, _msgSender());
            return true;
        }

        return false;
    }

    function recipientCancel(uint256 workflowId) external nonReentrant returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.to != _msgSender()) revert NotRecipient(workflowId, _msgSender(), et.to);
        if (et.escrowState != EscrowState.PENDING)
            revert TransferNotPending(workflowId, et.escrowState);

        et.recipientStatus = RecipientStatus.AGREE_TO_CANCEL;
        if (et.senderStatus == SenderStatus.AGREE_TO_CANCEL) {
            _cancelAndRefund(workflowId);
        }
        return true;
    }

    function senderCancel(uint256 workflowId) external nonReentrant returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.from != _msgSender()) revert NotSender(workflowId, _msgSender(), et.from);
        if (et.escrowState != EscrowState.PENDING)
            revert TransferNotPending(workflowId, et.escrowState);

        et.senderStatus = SenderStatus.AGREE_TO_CANCEL;
        if (et.recipientStatus == RecipientStatus.AGREE_TO_CANCEL) {
            _cancelAndRefund(workflowId);
        }
        return true;
    }

    // slither-disable-next-line reentrancy-no-eth
    function autoCancelDisputedEscrow(uint256 workflowId) external nonReentrant {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        ModuleSnapshot storage snap = moduleSnapshots[workflowId];
        if (et.escrowState != EscrowState.DISPUTED) {
            revert TransferNotInDispute(workflowId, et.escrowState);
        }

        // CRIT-3: Prevent overriding a resolver's decision that is pending settlement
        if (pendingSettlements[workflowId].exists) {
            revert InvalidState(workflowId, uint8(EscrowState.DISPUTED), uint8(et.escrowState)); // Has pending settlement
        }

        uint256 ts = disputeRaisedTimestamp[workflowId];
        if (ts == 0 || block.timestamp < ts + snap.maxDisputeDuration) {
            revert InvalidState(workflowId, uint8(EscrowState.DISPUTED), uint8(et.escrowState)); // Dispute timeout not exceeded
        }
        address from = et.from;
        uint256 amt = et.amountAfterFee;
        _cancelAndRefund(workflowId);
        delete disputeRaisedTimestamp[workflowId];
        emit DisputeAutoCancelled(workflowId, from, amt, uint8(FailureReason.TIMEOUT));

        ExecutionSource source = hasRole(ROLE_TIMELOCK, _msgSender()) ? ExecutionSource.GOVERNANCE : ExecutionSource.KEEPER;
        if (_msgSender() == et.from || _msgSender() == et.to) source = ExecutionSource.USER;
        emit TimedActionTriggered(workflowId, ACTION_AUTO_CANCEL, source, _msgSender());
    }

    // slither-disable-next-line reentrancy-no-eth
    function raiseDispute(uint256 workflowId) external nonReentrant {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        ModuleSnapshot storage snap = moduleSnapshots[workflowId];

        DisputeOps.DisputeOpeningResult memory result = disputeOps.computeDisputeOpening(
            address(_getResolutionModule(workflowId)),
            address(this),
            snap.incentiveModule,
            workflowId,
            _msgSender(),
            et.from,
            et.to,
            et.token,
            et.amountAfterFee,
            et.escrowState,
            et.disputeResolver
        );

        if (!result.success) revert TransferNotPending(workflowId, et.escrowState);

        StateManagementLibrary.transitionToDisputed(et, workflowId, (_msgSender() == et.from));
        disputeRaisedTimestamp[workflowId] = block.timestamp;

        emit EscrowStateChanged(workflowId, EscrowState.PENDING, EscrowState.DISPUTED);
        emit DisputeOpened(workflowId, _msgSender(), result.updatedResolver);

        if (result.updatedResolver != et.disputeResolver) {
            et.disputeResolver = result.updatedResolver;
        }

        DisputeInitializationLibrary.initializeInModule(
            snap.resolutionModule,
            workflowId,
            et.disputeResolver,
            EscrowEncodingLibrary.encodeEscrowTransferData(et.token, et.from, et.to, et.amountAfterFee, escrowSettings[workflowId].releaseAddress)
        );
        DisputeInitializationLibrary.callResolverCallback(et.disputeResolver, workflowId);

        if (result.callIncentiveHook) {
            if (DisputeRaiseLibrary.callIncentiveModuleHook(
                result.incentiveModule,
                workflowId,
                et.token,
                et.amountAfterFee,
                snap.escrowFeeBps,
                ESCROW_FEE_DENOMINATOR
            )) {
                emit OperationFailure(3, workflowId, result.incentiveModule, IIncentiveModule.onDisputeOpened.selector, uint8(FailureReason.CALL_FAILED));
            }
        }
    }

    /**
     * @notice Helper function to get incentive module from resolution module
     * @dev Used to access public incentiveModule variable from DecentralizedResolutionModule
     */

    /**
     * @notice Validate and prepare escalation, canceling any pending settlement
     * @param workflowId The escrow ID
     * @return et EscrowTransfer storage reference
     * @return resolutionModule Resolution module for this escrow
     */
    function _validateAndPrepareEscalation(
        uint256 workflowId
    ) internal returns (EscrowTransfer storage et, IResolutionModule resolutionModule) {
        _validateWorkflowId(workflowId);
        et = escrowTransfers[workflowId];
        if (address(disputeOps) == address(0)) revert ZeroDisputeOps();
        resolutionModule = _getResolutionModule(workflowId);

        if (pendingSettlements[workflowId].exists) {
            delete pendingSettlements[workflowId];
            emit PendingSettlementCancelled(workflowId);
        }
    }

    // DEPRECATED: _collectEscalationBond removed - use BondCollector instead


    /**
     * @notice Escalate a dispute to the next resolution level
     * @dev V1: Appeals are disabled. This function will revert if called for v1 escrows
     *      (incentiveModule snapshot is null). Appeals are enabled in Phase 2 via
     *      resolution module + incentive module swap through governance.
     *      
     *      For Phase 2: Requires payment of appeal bond (amount/token determined by resolution module).
     *      Bonds are recorded in the snapshotted incentive module for later distribution.
     *      
     * @param workflowId The escrow workflow ID to escalate
     * @return success True if escalation succeeded
     * @return newDisputeResolver Address of the resolver assigned to the next level
     * @return newLevel New escalation level
     */
    function escalateDispute(
        uint256 workflowId
    )
        external
        payable
        nonReentrant
        returns (bool success, address newDisputeResolver, uint8 newLevel)
    {
        (EscrowTransfer storage et, IResolutionModule resolutionModule) = _validateAndPrepareEscalation(workflowId);
        ModuleSnapshot storage snap = moduleSnapshots[workflowId];

        DisputeOps.EscalationResult memory result = disputeOps.computeEscalation(
            address(resolutionModule),
            address(this),
            snap.incentiveModule,
            snap.appealBondProtocolFeeBps,
            escrowFeeAddress,
            workflowId,
            _msgSender(),
            et.from,
            et.to,
            et.token,
            et.amountAfterFee,
            et.escrowState
        );
        if (!result.success) revert EscalationNotAllowed();

        // Validate bond payment
        (bool msgValueValid, ) = DisputeEscalationLibrary.validateBondMsgValue(result.bondToken, result.bondAmount, msg.value);
        if (!msgValueValid) revert InvalidBondMsgValue(workflowId, result.bondAmount, msg.value);

        if (result.bondAmount > 0) {
            if (result.protocolFeeAmount > 0) {
                emit ProtocolFeeCollected(1, workflowId, result.bondToken, result.bondAmount, snap.appealBondProtocolFeeBps, result.protocolFeeAmount);
            }

            IIncentiveModule incentiveMod = IIncentiveModule(result.incentiveModule);
            if (result.bondToken == address(0)) {
                BondHandlingLibrary.handleETHBond(
                    incentiveMod,
                    workflowId,
                    _msgSender(),
                    result.bondToRecord,
                    result.bondToken,
                    result.newLevel,
                    escrowFeeAddress,
                    result.protocolFeeAmount
                );
            } else {
                if (address(bondCollector) == address(0)) revert ZeroBondCollector();

                uint256 balBefore = IERC20(result.bondToken).balanceOf(address(this));
                _pullTokens(result.bondToken, _msgSender(), result.bondAmount);
                uint256 received = IERC20(result.bondToken).balanceOf(address(this)) - balBefore;
                if (received < result.bondAmount) revert AccountingDeficit(result.bondToken, result.bondAmount - received);

                BondHandlingLibrary.handleERC20BondAfterPull(
                    incentiveMod,
                    bondCollector,
                    workflowId,
                    _msgSender(),
                    result.bondToken,
                    result.bondToRecord,
                    result.newLevel,
                    escrowFeeAddress,
                    result.protocolFeeAmount
                );
            }
        }

        // Execute escalation in module (modifies module state)
        bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(et.token, et.from, et.to, et.amountAfterFee, escrowSettings[workflowId].releaseAddress);
        (bool escSuccess, bytes memory escData) = address(resolutionModule).call(
            abi.encodeWithSelector(IResolutionModule.executeEscalation.selector, workflowId, address(this), escrowData)
        );
        if (!escSuccess) revert EscalationNotAllowed();

        (bool modSuccess, address newRes, uint8 newLvl) = abi.decode(escData, (bool, address, uint8));
        if (!modSuccess || newRes == address(0)) revert EscalationNotAllowed();

        et.disputeResolver = newRes;

        if (result.bondToken == address(0) && msg.value > result.bondAmount) {
            uint256 excess = msg.value - result.bondAmount;
            (bool s, ) = payable(_msgSender()).call{value: excess}('');
            if (!s) revert ExcessRefundTransferFailed(workflowId, _msgSender(), excess);
        }

        emit DisputeEscalated(workflowId, result.currentLevel, newLvl, newRes, _msgSender());
        return (true, newRes, newLvl);
    }

    // ============ Resolution ============
    /**
     * @notice Shared internal function for executing resolution actions (always full resolution)
     * @param workflowId The escrow workflow ID
     * @param isRelease True to release to recipient, false to cancel/refund to sender
     * @param resolutionHash Hash of resolution details (for offchain verification)
     * @return success True if resolution executed successfully
     */
    function _executeResolution(
        uint256 workflowId,
        bool isRelease,
        bytes32 resolutionHash
    ) internal returns (bool) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];

        if (!_isAuthorizedDisputeResolver(workflowId, _msgSender()))
            revert NotAuthorizedResolver(_msgSender(), et.disputeResolver);
        if (et.escrowState != EscrowState.DISPUTED)
            revert TransferNotInDispute(workflowId, et.escrowState);

        _recordResolutionOutcome(workflowId, _msgSender(), isRelease, resolutionHash);
        emit EscrowResolved(workflowId, _msgSender(), resolutionHash);

        IResolutionModule resolutionModule = _getResolutionModule(workflowId);
        address snap = moduleSnapshots[workflowId].resolutionModule;
        if (snap != address(0) && address(resolutionModule) != snap) {
            resolutionModule = IResolutionModule(snap);
        }
        if (address(resolutionModule) != address(0) && address(resolutionModule).code.length == 0) {
            revert NotAContract(1, address(resolutionModule));
        }

        if (address(settlementOps) == address(0)) revert ZeroSettlementOps();

        SettlementOps.ResolutionResult memory result = settlementOps.computeResolutionExecution(
            address(resolutionModule),
            workflowId,
            isRelease,
            timeoutConfig
        );

        if (result.shouldExecute) {
            if (isRelease) _releaseEscrowTransfer(workflowId);
            else _cancelAndRefund(workflowId);
            return true;
        }
        pendingSettlements[workflowId] = PendingSettlement({exists: true, isRelease: isRelease, appealDeadline: result.appealDeadline, resolutionHash: resolutionHash});
        emit PendingSettlementSet(workflowId, isRelease, result.appealDeadline);
        return true;
    }

    function executePendingSettlement(uint256 workflowId) external nonReentrant {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];
        PendingSettlement storage pending = pendingSettlements[workflowId];

        if (address(settlementOps) == address(0)) revert ZeroSettlementOps();
        SettlementOps.SettlementPendingSettlement memory pendingMem = _convertPendingSettlement(pending);
        (bool canExecute, bool isRelease) = settlementOps.computePendingSettlementExecution(workflowId, pendingMem, et.escrowState);
        if (!canExecute) {
            if (!pending.exists) revert NoPendingSettlement(workflowId);
            if (block.timestamp < pending.appealDeadline) revert AppealWindowNotExpired(workflowId, pending.appealDeadline, block.timestamp);
            revert NotInDisputedState(workflowId, et.escrowState);
        }
        delete pendingSettlements[workflowId];
        IResolutionModule resolutionModule = _getResolutionModule(workflowId);
        if (address(resolutionModule) != address(0)) _finalizeDisputeInModule(workflowId);
        if (isRelease) _releaseEscrowTransfer(workflowId);
        else _cancelAndRefund(workflowId);

        emit PendingSettlementExecuted(workflowId, isRelease);
    }

    /// @notice Release escrow to recipient (core settlement action)
    /// @param workflowId Unique escrow identifier
    /// @dev Consults the release strategy to determine eligibility
    /// @dev Transitions PENDING → RELEASED
    /// @dev May transfer funds immediately (push) or create claimable balance (fallback)
    /// @dev Part of IEscrowCore interface for wallet adoption
    /// @dev Callable even when paused (release strategy may further restrict)
    function release(uint256 workflowId) external nonReentrant {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];

        // Only PENDING escrows can be released
        if (et.escrowState != EscrowState.PENDING) {
            revert TransferNotPending(workflowId, et.escrowState);
        }

        // Encode escrow data once (canonical format: token, sender, recipient, amountAfterFee, releaseAddress)
        bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(
            et.token,
            et.from,
            et.to,
            et.amountAfterFee,
            escrowSettings[workflowId].releaseAddress
        );

        // Load release strategy from snapshot
        IReleaseStrategy strategy = _getReleaseStrategy(workflowId);

        // Check strategy is configured (revert if not; don't silently bypass policy)
        if (address(strategy) == address(0)) {
            revert ReleaseStrategyNotSet(workflowId);
        }

        // Consult strategy for eligibility
        (bool allowed, uint8 reasonCode) = strategy.canRelease(
            workflowId,
            address(this),
            _msgSender(),
            escrowData
        );

        // Require strategy allows the release
        if (!allowed) {
            // reasonCode 1 = not authorized, 2 = wrong state, etc.
            // For wallet-friendly error, use a compact error that maps to the code
            if (reasonCode == 1) {
                revert NotSender(workflowId, _msgSender(), et.from);
            } else {
                revert ReleaseNotAllowed(workflowId, reasonCode);
            }
        }

        // Release the escrow (handles push/fallback internally)
        _releaseEscrowTransfer(workflowId);
    }

    function cancelAsDisputeResolver(uint256 workflowId, bytes32 resolutionHash) public nonReentrant returns (bool) {
        return _executeResolution(workflowId, false, resolutionHash);
    }

    function releaseAsDisputeResolver(uint256 workflowId, bytes32 resolutionHash) public nonReentrant returns (bool) {
        return _executeResolution(workflowId, true, resolutionHash);
    }

    function _isAuthorizedDisputeResolver(
        uint256 workflowId,
        address disputeResolver
    ) internal view returns (bool) {
        EscrowTransfer storage et = escrowTransfers[workflowId];

        // If a customResolver is set for this escrow, it is the only authorized resolver.
        // Governance or module-level resolver changes must NOT override this per-escrow choice.
        EscrowSettings memory settings = escrowSettings[workflowId];
        if (settings.customResolver != address(0)) {
            return disputeResolver == settings.customResolver;
        }

        address snap = moduleSnapshots[workflowId].resolutionModule;
        if (snap != address(0)) {
            bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(
                et.token,
                et.from,
                et.to,
                et.amountAfterFee,
                escrowSettings[workflowId].releaseAddress
            );
            (bool success, bytes memory data) = snap.staticcall(
                abi.encodeWithSelector(IResolutionModule.isAuthorizedDisputeResolver.selector, workflowId, address(this), disputeResolver, escrowData)
            );
            if (success && data.length >= 64) {
                (bool authorized, ) = abi.decode(data, (bool, uint8));
                if (authorized) return true;
            }
        }
        return disputeResolver == et.disputeResolver;
    }

    function _applyEscrowSettings(uint256 workflowId, EscrowSettings memory settings) internal {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (settings.customResolver != address(0)) et.disputeResolver = settings.customResolver;
        bool useDefaults = (settings.autoReleaseTime == 0 && settings.autoCancelTime == 0);

        uint256 relTime = settings.autoReleaseTime;
        if (relTime == 0 && useDefaults && timeoutConfig.defaultAutoReleaseDelay > 0) {
            relTime = block.timestamp + timeoutConfig.defaultAutoReleaseDelay;
        }
        if (relTime > type(uint64).max) revert InvalidAutoTime(AUTO_TIME_TOO_LARGE, relTime, block.timestamp);
        et.autoReleaseTime = uint64(relTime);

        uint256 cancTime = settings.autoCancelTime;
        if (cancTime == 0 && useDefaults && timeoutConfig.defaultAutoCancelDelay > 0) {
            cancTime = block.timestamp + timeoutConfig.defaultAutoCancelDelay;
        }
        if (cancTime > type(uint64).max) revert InvalidAutoTime(AUTO_TIME_TOO_LARGE, cancTime, block.timestamp);
        et.autoCancelTime = uint64(cancTime);

        escrowSettings[workflowId] = settings;
        emit EscrowSettingsUpdated(workflowId, settings);
    }

    /**
     * @notice Convert PendingSettlement storage to memory (consolidated helper)
     * @param pending Storage reference
     * @return pendingMem Memory struct
     */
    function _convertPendingSettlement(PendingSettlement storage pending) internal view returns (SettlementOps.SettlementPendingSettlement memory pendingMem) {
        return SettlementOps.SettlementPendingSettlement({
            exists: pending.exists,
            isRelease: pending.isRelease,
            appealDeadline: pending.appealDeadline,
            resolutionHash: pending.resolutionHash
        });
    }

    function _finalizeDisputeInModule(uint256 workflowId) internal {
        IResolutionModule resolutionModule = _getResolutionModule(workflowId);
        if (address(resolutionModule) != address(0)) {
            (bool success, ) = address(resolutionModule).call(abi.encodeWithSelector(SEL_FINALIZE_DISPUTE, workflowId));
            success; // Ignore failure
        }
    }


    function withdrawEscrow(uint256 workflowId) external nonReentrant returns (uint256) {
        _validateWorkflowId(workflowId);
        EscrowTransfer storage et = escrowTransfers[workflowId];

        if (et.escrowState != EscrowState.RESOLVED &&
            et.escrowState != EscrowState.RELEASED &&
            et.escrowState != EscrowState.REFUNDED) {
            revert TransferNotFinalized(workflowId, et.escrowState);
        }

        address token = et.token; // Single token per escrow
        uint256 amount = claimableBalances[workflowId][_msgSender()];
        if (amount == 0) revert NoClaimableBalance(workflowId, _msgSender(), token);

        claimableBalances[workflowId][_msgSender()] = 0;
        totalClaimableAssets[token] -= amount;

        _transferTokens(token, _msgSender(), amount);

        emit EscrowWithdrawn(workflowId, _msgSender(), token, amount);
        return amount;
    }


    function _validateWorkflowId(uint256 workflowId) internal view {
        if (workflowId >= escrowTransfers.length) {
            revert InvalidWorkflowId(workflowId, escrowTransfers.length);
        }
    }

    /**
     * @notice Get the total number of escrows created
     * @return count Total number of escrows
     * @dev Added for EscrowViewContract to check bounds without reverting
     */
    function getEscrowCount() external view returns (uint256 count) {
        return escrowTransfers.length;
    }

    /// @notice Check if release is allowed - simplified for size
    function canRelease(uint256 workflowId, address caller) external view returns (bool allowed) {
        if (workflowId >= escrowTransfers.length) return false;
        EscrowTransfer storage et = escrowTransfers[workflowId];
        if (et.escrowState != EscrowState.PENDING) return false;
        if (caller != et.from) return false;
        return true;
    }

    // Stub for backwards compatibility - returns state directly
    function getEscrowState(uint256 workflowId) external view returns (EscrowState state) {
        _validateWorkflowId(workflowId);
        return escrowTransfers[workflowId].escrowState;
    }

    // View functions moved to EscrowViewContract for size optimization:
    // - getResolutionMode() 
    // - getActiveDisputeHandler()
    // - canRelease()
    // - getActionStatus()

    function _requirePending(uint256 workflowId) internal view {
        _validateWorkflowId(workflowId);
        EscrowState st = escrowTransfers[workflowId].escrowState;
        if (st != EscrowState.PENDING) {
            revert TransferNotPending(workflowId, st);
        }
    }

    /**
     * @notice Attempt automatic transfer with graceful fallback to claimable balance
     * @param workflowId The escrow ID
     * @param recipient Address to receive funds
     * @param token Token address
     * @param amount Amount to transfer
     * @param principalExpected Expected principal (for validating yield claims)
     * @return transferred True if transfer succeeded, false if fell back to claimable
     */
    function _attemptAutoTransfer(
        uint256 workflowId,
        address recipient,
        address token,
        uint256 amount,
        uint256 principalExpected
    ) internal returns (bool transferred) {
        if (amount == 0) {
            return false;
        }

        uint256 bal = IERC20(token).balanceOf(address(this));

        // CRITICAL: If module claims yield (amount > principal), escrow MUST have the funds
        // Otherwise the module overreported and we must revert to prevent fund loss
        if (amount > principalExpected) {
            require(bal >= amount, "EscrowInsufficientBalance");
        }

        // If amount <= principalExpected, it's OK to fallback to claimable if transfer fails
        bool success = bal >= amount && _tryTransfer(token, recipient, amount);
        if (success) {
            emit EscrowTransferAutoResult(workflowId, recipient, token, amount, true, 0);
            return true;
        }

        // Transfer failed - set as claimable
        claimableBalances[workflowId][recipient] += amount;
        totalClaimableAssets[token] += amount;
        emit ClaimableBalanceSet(workflowId, recipient, token, amount);
        uint8 reason = bal < amount ? uint8(FailureReason.CONTRACT_INSUFFICIENT_BALANCE) : uint8(FailureReason.PUSH_FAILED_FALLBACK_TO_PULL);
        emit EscrowTransferAutoResult(workflowId, recipient, token, amount, false, reason);
        emit OperationFailure(4, workflowId, token, IERC20.transfer.selector, reason);
        return false;
    }

    function _tryTransfer(address token, address to, uint256 amount) internal returns (bool success) {
        (success, ) = token.call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        if (success) {
            assembly {
                if returndatasize() {
                    returndatacopy(0, 0, returndatasize())
                    success := and(mload(0), 0xff)
                }
            }
        }
    }



    /**
     * @notice Handle v2.5 yield module unwind on release/cancel
     * @dev If no module or no initialized yield, returns original amount
     * @dev Otherwise delegates to module for unwind (which handles all recovery)
     * @dev If unwind reverts, tries emergencyUnwind as fallback
     */
    function _handleYieldModuleUnwind(
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal virtual returns (uint256 principalOut, uint256 yieldOut) {
        address module = v25YieldModules[workflowId];
        if (module == address(0)) return (amount, 0);

        uint256 yieldPrincipal = v25YieldPrincipals[workflowId];
        if (yieldPrincipal == 0) return (amount, 0);

        // Try normal unwind first
        try IYieldModule(module).unwindToEscrow(workflowId, token, yieldPrincipal) returns (uint256 principal, uint256 yield) {
            return (principal, yield);
        } catch {
            // Unwind failed - try emergency unwind
            try IYieldModule(module).emergencyUnwind(workflowId, token, yieldPrincipal) returns (uint256 recovered) {
                // INVARIANT: Reject partial recovery - must recover full principal or revert
                if (recovered < yieldPrincipal) {
                    revert("YieldModuleEmergency: PartialRecoveryNotAllowed");
                }
                return (recovered, 0);
            } catch {
                // Emergency unwind also failed - return original amount as fallback
                return (yieldPrincipal, 0);
            }
        }
    }

    function _cancelAndRefund(uint256 workflowId) internal {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        uint256 amount = et.amountAfterFee;
        address from = et.from;
        address token = et.token;

        if (pendingSettlements[workflowId].exists) {
            delete pendingSettlements[workflowId];
            emit PendingSettlementCancelled(workflowId);
        }

        EscrowState oldStatus = StateManagementLibrary.transitionToRefunded(et, workflowId);
        emit EscrowStateChanged(workflowId, oldStatus, EscrowState.REFUNDED);

        (uint256 principal, uint256 yield) = _handleYieldModuleUnwind(workflowId, token, amount);
        uint256 actualAmount = principal + yield;

        // CRITICAL: Update accounting based on FULL principal amount (amount, not principal)
        // When module has loss: principal < amount
        // The loss difference appears as "unaccounted" in the balance delta
        // This makes losses visible in accounting for operators to detect and track
        _updateEscrowBalance(token, amount, false);

        // Auto-transfer: Attempt automatic transfer, fallback to claimable if fails
        _attemptAutoTransfer(workflowId, from, token, actualAmount, amount);
        _emitEscrowTransferCancelled(workflowId, token, from, amount);
    }

    /**
     * @notice Best-effort check if strategy allows release (used by getActionStatus)
     * @dev Uses staticcall to safely query strategy without reverting
     * @return canRelease True if strategy returns allowed=true, false if call fails or not allowed
     */
    function _checkStrategyCanRelease(uint256 workflowId, EscrowTransfer storage et) internal view returns (bool canRelease) {
        IReleaseStrategy strategy = _getReleaseStrategy(workflowId);
        if (address(strategy) == address(0)) {
            return false;
        }

        try this._staticCanRelease(
            workflowId,
            et.token,
            et.from,
            et.to,
            et.amountAfterFee
        ) returns (bool allowed) {
            return allowed;
        } catch {
            // If strategy call fails, report as unavailable (safe default for UI)
            return false;
        }
    }

    /**
     * @notice Wrapper for staticcall to strategy (internal helper for getActionStatus)
     * @dev Takes individual escrow fields instead of storage pointer (required for external function)
     */
    function _staticCanRelease(
        uint256 workflowId,
        address token,
        address sender,
        address recipient,
        uint256 amountAfterFee
    ) external view returns (bool) {
        IReleaseStrategy strategy = _getReleaseStrategy(workflowId);
        if (address(strategy) == address(0)) {
            return false;
        }

        // Get releaseAddress from escrow settings
        address releaseAddr = escrowSettings[workflowId].releaseAddress;

        bytes memory escrowData = EscrowEncodingLibrary.encodeEscrowTransferData(
            token,
            sender,
            recipient,
            amountAfterFee,
            releaseAddr
        );

        (bool allowed, ) = strategy.canRelease(workflowId, address(this), _msgSender(), escrowData);
        return allowed;
    }

    function _releaseEscrowTransfer(uint256 workflowId) internal {
        EscrowTransfer storage et = escrowTransfers[workflowId];
        uint256 amount = et.amountAfterFee;
        address to = et.to;
        address token = et.token;

        if (pendingSettlements[workflowId].exists) {
            delete pendingSettlements[workflowId];
            emit PendingSettlementCancelled(workflowId);
        }

        EscrowState oldStatus = StateManagementLibrary.transitionToReleased(et, workflowId);
        emit EscrowStateChanged(workflowId, oldStatus, EscrowState.RELEASED);

        (uint256 principal, uint256 yield) = _handleYieldModuleUnwind(workflowId, token, amount);
        uint256 actualAmount = principal + yield;

        // CRITICAL: Update accounting based on FULL principal amount (amount, not principal)
        // When module has loss: principal < amount
        // Example: amount=990e18, principal=890e18 (loss=100e18)
        // We reduce totalHeldInEscrowPerToken by 990e18 (full amount)
        // But only transfer out 890e18
        // The 100e18 difference appears as "unaccounted" in the balance delta
        // This makes losses visible in accounting: contractBalance - expected = loss
        _updateEscrowBalance(token, amount, false);

        // Auto-transfer: Attempt automatic transfer, fallback to claimable if fails
        _attemptAutoTransfer(workflowId, to, token, actualAmount, amount);
        _emitEscrowTransferReleased(workflowId, token, to, amount);
    }

    function _transferTokens(address token, address to, uint256 amount) internal virtual;
    function _updateEscrowBalance(address token, uint256 amount, bool add) internal virtual;
    function _emitEscrowTransferCancelled(
        uint256 workflowId,
        address token,
        address from,
        uint256 amount
    ) internal virtual;
    function _emitEscrowTransferReleased(
        uint256 workflowId,
        address token,
        address to,
        uint256 amount
    ) internal virtual;
    function _getYieldGenerationModule(
        uint256 workflowId
    ) internal view virtual returns (IYieldModule);
    function _getYieldDistributionModule(
        uint256 workflowId
    ) internal view virtual returns (IYieldDistributionModule);
    function _getReleaseStrategy(
        uint256 workflowId
    ) internal view virtual returns (IReleaseStrategy);
    function _getResolutionModule(
        uint256 workflowId
    ) internal view virtual returns (IResolutionModule) {
        address snap = moduleSnapshots[workflowId].resolutionModule;
        if (snap != address(0)) {
            return IResolutionModule(snap);
        }
        return IResolutionModule(disputeResolutionModule);
    }

    function _depositYieldForEscrow(uint256 workflowId, address token, uint256 amount) internal virtual {
        IYieldModule genModule = _getYieldGenerationModule(workflowId);
        if (address(genModule) != address(0)) {
            (bool supported, ) = genModule.canHandle(token, YieldPreset.OFF, amount);
            if (supported) {
                // Call _depositForYield which is overridden in child contracts (EscrowVault/EscrowableERC20)
                // This allows child contracts to set approvals before calling the module
                _depositForYield(genModule, workflowId, token, amount);
            }
        }
    }

    // ResolutionOutcome enum removed - using version from EscrowTypes.sol

    function _recordResolutionOutcome(
        uint256 workflowId,
        address disputeResolver,
        bool isRelease,
        bytes32 /* resolutionHash */
    ) internal {
        address module = address(_getResolutionModule(workflowId));
        if (module == address(0)) return;
        ResolutionOutcome outcome = isRelease
            ? ResolutionOutcome.RELEASE
            : ResolutionOutcome.CANCEL;
        uint256 resolutionTime = block.timestamp;
        (bool success, ) = module.call(
            abi.encodeWithSelector(
                SEL_RECORD_RESOLUTION,
                workflowId,
                address(this),
                disputeResolver,
                uint8(outcome),
                resolutionTime
            )
        );
        success;
    }
}

contracts/core/BondCollector.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts/access/AccessControl.sol';
import '../shared/interfaces/IIncentiveModule.sol';
import '../types/EscrowTypes.sol';

/**
 * @title BondCollector
 * @notice External contract for collecting escalation bonds (ETH or ERC20)
 * @dev Extracted from BaseEscrow to reduce contract size (Priority 2 optimization)
 * 
 *      Handles:
 *      - ETH bond collection with protocol fee deduction
 *      - ERC20 bond collection with protocol fee deduction
 *      - Custody lives in this contract for ERC20 bonds (escrow transfers in, this contract approves incentive module)
 *      - Protocol fee transfer to fee address
 *      - Bond recording via incentive module
 */
contract BondCollector is AccessControl {
    using SafeERC20 for IERC20;

    // ============ Role Constants ============
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // ============ Custom Errors ============
    error ZeroOwner();

    // Events
    event ProtocolFeeCollected(
        uint8 indexed kind, // 1 = appeal bond
        uint256 indexed workflowId,
        address indexed token,
        uint256 bondAmount,
        uint256 feeBps,
        uint256 feeAmount
    );

    /**
     * @notice Constructor for BondCollector
     * @param initialOwner Address that will receive DEFAULT_ADMIN_ROLE (for initial setup only)
     */
    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialOwner must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    /**
     * @notice Register an escrow contract (grants it ROLE_ESCROW_CONTRACT)
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidAddress(ADDR_ESCROW_CONTRACT, escrowContract);
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @notice Collect escalation bond (ETH or ERC20) and deduct protocol fee
     * @param workflowId The escrow ID
     * @param incentiveMod Incentive module for bond recording
     * @param bondAmount Bond amount to collect
     * @param bondToken Bond token address (address(0) for ETH)
     * @param newLevel New escalation level
     * @param snapshottedBondFee Protocol fee in basis points (from module snapshot)
     * @param escrowFeeAddress Address to receive protocol fees
     * @param depositor Address that deposited the bond (user for ETH, this contract for ERC20)
     * @param escalatedBy Address that initiated the escalation (always the user)
     * @return collected Whether bond was successfully collected
     * @dev Only authorized escrow contracts can call this function
     */
    function collectBond(
        uint256 workflowId,
        IIncentiveModule incentiveMod,
        uint256 bondAmount,
        address bondToken,
        uint8 newLevel,
        uint256 snapshottedBondFee,
        address escrowFeeAddress,
        address depositor,
        address escalatedBy
    ) external payable onlyRole(ROLE_ESCROW_CONTRACT) returns (bool collected) {
        if (address(incentiveMod) == address(0)) return false;

        if (bondToken == address(0)) {
            return _collectETHBond(workflowId, incentiveMod, bondAmount, newLevel, snapshottedBondFee, escrowFeeAddress, depositor, escalatedBy);
        } else {
            return _collectERC20Bond(workflowId, incentiveMod, bondAmount, bondToken, newLevel, snapshottedBondFee, escrowFeeAddress, depositor, escalatedBy);
        }
    }

    /**
     * @notice Internal function to handle ETH bond collection
     */
    function _collectETHBond(
        uint256 workflowId,
        IIncentiveModule incentiveMod,
        uint256 bondAmount,
        uint8 newLevel,
        uint256 snapshottedBondFee,
        address escrowFeeAddress,
        address depositor,
        address escalatedBy
    ) internal returns (bool) {
        uint256 ethToSend = bondAmount;
        if (msg.value > bondAmount) {
            ethToSend = bondAmount;
        }

        if (snapshottedBondFee > 0 && escrowFeeAddress != address(0)) {
            uint256 protocolFeeAmount = (ethToSend * snapshottedBondFee) / 10000;
            if (protocolFeeAmount > 0) {
                (bool feeSuccess, ) = payable(escrowFeeAddress).call{value: protocolFeeAmount}('');
                if (!feeSuccess) return false;
                ethToSend = ethToSend - protocolFeeAmount;
                emit ProtocolFeeCollected(1, workflowId, address(0), bondAmount, snapshottedBondFee, protocolFeeAmount);
            }
        }

        if (ethToSend > 0) {
            return _recordETHBond(workflowId, incentiveMod, ethToSend, newLevel, depositor, escalatedBy);
        }
        return false;
    }

    function _recordETHBond(
        uint256 workflowId,
        IIncentiveModule incentiveMod,
        uint256 ethToSend,
        uint8 newLevel,
        address depositor,
        address escalatedBy
    ) internal returns (bool) {
        (bool s, ) = address(incentiveMod).call{value: ethToSend}(
            abi.encodeWithSelector(
                IIncentiveModule.recordAppealBond.selector,
                workflowId,
                _msgSender(),
                depositor,
                escalatedBy,
                ethToSend,
                address(0),
                newLevel
            )
        );
        return s;
    }

    /**
     * @notice Internal function to handle ERC20 bond collection
     */
    function _collectERC20Bond(
        uint256 workflowId,
        IIncentiveModule incentiveMod,
        uint256 bondAmount,
        address bondToken,
        uint8 newLevel,
        uint256 snapshottedBondFee,
        address escrowFeeAddress,
        address depositor,
        address escalatedBy
    ) internal returns (bool) {
        // CRIT-3: Actually pull the tokens from the caller
        IERC20(bondToken).safeTransferFrom(_msgSender(), address(this), bondAmount);

        uint256 bondToRecord = bondAmount;

        if (snapshottedBondFee > 0 && escrowFeeAddress != address(0)) {
            uint256 protocolFeeAmount = (bondAmount * snapshottedBondFee) / 10000;
            if (protocolFeeAmount > 0) {
                bondToRecord = bondAmount - protocolFeeAmount;
                IERC20(bondToken).safeTransfer(escrowFeeAddress, protocolFeeAmount);
                emit ProtocolFeeCollected(1, workflowId, bondToken, bondAmount, snapshottedBondFee, protocolFeeAmount);
            }
        }

        if (bondToRecord > 0) {
            IERC20(bondToken).safeIncreaseAllowance(address(incentiveMod), bondToRecord);
            try incentiveMod.recordAppealBond(workflowId, _msgSender(), depositor, escalatedBy, bondToRecord, bondToken, newLevel) {
                IERC20(bondToken).approve(address(incentiveMod), 0);
                return true;
            } catch {
                IERC20(bondToken).approve(address(incentiveMod), 0);
                return false;
            }
        }
        return false;
    }

    /**
     * @notice Approve a spender to pull ERC20 bond tokens
     * @dev Intended for escrow contract flows where the escrow contract calls the incentive module,
     *      but custody lives in this contract (BondCollector).
     */
    function approveBondSpender(
        address token,
        address spender,
        uint256 amount
    ) external onlyRole(ROLE_ESCROW_CONTRACT) {
        IERC20(token).safeIncreaseAllowance(spender, amount);
    }

    /**
     * @notice Reset an ERC20 approval back to zero
     * @dev Best practice to avoid leaving allowances lingering on third-party contracts.
     */
    function resetBondSpender(address token, address spender) external onlyRole(ROLE_ESCROW_CONTRACT) {
        IERC20(token).approve(spender, 0);
    }

    /**
     * @notice Recover ERC20 tokens sent to this contract by mistake
     */
    function recoverERC20(
        address token,
        address recipient,
        uint256 amount
    ) external onlyRole(ROLE_TIMELOCK) {
        uint256 balance = IERC20(token).balanceOf(address(this));
        uint256 recoveryAmount = amount == 0 ? balance : amount;
        if (recoveryAmount > balance) revert InvalidAmount(AMOUNT_GENERIC);
        IERC20(token).safeTransfer(recipient, recoveryAmount);
    }

    /**
     * @notice Recover native ETH sent to this contract by mistake
     */
    function recoverNativeETH(
        address recipient,
        uint256 amount
    ) external onlyRole(ROLE_TIMELOCK) {
        uint256 balance = address(this).balance;
        uint256 recoveryAmount = amount == 0 ? balance : amount;
        if (recoveryAmount > balance) revert InvalidAmount(AMOUNT_GENERIC);
        (bool success, ) = payable(recipient).call{value: recoveryAmount}("");
        if (!success) revert InvalidAddress(ADDR_RECIPIENT, recipient);
    }
}

contracts/core/CREATE2EscrowFactory.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/utils/Create2.sol';
import './EscrowVault.sol';

/**
 * @title CREATE2EscrowFactory
 * @notice Factory for deploying EscrowVault with deterministic addresses
 * @dev Uses CREATE2 to ensure same contract address across all L2s with identical salt
 */
contract CREATE2EscrowFactory {
    event EscrowDeployed(
        address indexed escrowVault,
        bytes32 salt,
        uint256 escrowFeeBps,
        address feeAddress
    );

    error DeploymentFailed(bytes32 salt);
    error AlreadyDeployed(bytes32 salt, address existing);

    /// @notice Get the address where an escrow will be deployed
    function getDeploymentAddress(
        uint256 escrowFeeBps,
        address feeAddress,
        address yieldOpsAddress,
        address disputeOpsAddress,
        address moduleManagementAddress,
        bytes32 salt
    ) external view returns (address predictedAddress) {
        bytes memory bytecode = abi.encodePacked(
            type(EscrowVault).creationCode,
            abi.encode(
                escrowFeeBps,
                feeAddress,
                yieldOpsAddress,
                disputeOpsAddress,
                moduleManagementAddress
            )
        );
        predictedAddress = Create2.computeAddress(salt, keccak256(bytecode));
    }

    /// @notice Deploy EscrowVault to deterministic address
    function deployEscrow(
        uint256 escrowFeeBps,
        address feeAddress,
        address yieldOpsAddress,
        address disputeOpsAddress,
        address moduleManagementAddress,
        bytes32 salt
    ) external returns (EscrowVault escrowVault) {
        bytes memory constructorArgs = abi.encode(
            escrowFeeBps,
            feeAddress,
            yieldOpsAddress,
            disputeOpsAddress,
            moduleManagementAddress
        );

        bytes memory bytecode = abi.encodePacked(
            type(EscrowVault).creationCode,
            constructorArgs
        );

        address predictedAddress = Create2.computeAddress(salt, keccak256(bytecode));
        if (predictedAddress.code.length > 0) {
            revert AlreadyDeployed(salt, predictedAddress);
        }

        escrowVault = EscrowVault(
            Create2.deploy(0, salt, bytecode)
        );

        if (address(escrowVault) == address(0)) {
            revert DeploymentFailed(salt);
        }

        emit EscrowDeployed(
            address(escrowVault),
            salt,
            escrowFeeBps,
            feeAddress
        );
    }

    /// @notice Check if escrow is deployed at predicted address
    function isDeployed(
        uint256 escrowFeeBps,
        address feeAddress,
        address yieldOpsAddress,
        address disputeOpsAddress,
        address moduleManagementAddress,
        bytes32 salt
    ) external view returns (bool deployed) {
        address predictedAddress = this.getDeploymentAddress(
            escrowFeeBps,
            feeAddress,
            yieldOpsAddress,
            disputeOpsAddress,
            moduleManagementAddress,
            salt
        );
        deployed = predictedAddress.code.length > 0;
    }
}

contracts/core/EscrowableERC20.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/ERC20.sol';
import './BaseEscrow.sol';
import '../types/EscrowTypes.sol';
import '../types/YieldPresets.sol';
import '../interfaces/IReleaseStrategy.sol';
import '../shared/interfaces/IResolutionModule.sol';
import '../interfaces/IYieldModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import './ModuleSnapshotRegistry.sol';
import '../libraries/ModuleGetterLibrary.sol';
import '../libraries/ModuleGetterConsolidationLibrary.sol';

/**
 * @title EscrowableERC20
 */
contract EscrowableERC20 is ERC20, BaseEscrow {
    using SafeERC20 for IERC20;
    uint256 public constant INITIAL_SUPPLY = 1000000000000000000000000;
    uint256 public totalHeldInEscrow = 0;
    uint256 public totalFees = 0;
    ModuleSnapshotRegistry public immutable moduleManagement;

    event FeesWithdrawn(uint256 amount);

    constructor(
        string memory name,
        string memory symbol,
        uint256 escrowFeeBps,
        address feeAddress,
        address yieldOpsAddress,
        address disputeOpsAddress,
        address moduleManagementAddress
    ) ERC20(name, symbol) {
        if (escrowFeeBps > MAX_ESCROW_FEE_BPS) revert InvalidEscrowFee(escrowFeeBps, MAX_ESCROW_FEE_BPS);
        if (feeAddress == address(0)) revert ZeroAddress(1);
        if (yieldOpsAddress == address(0)) revert ZeroAddress(2);
        if (disputeOpsAddress == address(0)) revert ZeroAddress(3);
        if (moduleManagementAddress == address(0)) revert ZeroAddress(4);
        if (yieldOpsAddress.code.length == 0) revert ZeroAddress(2);
        if (disputeOpsAddress.code.length == 0) revert ZeroAddress(3);
        if (moduleManagementAddress.code.length == 0) revert ZeroAddress(4);

        escrowFee = escrowFeeBps;
        escrowFeeAddress = feeAddress;
        yieldOps = YieldOps(yieldOpsAddress);
        disputeOps = DisputeOps(disputeOpsAddress);
        moduleManagement = ModuleSnapshotRegistry(moduleManagementAddress);

        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(ROLE_TIMELOCK, _msgSender());

        yieldProtocolFeeBps = DEFAULT_YIELD_PROTOCOL_FEE_BPS;
        appealBondProtocolFeeBps = 0;
        timeoutConfig.defaultAutoReleaseDelay = 0;
        timeoutConfig.defaultAutoCancelDelay = 0;
        timeoutConfig.maxDisputeDuration = 90 days;
        timeoutConfig.appealWindowDuration = 2 days;

        _mint(_msgSender(), INITIAL_SUPPLY);
    }

    // ============ Convenience Functions ============

    /**
     * @notice Create a new escrow with custom auto-release or auto-cancel time
     * @param seller Recipient address (seller)
     * @param amount Total amount to escrow (after fee deduction)
     * @param autoReleaseTime Timestamp for automatic release (0 = no auto-release)
     * @param autoCancelTime Timestamp for automatic cancel (0 = no auto-cancel)
     * @return workflowId The ID of the created escrow transfer
     */
    function createEscrow(
        address seller,
        uint256 amount,
        uint256 autoReleaseTime,
        uint256 autoCancelTime
    ) public returns (uint256) {
        EscrowSettings memory settings = EscrowSettings({
            customResolver: address(0),
            releaseAddress: address(0),
            yieldPreset: YieldPreset.OFF,
            autoReleaseTime: autoReleaseTime,
            autoCancelTime: autoCancelTime
        });
        return createEscrow(address(this), seller, amount, settings);
    }

    function releaseEscrowTransfer(uint256 workflowId) public nonReentrant {
        _requirePending(workflowId);
        if (escrowTransfers[workflowId].from != _msgSender()) revert NotSender(workflowId, _msgSender(), escrowTransfers[workflowId].from);
        _releaseEscrowTransfer(workflowId);
    }

    // ============ BaseEscrow Hook Implementations ============

    /// @dev Token must be address(this)
    modifier onlyThisToken(address token) {
        if (token != address(this)) revert InvalidAddress(ADDR_TOKEN, token);
        _;
    }

    /**
     * @dev Transfer tokens from sender to contract using ERC20's internal _transfer
     * @param token Token address (must be address(this) for EscrowableERC20)
     * @param from Sender address
     * @param amount Amount to transfer
     */
    function _pullTokens(address token, address from, uint256 amount) internal override onlyThisToken(token) {
        _transfer(from, address(this), amount);
    }

    /**
     * @dev Record fee in totalFees
     * @param token Must be address(this)
     * @param amount Fee amount
     */
    function _recordFee(address token, uint256 amount) internal override onlyThisToken(token) {
        uint256 currentFees = totalFees;
        if (amount > type(uint256).max - currentFees) {
            revert FeeOverflow();
        }
        totalFees = currentFees + amount;
    }

    /**
     * @dev Transfer tokens using ERC20's internal _transfer
     * @param token Token address (must be address(this) for EscrowableERC20)
     * @param to Recipient address
     * @param amount Amount to transfer
     */
    function _transferTokens(address token, address to, uint256 amount) internal override onlyThisToken(token) {
        _transfer(address(this), to, amount);
    }

    /**
     * @dev Update escrow balance tracking
     * @param token Must be address(this)
     * @param amount Amount to add/subtract
     * @param add True to add, false to subtract
     */
    function _updateEscrowBalance(address token, uint256 amount, bool add) internal override onlyThisToken(token) {
        if (add) {
            totalHeldInEscrow += amount;
        } else {
            // CRIT-1: Prevent underflow that could break accounting
            if (totalHeldInEscrow < amount) {
                revert BalanceUnderflow(token, totalHeldInEscrow, amount);
            }
            totalHeldInEscrow -= amount;
        }
    }

    /**
     * @dev Emit EscrowTransferCreated event (without token parameter)
     */
    function _emitEscrowTransferCreated(
        uint256 workflowId,
        address token,
        address from,
        address to,
        uint256 amount
    ) internal pure override {
        workflowId; token; from; to; amount;
    }

    /**
     * @dev Emit EscrowTransferCancelled event (without token parameter)
     */
    function _emitEscrowTransferCancelled(
        uint256 workflowId,
        address token,
        address from,
        uint256 amount
    ) internal pure override {
        workflowId; token; from; amount;
    }

    /**
     * @dev Emit EscrowTransferReleased event (without token parameter)
     */
    function _emitEscrowTransferReleased(
        uint256 workflowId,
        address token,
        address to,
        uint256 amount
    ) internal pure override {
        workflowId; token; to; amount;
    }

    /**
     * @dev Delegate yield deposit to module
     */
    function _depositForYield(
        IYieldModule generationModule,
        uint256 workflowId,
        address token,
        uint256 amount
    ) internal override {
        address moduleAddress = address(generationModule);
        uint256 currentAllowance = allowance(address(this), moduleAddress);
        if (currentAllowance < amount) {
            _approve(address(this), moduleAddress, type(uint256).max);
        }

        uint256 balBefore = balanceOf(address(this));
        uint256 accepted = generationModule.initializeYield(workflowId, token, amount, YieldPreset.OFF);
        uint256 balAfter = balanceOf(address(this));

        if (balBefore - balAfter < accepted) {
            revert AccountingDeficit(token, amount);
        }

        // Store v2.5 yield tracking data
        v25YieldModules[workflowId] = moduleAddress;
        v25YieldPrincipals[workflowId] = accepted;
    }

    // ============ Module Getters ============

    function _getReleaseStrategy(uint256 workflowId) internal view override returns (IReleaseStrategy) {
        address moduleAddr = ModuleGetterLibrary.getModuleAddress(
            workflowId, ModuleType.RELEASE, moduleSnapshots, moduleManagement, address(this)
        );
        return ModuleGetterConsolidationLibrary.getReleaseStrategy(moduleAddr);
    }

    function _getResolutionModule(uint256 workflowId) internal view override returns (IResolutionModule) {
        address moduleAddr = ModuleGetterLibrary.getModuleAddress(
            workflowId, ModuleType.RESOLUTION, moduleSnapshots, moduleManagement, address(this)
        );
        return ModuleGetterConsolidationLibrary.getResolutionModule(moduleAddr, disputeResolutionModule);
    }

    function _getYieldGenerationModule(uint256 workflowId) internal view override returns (IYieldModule) {
        address moduleAddr = ModuleGetterLibrary.getModuleAddress(
            workflowId, ModuleType.YIELD_GEN, moduleSnapshots, moduleManagement, address(this)
        );
        return ModuleGetterConsolidationLibrary.getYieldModule(moduleAddr);
    }

    function _getYieldDistributionModule(uint256 workflowId) internal view override returns (IYieldDistributionModule) {
        address moduleAddr = ModuleGetterLibrary.getModuleAddress(
            workflowId, ModuleType.YIELD_DIST, moduleSnapshots, moduleManagement, address(this)
        );
        return ModuleGetterConsolidationLibrary.getYieldDistributionModule(moduleAddr);
    }

    // ============ Fee Management ============

    /**
     * @notice Withdraw accumulated escrow fees
     * @return success True if withdrawal was successful
     * @dev Only the fee address can withdraw fees. Transfers all accumulated fees to the fee address.
     */
    function withdrawFees() public nonReentrant returns (bool) {
        if (_msgSender() != escrowFeeAddress) {
            revert NotFeeAddress(_msgSender(), escrowFeeAddress);
        }
        uint256 feeAmount = totalFees;
        if (feeAmount == 0) {
            revert NoFeesToWithdraw(address(this), feeAmount);
        }

        // Check balance before clearing state (checks-effects-interactions pattern)
        uint256 balance = balanceOf(address(this));
        if (balance < feeAmount) {
            revert InsufficientContractBalance(address(this), feeAmount, balance);
        }

        // Clear state AFTER successful transfer to prevent fee loss on failure
        // Note: If transfer fails, revert will restore state (Solidity 0.8+ automatic)
        _transfer(address(this), escrowFeeAddress, feeAmount);
        totalFees = 0;

        emit FeesWithdrawn(feeAmount);
        return true;
    }
}

/**
 * @title EscrowableERC20Factory
 * @notice Factory contract for creating new EscrowableERC20 instances
 * @dev Allows deployment of new EscrowableERC20 tokens with custom parameters
 */
contract EscrowableERC20Factory {
    /// @notice Create a new EscrowableERC20 token contract
    function createEscrowableERC20(
        string memory name,
        string memory symbol,
        uint256 escrowFee,
        address escrowFeeAddress,
        address yieldOps,
        address disputeOps,
        address moduleManagement
    ) public returns (address) {
        return
            address(
                new EscrowableERC20(
                    name,
                    symbol,
                    escrowFee,
                    escrowFeeAddress,
                    yieldOps,
                    disputeOps,
                    moduleManagement
                )
            );
    }
}

