// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../../shared/interfaces/IResolutionModule.sol';
import '@openzeppelin/contracts/access/AccessControl.sol';
import '../../types/EscrowTypes.sol';

/**
 * @title DefaultResolutionModule
 * @notice Default resolution module: single resolver, no escalation
 * @dev Pluggable module intended to be selected by governance and used by the escrow contract
 *      to choose the per-escrow disputeResolver at escrow creation time.
 */
contract DefaultResolutionModule is AccessControl, IResolutionModule {
    // Role constants for governance
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');
    address public resolver;

    event ResolverUpdated(address indexed oldResolver, address indexed newResolver);

    constructor(address initialOwner, address initialResolver) {
        if (initialOwner == address(0)) revert InvalidAddress(ADDR_INITIAL_OWNER, initialOwner);
        if (initialResolver == address(0)) revert InvalidAddress(ADDR_INITIAL_RESOLVER, initialResolver);
        resolver = initialResolver;
        // Grant DEFAULT_ADMIN_ROLE to initialOwner so roles can be granted later
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
    }

    function setResolver(address newResolver) external onlyRole(ROLE_TIMELOCK) {
        if (newResolver == address(0)) revert InvalidAddress(ADDR_INITIAL_RESOLVER, newResolver);
        address oldResolver = resolver;
        resolver = newResolver;
        emit ResolverUpdated(oldResolver, newResolver);
    }

    /**
     * @notice Initialize a new dispute in the module
     */
    function initializeDispute(
        uint256 /* workflowId */,
        address /* escrowContract */,
        address /* initialResolver */,
        bytes32 /* categoryKey */
    ) external virtual override {}

    /**
     * @notice Record a resolution outcome
     */
    function recordResolution(
        uint256 /* workflowId */,
        address /* escrowContract */,
        address /* resolver */,
        ResolutionOutcome /* outcome */,
        uint256 /* resolutionTime */
    ) external virtual override {}

    /**
     * @notice Check if address is authorized dispute resolver
     * @dev In default implementation, checks against stored resolver
     */
    function isAuthorizedDisputeResolver(
        uint256 /* workflowId */,
        address /* escrowContract */,
        address checkDisputeResolver,
        bytes calldata /* escrowData */
    ) external view virtual override returns (bool authorized, uint8 role) {
        // Check if the dispute resolver matches the stored resolver
        authorized = (checkDisputeResolver == resolver);
        role = 0;
        return (authorized, role);
    }

    /**
     * @notice Get dispute resolver for dispute
     */
    function getDisputeResolver(
        uint256 /* workflowId */,
        address /* escrowContract */,
        bytes calldata /* escrowData */
    ) external view virtual override returns (address disputeResolver, uint8 escalationLevel) {
        return (resolver, 0);
    }

    /**
     * @notice Check if escalation is allowed (default: no escalation)
     */
    function canEscalate(
        uint256 /* workflowId */,
        address /* escrowContract */,
        uint8 /* currentLevel */,
        bytes calldata /* escrowData */
    ) external pure virtual override returns (bool allowed, address nextResolver, uint256 escalationFee) {
        return (false, address(0), 0);
    }

    /**
     * @notice Execute escalation (default: not supported)
     */
    function executeEscalation(
        uint256 /* workflowId */,
        address /* escrowContract */,
        bytes calldata /* escrowData */
    ) external pure virtual override returns (bool success, address newResolver, uint8 newLevel) {
        return (false, address(0), 0);
    }

    /**
     * @notice Get required appeal bond for escalation (DR v2)
     * @dev Default implementation: no bonds required (returns 0)
     */
    function getRequiredAppealBond(
        uint256 /* workflowId */,
        address /* escrowContract */,
        uint8 /* currentLevel */,
        bytes calldata /* escrowData */
    ) external pure virtual override returns (uint256 amount, address token) {
        return (0, address(0));
    }

    /**
     * @notice Get decision at a specific round
     */
    function getDecisionAtRound(uint256 /* workflowId */, address /* escrowContract */, uint8 /* round */) external view virtual override returns (uint8 decision) {
        return 0; // ResolutionOutcome.NONE
    }

    /**
     * @notice Get appeal deadline and current round
     */
    function getAppealDeadlineAndRound(
        uint256 /* workflowId */,
        address /* escrowContract */
    ) external view virtual override returns (uint256 appealDeadline, uint8 currentRound, bool isFinalRound) {
        return (0, 0, false);
    }

    /**
     * @notice Record a reversal
     */
    function recordReversal(uint256 /* workflowId */, address /* escrowContract */, uint8 /* priorRound */) external virtual override {}

    /**
     * @notice Finalize a dispute
     */
    function finalizeDispute(uint256 /* workflowId */, address /* escrowContract */) external virtual override {}

    /**
     * @notice Get incentive module address (optional interface)
     * @return module Address of incentive module (0 for default)
     * @dev Implemented to avoid "function selector not recognized" reverts in traces
     *      when probed by ModuleSnapshotLibrary.
     */
    function incentiveModule() external pure returns (address) {
        return address(0);
    }

    /**
     * @notice Get module name
     */
    function moduleName() external pure virtual override returns (string memory) {
        return 'DefaultSingleResolver';
    }

    /**
     * @notice Get the module version
     * @return version The module version (semantic versioning)
     */
    function moduleVersion() external pure virtual override returns (string memory version) {
        return '1.0.0';
    }

    /**
     * @notice Check if contract supports an interface
     * @param interfaceId The interface identifier
     * @return supported True if interface is supported
     * @dev AccessControl already includes ERC165
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(AccessControl, IERC165) returns (bool) {
        return
            interfaceId == type(IResolutionModule).interfaceId ||
            super.supportsInterface(interfaceId);
    }
}

contracts/core/ModuleSnapshotRegistry.so.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import '../governance/SlowLaneQueueActivate.sol';
import '../interfaces/IReleaseStrategy.sol';
import '../interfaces/ICancellationStrategy.sol';
import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import '../shared/interfaces/IResolutionModule.sol';
import './BaseEscrow.sol';

/**
 * @title ModuleSnapshotRegistry
 * @notice Registry for module snapshots frozen at escrow creation time.
 * @dev Extracted from EscrowVault/EscrowableERC20 to reduce contract size.
 *      Handles queue/activate pattern for default modules with slow lane activation.
 */
contract ModuleSnapshotRegistry is AccessControl, SlowLaneQueueActivate {
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    /// @notice Module state for each escrow contract
    struct ModuleState {
        IReleaseStrategy defaultReleaseStrategy;
        ICancellationStrategy defaultCancellationStrategy;
        IYieldGenerationModule defaultYieldGenerationModule;
        IYieldDistributionModule defaultYieldDistributionModule;
        IResolutionModule defaultResolutionModule;
        mapping(BaseEscrow.ModuleType => PendingAddress) pendingModules;
    }

    /// @notice Mapping from escrow contract to its module state
    mapping(address => ModuleState) public escrowModuleStates;

    /// @notice Mapping from yield generation module to its assigned escrow contract
    mapping(address => address) public yieldGenerationModuleToEscrow;

    /// @notice Mapping from yield distribution module to its assigned escrow contract
    mapping(address => address) public yieldDistributionModuleToEscrow;

    /// @notice Events for module management
    event DefaultReleaseStrategyQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultReleaseStrategyActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );
    event DefaultYieldGenerationModuleQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultYieldGenerationModuleActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );
    event DefaultYieldDistributionModuleQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultYieldDistributionModuleActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );
    event DefaultResolutionModuleQueued(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule,
        uint64 eta
    );
    event DefaultResolutionModuleActivated(
        address indexed escrowContract,
        address indexed oldModule,
        address indexed newModule
    );

    /// @notice Error when escrow contract is not registered
    error EscrowNotRegistered(address escrowContract);

    /// @notice Error when yield module is already assigned to another escrow contract
    error YieldModuleAlreadyAssigned(address module, address currentEscrow, address newEscrow);

    /**
     * @notice Deploy the ModuleSnapshotRegistry.
     * @param initialAdmin Initial admin for bootstrap (expected to be replaced/managed by governance wiring).
     * @dev Grants `DEFAULT_ADMIN_ROLE` and `ROLE_TIMELOCK` to `initialAdmin` for initial setup.
     *      In production, `ROLE_TIMELOCK` should be held by the TimelockController.
     */
    constructor(address initialAdmin) {
        if (initialAdmin == address(0)) revert InvalidValue();
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialAdmin must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialAdmin);
    }

    /**
     * @notice Register an escrow contract for module management
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidValue();
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @notice Queue a new module
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to queue
     * @param module Address of the new module to queue
     * @dev Only governance (ROLE_TIMELOCK) can queue modules directly.
     *      Ensures the escrow contract is registered.
     *      Enforces 7-day slow lane delay via SlowLaneQueueActivate.
     *      For yield modules, prevents assignment if already assigned to another escrow.
     */
    function queueModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType,
        address module
    ) external onlyRole(ROLE_TIMELOCK) {
        if (!hasRole(ROLE_ESCROW_CONTRACT, escrowContract)) {
            revert EscrowNotRegistered(escrowContract);
        }
        if (module == address(0)) revert InvalidValue();

        ModuleState storage state = escrowModuleStates[escrowContract];

        // Validate yield module exclusivity
        if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            address currentEscrow = yieldGenerationModuleToEscrow[module];
            if (currentEscrow != address(0) && currentEscrow != escrowContract) {
                revert YieldModuleAlreadyAssigned(module, currentEscrow, escrowContract);
            }
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            address currentEscrow = yieldDistributionModuleToEscrow[module];
            if (currentEscrow != address(0) && currentEscrow != escrowContract) {
                revert YieldModuleAlreadyAssigned(module, currentEscrow, escrowContract);
            }
        }

        _queueAddress(state.pendingModules[moduleType], module);

        // Emit appropriate event
        if (moduleType == BaseEscrow.ModuleType.RELEASE) {
            emit DefaultReleaseStrategyQueued(
                escrowContract,
                address(state.defaultReleaseStrategy),
                module,
                state.pendingModules[moduleType].eta
            );
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            emit DefaultYieldGenerationModuleQueued(
                escrowContract,
                address(state.defaultYieldGenerationModule),
                module,
                state.pendingModules[moduleType].eta
            );
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            emit DefaultYieldDistributionModuleQueued(
                escrowContract,
                address(state.defaultYieldDistributionModule),
                module,
                state.pendingModules[moduleType].eta
            );
        } else if (moduleType == BaseEscrow.ModuleType.RESOLUTION) {
            emit DefaultResolutionModuleQueued(
                escrowContract,
                address(state.defaultResolutionModule),
                module,
                state.pendingModules[moduleType].eta
            );
        }
    }

    /**
     * @notice Activate the queued module
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to activate
     * @dev Only governance (ROLE_TIMELOCK) can activate modules directly.
     *      Ensures the escrow contract is registered.
     *      Reverts if no module is queued for the given type, or if the ETA has not passed yet.
     *      Enforces 7-day slow lane delay - cannot be bypassed.
     */
    function activateModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType
    ) external onlyRole(ROLE_TIMELOCK) {
        if (!hasRole(ROLE_ESCROW_CONTRACT, escrowContract)) {
            revert EscrowNotRegistered(escrowContract);
        }

        ModuleState storage state = escrowModuleStates[escrowContract];
        address newModule = _activateAddress(state.pendingModules[moduleType]);
        address oldModule;

        if (moduleType == BaseEscrow.ModuleType.RELEASE) {
            oldModule = address(state.defaultReleaseStrategy);
            state.defaultReleaseStrategy = IReleaseStrategy(newModule);
            emit DefaultReleaseStrategyActivated(escrowContract, oldModule, newModule);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            oldModule = address(state.defaultYieldGenerationModule);
            // Remove old module assignment
            if (oldModule != address(0)) {
                delete yieldGenerationModuleToEscrow[oldModule];
            }
            // Assign new module to this escrow
            state.defaultYieldGenerationModule = IYieldGenerationModule(newModule);
            yieldGenerationModuleToEscrow[newModule] = escrowContract;
            emit DefaultYieldGenerationModuleActivated(escrowContract, oldModule, newModule);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            oldModule = address(state.defaultYieldDistributionModule);
            // Remove old module assignment
            if (oldModule != address(0)) {
                delete yieldDistributionModuleToEscrow[oldModule];
            }
            // Assign new module to this escrow
            state.defaultYieldDistributionModule = IYieldDistributionModule(newModule);
            yieldDistributionModuleToEscrow[newModule] = escrowContract;
            emit DefaultYieldDistributionModuleActivated(escrowContract, oldModule, newModule);
        } else if (moduleType == BaseEscrow.ModuleType.RESOLUTION) {
            oldModule = address(state.defaultResolutionModule);
            state.defaultResolutionModule = IResolutionModule(newModule);
            emit DefaultResolutionModuleActivated(escrowContract, oldModule, newModule);
        }
    }

    /**
     * @notice Get pending module information
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to query
     * @return value Pending module address
     * @return eta Timestamp when activation becomes available
     * @return exists Whether a pending module exists
     */
    function getPendingModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType
    ) external view returns (address value, uint64 eta, bool exists) {
        ModuleState storage state = escrowModuleStates[escrowContract];
        return getPendingAddress(state.pendingModules[moduleType]);
    }

    /**
     * @notice Get default release strategy for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default release strategy
     */
    function getDefaultReleaseStrategy(
        address escrowContract
    ) external view virtual returns (IReleaseStrategy) {
        return escrowModuleStates[escrowContract].defaultReleaseStrategy;
    }

    /**
     * @notice Get default cancellation strategy for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default cancellation strategy
     */
    function getDefaultCancellationStrategy(
        address escrowContract
    ) external view virtual returns (ICancellationStrategy) {
        return escrowModuleStates[escrowContract].defaultCancellationStrategy;
    }

    /**
     * @notice Get default yield generation module for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default yield generation module
     */
    function getDefaultYieldGenerationModule(
        address escrowContract
    ) external view virtual returns (IYieldGenerationModule) {
        return escrowModuleStates[escrowContract].defaultYieldGenerationModule;
    }

    /**
     * @notice Get default yield distribution module for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default yield distribution module
     */
    function getDefaultYieldDistributionModule(
        address escrowContract
    ) external view virtual returns (IYieldDistributionModule) {
        return escrowModuleStates[escrowContract].defaultYieldDistributionModule;
    }

    /**
     * @notice Get default resolution module for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @return The default resolution module
     */
    function getDefaultResolutionModule(
        address escrowContract
    ) external view virtual returns (IResolutionModule) {
        return escrowModuleStates[escrowContract].defaultResolutionModule;
    }

    /**
     * @notice Get module address for an escrow contract by type
     * @param escrowContract Address of the escrow contract
     * @param moduleType Type of module to retrieve
     * @return The module address (address(0) if not set)
     * @dev PRIORITY: Consolidated getter to reduce bytecode in escrow contracts
     */
    function getModule(
        address escrowContract,
        BaseEscrow.ModuleType moduleType
    ) external view returns (address) {
        ModuleState storage state = escrowModuleStates[escrowContract];
        if (moduleType == BaseEscrow.ModuleType.RELEASE) {
            return address(state.defaultReleaseStrategy);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_GEN) {
            return address(state.defaultYieldGenerationModule);
        } else if (moduleType == BaseEscrow.ModuleType.YIELD_DIST) {
            return address(state.defaultYieldDistributionModule);
        } else if (moduleType == BaseEscrow.ModuleType.RESOLUTION) {
            return address(state.defaultResolutionModule);
        }
        return address(0);
    }

    /**
     * @notice Set the default cancellation strategy for an escrow contract
     * @param escrowContract Address of the escrow contract
     * @param cancellationStrategy Address of the cancellation strategy
     * @dev Only callable by ROLE_TIMELOCK (governance)
     */
    function setDefaultCancellationStrategy(
        address escrowContract,
        address cancellationStrategy
    ) external onlyRole(ROLE_TIMELOCK) {
        if (!hasRole(ROLE_ESCROW_CONTRACT, escrowContract)) {
            revert EscrowNotRegistered(escrowContract);
        }
        if (cancellationStrategy == address(0)) revert InvalidValue();
        escrowModuleStates[escrowContract].defaultCancellationStrategy = ICancellationStrategy(cancellationStrategy);
    }
}

contracts/core/MulticallFallbackHandler..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { IMulticall3 } from "../interfaces/IMulticall3.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

struct ChainEndpoint {
    uint256 chainId;
    string rpcUrl;
    uint8 priority;
    bool enabled;
}

struct FallbackConfig {
    address fallbackAggregator;
    uint256 fallbackTimeout;
}

contract MulticallFallbackHandler is Ownable {
    IMulticall3 public primaryMulticall;
    FallbackConfig public fallbackConfig;
    mapping(uint256 => ChainEndpoint) public endpoints;

    event PrimaryMulticallSet(address indexed multicall);
    event FallbackConfigUpdated(address indexed fallbackAggregator, uint256 timeout);
    event EndpointUpdated(uint256 indexed chainId, string rpcUrl);
    event FallbackTriggered(uint256 indexed chainId, string reason);

    error InvalidPrimaryMulticall();
    error InvalidChainId();
    error NoEndpoint();
    error EndpointDisabled();

    constructor(
        address _primaryMulticall,
        address _fallbackAggregator,
        uint256 _fallbackTimeout
    ) Ownable(msg.sender) {
        if (_primaryMulticall == address(0)) revert InvalidPrimaryMulticall();
        primaryMulticall = IMulticall3(_primaryMulticall);
        fallbackConfig = FallbackConfig({
            fallbackAggregator: _fallbackAggregator,
            fallbackTimeout: _fallbackTimeout
        });
    }

    function setPrimaryMulticall(address _multicall) external onlyOwner {
        if (_multicall == address(0)) revert InvalidPrimaryMulticall();
        primaryMulticall = IMulticall3(_multicall);
        emit PrimaryMulticallSet(_multicall);
    }

    function setFallbackConfig(
        address _fallbackAggregator,
        uint256 _timeout
    ) external onlyOwner {
        fallbackConfig = FallbackConfig({
            fallbackAggregator: _fallbackAggregator,
            fallbackTimeout: _timeout
        });
        emit FallbackConfigUpdated(_fallbackAggregator, _timeout);
    }

    function addEndpoint(
        uint256 _chainId,
        string calldata _rpcUrl,
        uint8 _priority
    ) external onlyOwner {
        if (_chainId == 0) revert InvalidChainId();
        endpoints[_chainId] = ChainEndpoint({
            chainId: _chainId,
            rpcUrl: _rpcUrl,
            priority: _priority,
            enabled: true
        });
        emit EndpointUpdated(_chainId, _rpcUrl);
    }

    function disableEndpoint(uint256 _chainId) external onlyOwner {
        if (_chainId == 0) revert InvalidChainId();
        endpoints[_chainId].enabled = false;
    }

    function enableEndpoint(uint256 _chainId) external onlyOwner {
        if (_chainId == 0) revert InvalidChainId();
        endpoints[_chainId].enabled = true;
    }

    function executeWithFallback(
        IMulticall3.Call3[] calldata calls,
        uint256 chainId
    )
        external
        returns (
            IMulticall3.Result[] memory results,
            bool usedFallback
        )
    {
        if (!endpoints[chainId].enabled) revert EndpointDisabled();

        try primaryMulticall.aggregate3(calls) returns (
            IMulticall3.Result[] memory primaryResults
        ) {
            uint256 successCount = 0;
            for (uint256 i = 0; i < primaryResults.length; i++) {
                if (primaryResults[i].success) successCount++;
            }

            if (successCount >= (primaryResults.length / 2)) {
                return (primaryResults, false);
            }
        } catch {
            emit FallbackTriggered(chainId, "primary_multicall_failed");
        }

        emit FallbackTriggered(chainId, "low_success_rate");

        return (new IMulticall3.Result[](0), true);
    }

    function getEndpoint(uint256 _chainId)
        external
        view
        returns (ChainEndpoint memory)
    {
        if (!endpoints[_chainId].enabled) revert EndpointDisabled();
        return endpoints[_chainId];
    }

    function isEndpointHealthy(uint256 _chainId)
        external
        view
        returns (bool)
    {
        return endpoints[_chainId].enabled;
    }
}

contracts/core/MultiL2EscrowAggregator.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { IMulticall3 } from "../interfaces/IMulticall3.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

struct EscrowQuery {
    uint256 chainId;
    address escrowAddress;
}

struct EscrowBalanceData {
    uint256 chainId;
    address escrowAddress;
    uint256 escrowBalance;
    uint256 userBalance;
    bool active;
    bool success;
}

struct MultiL2EscrowSnapshot {
    address user;
    EscrowBalanceData[] escrows;
    uint256 totalLocked;
    uint256 timestamp;
    uint8 healthyChains;
}

contract MultiL2EscrowAggregator is Ownable {
    IMulticall3 public multicall3;
    address public usdcAddress;

    event QueryExecuted(address indexed user, uint256 escrowCount);
    event MulticallAddressUpdated(address indexed newAddress);
    event USDCAddressUpdated(address indexed newAddress);

    error InvalidMulticallAddress();
    error InvalidUSDCAddress();
    error EmptyEscrowList();
    error CallFailures(uint256 failureCount);

    constructor(address _multicall3, address _usdc) Ownable(msg.sender) {
        if (_multicall3 == address(0)) revert InvalidMulticallAddress();
        if (_usdc == address(0)) revert InvalidUSDCAddress();
        multicall3 = IMulticall3(_multicall3);
        usdcAddress = _usdc;
    }

    function setMulticall3(address _multicall3) external onlyOwner {
        if (_multicall3 == address(0)) revert InvalidMulticallAddress();
        multicall3 = IMulticall3(_multicall3);
        emit MulticallAddressUpdated(_multicall3);
    }

    function setUSDCAddress(address _usdc) external onlyOwner {
        if (_usdc == address(0)) revert InvalidUSDCAddress();
        usdcAddress = _usdc;
        emit USDCAddressUpdated(_usdc);
    }

    function queryEscrows(
        address user,
        EscrowQuery[] calldata escrows
    )
        external
        returns (MultiL2EscrowSnapshot memory snapshot)
    {
        if (escrows.length == 0) revert EmptyEscrowList();

        IMulticall3.Call3[] memory calls = new IMulticall3.Call3[](
            escrows.length * 2
        );

        for (uint256 i = 0; i < escrows.length; i++) {
            uint256 baseIdx = i * 2;

            calls[baseIdx] = IMulticall3.Call3({
                target: escrows[i].escrowAddress,
                callData: abi.encodeWithSignature("balanceOf(address)", user),
                allowFailure: true
            });

            calls[baseIdx + 1] = IMulticall3.Call3({
                target: escrows[i].escrowAddress,
                callData: abi.encodeWithSignature("isActive()"),
                allowFailure: true
            });
        }

        IMulticall3.Result[] memory results = multicall3.aggregate3(calls);

        snapshot.user = user;
        snapshot.timestamp = block.timestamp;
        snapshot.healthyChains = 0;

        EscrowBalanceData[] memory data = new EscrowBalanceData[](
            escrows.length
        );

        for (uint256 i = 0; i < escrows.length; i++) {
            uint256 balanceIdx = i * 2;
            uint256 activeIdx = i * 2 + 1;

            data[i].chainId = escrows[i].chainId;
            data[i].escrowAddress = escrows[i].escrowAddress;
            data[i].success = results[balanceIdx].success && results[activeIdx].success;

            if (data[i].success) {
                data[i].userBalance = abi.decode(results[balanceIdx].returnData, (uint256));
                data[i].active = abi.decode(results[activeIdx].returnData, (bool));

                snapshot.totalLocked += data[i].userBalance;
                snapshot.healthyChains++;
            }
        }

        snapshot.escrows = data;

        emit QueryExecuted(user, escrows.length);

        return snapshot;
    }

    function queryEscrowsWithUSDC(
        address user,
        EscrowQuery[] calldata escrows
    )
        external
        returns (MultiL2EscrowSnapshot memory snapshot)
    {
        if (escrows.length == 0) revert EmptyEscrowList();

        IMulticall3.Call3[] memory calls = new IMulticall3.Call3[](
            escrows.length * 3
        );

        for (uint256 i = 0; i < escrows.length; i++) {
            uint256 baseIdx = i * 3;

            calls[baseIdx] = IMulticall3.Call3({
                target: escrows[i].escrowAddress,
                callData: abi.encodeWithSignature("balanceOf(address)", user),
                allowFailure: true
            });

            calls[baseIdx + 1] = IMulticall3.Call3({
                target: escrows[i].escrowAddress,
                callData: abi.encodeWithSignature("isActive()"),
                allowFailure: true
            });

            calls[baseIdx + 2] = IMulticall3.Call3({
                target: usdcAddress,
                callData: abi.encodeWithSignature("balanceOf(address)", user),
                allowFailure: true
            });
        }

        IMulticall3.Result[] memory results = multicall3.aggregate3(calls);

        snapshot.user = user;
        snapshot.timestamp = block.timestamp;
        snapshot.healthyChains = 0;

        EscrowBalanceData[] memory data = new EscrowBalanceData[](
            escrows.length
        );

        for (uint256 i = 0; i < escrows.length; i++) {
            uint256 balanceIdx = i * 3;
            uint256 activeIdx = i * 3 + 1;

            data[i].chainId = escrows[i].chainId;
            data[i].escrowAddress = escrows[i].escrowAddress;
            data[i].success = results[balanceIdx].success && results[activeIdx].success;

            if (data[i].success) {
                data[i].userBalance = abi.decode(results[balanceIdx].returnData, (uint256));
                data[i].active = abi.decode(results[activeIdx].returnData, (bool));

                snapshot.totalLocked += data[i].userBalance;
                snapshot.healthyChains++;
            }
        }

        snapshot.escrows = data;

        emit QueryExecuted(user, escrows.length);

        return snapshot;
    }
}

