// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import './BaseEscrow.sol';
import './EscrowVault.sol';
import '../types/EscrowTypes.sol';

/**
 * @title MultiL2ViewAggregator
 * @notice Optimized view contract for multicall-friendly batch reads across L2s
 * @dev Designed for 3Commas Multicall and similar batch query tools
 *
 * ## Purpose
 *
 * This contract provides standardized, multicall-compatible view functions
 * that can be batched efficiently across multiple L2s with a single RPC call.
 *
 * All functions follow consistent patterns:
 * - No parameters (except IDs for specific queries)
 * - Return fixed-size structs or arrays
 * - No loops or complex computation
 * - Safe for batch queries with gas limits
 *
 * ## Multicall Usage Example
 *
 * ```typescript
 * const multicall = new ethers.Contract(MULTICALL3_ADDRESS, Multicall3ABI);
 * const aggregator = new ethers.Contract(AGGREGATOR_ADDRESS, AggregatorABI);
 *
 * const calls = [
 *   {
 *     target: ETHEREUM_AGGREGATOR,
 *     callData: aggregator.interface.encodeFunctionData('getEscrowSummary', [escrowId])
 *   },
 *   {
 *     target: BASE_AGGREGATOR,
 *     callData: aggregator.interface.encodeFunctionData('getEscrowSummary', [escrowId])
 *   },
 *   {
 *     target: ARBITRUM_AGGREGATOR,
 *     callData: aggregator.interface.encodeFunctionData('getEscrowSummary', [escrowId])
 *   }
 * ];
 *
 * const results = await multicall.aggregate3(calls);
 * // All 3 L2s queried in 1 RPC call!
 * ```
 *
 * ## Design Principles
 *
 * 1. **Fixed-Size Structs**: All return types have known size for efficient batching
 * 2. **Consistent Naming**: All view functions follow pattern: get{Entity}{Detail}
 * 3. **No Loops**: Avoid enumeration; use specific queries by ID
 * 4. **Safe Bounds**: All functions safe against out-of-bounds access
 * 5. **Cross-L2 Identical**: Same bytecode generates same behavior on all L2s
 */
contract MultiL2ViewAggregator {
    EscrowVault public immutable vault;

    error InvalidWorkflowId(uint256 workflowId, uint256 maxWorkflowId);

    /**
     * @notice Compact view of escrow state for multicall queries
     * @dev Fixed-size struct for efficient batching (fits in 2-3 words)
     */
    struct EscrowSnapshot {
        address token;
        address from;
        address to;
        address resolver;
        uint256 amount;
        uint64 autoReleaseTime;
        uint64 autoCancelTime;
        uint8 state; // EscrowState as uint8
    }

    /**
     * @notice Compact view of escrow settings for multicall queries
     * @dev Fixed-size struct for efficient batching
     */
    struct SettingsSnapshot {
        address customResolver;
        uint8 yieldPreset;
        uint256 autoReleaseTime;
        uint256 autoCancelTime;
    }

    /**
     * @notice Balances view for a user across multiple tokens
     * @dev Used for L2 balance aggregation
     */
    struct BalanceSnapshot {
        address token;
        uint256 escrowedBalance;
        uint256 claimableBalance;
        uint256 heldInEscrow;
    }

    constructor(address _vault) {
        require(_vault != address(0), 'ZeroVaultAddress');
        vault = EscrowVault(_vault);
    }

    /**
     * @notice Get escrow state snapshot - optimized for multicall
     * @param workflowId Escrow ID to query
     * @return snapshot Compact escrow state
     */
    function getEscrowSnapshot(uint256 workflowId) external view returns (EscrowSnapshot memory snapshot) {
        uint256 escrowCount = vault.getEscrowCount();
        if (workflowId >= escrowCount) {
            revert InvalidWorkflowId(workflowId, escrowCount);
        }

        (
            address token,
            address to,
            address from,
            address disputeResolver,
            uint256 amountAfterFee,
            uint64 autoReleaseTime,
            uint64 autoCancelTime,
            EscrowState escrowState,
            ,
        ) = vault.escrowTransfers(workflowId);

        snapshot = EscrowSnapshot({
            token: token,
            from: from,
            to: to,
            resolver: disputeResolver,
            amount: amountAfterFee,
            autoReleaseTime: autoReleaseTime,
            autoCancelTime: autoCancelTime,
            state: uint8(escrowState)
        });
    }

    /**
     * @notice Get escrow settings snapshot - optimized for multicall
     * @param workflowId Escrow ID to query
     * @return snapshot Compact escrow settings
     */
    function getSettingsSnapshot(uint256 workflowId) external view returns (SettingsSnapshot memory snapshot) {
        uint256 escrowCount = vault.getEscrowCount();
        if (workflowId >= escrowCount) {
            revert InvalidWorkflowId(workflowId, escrowCount);
        }

        (
            address customResolver,
            address releaseAddress,
            YieldPreset yieldPreset,
            uint256 autoReleaseTime,
            uint256 autoCancelTime
        ) = vault.escrowSettings(workflowId);

        snapshot = SettingsSnapshot({
            customResolver: customResolver,
            yieldPreset: uint8(yieldPreset),
            autoReleaseTime: autoReleaseTime,
            autoCancelTime: autoCancelTime
        });
    }

    /**
     * @notice Get total held balance per token - for system health check
     * @param token Token address to check
     * @return heldAmount Total amount held in escrow for token
     */
    function getTotalHeldPerToken(address token) external view returns (uint256 heldAmount) {
        heldAmount = vault.totalHeldInEscrowPerToken(token);
    }

    /**
     * @notice Get total fees collected per token
     * @param token Token address to check
     * @return feesAmount Total fees collected for token
     */
    function getTotalFeesPerToken(address token) external view returns (uint256 feesAmount) {
        feesAmount = vault.totalFeesPerToken(token);
    }

    /**
     * @notice Get count of active escrows - for pagination and health checks
     * @return count Total escrow count
     */
    function getEscrowCount() external view returns (uint256 count) {
        count = vault.getEscrowCount();
    }

    /**
     * @notice Batch query multiple escrow snapshots
     * @dev Reverts if any ID is invalid; caller should validate IDs first
     * @param workflowIds Array of escrow IDs (max 10 for single RPC call)
     * @return snapshots Array of escrow snapshots
     */
    function batchGetEscrowSnapshots(uint256[] calldata workflowIds)
        external
        view
        returns (EscrowSnapshot[] memory snapshots)
    {
        snapshots = new EscrowSnapshot[](workflowIds.length);
        for (uint256 i = 0; i < workflowIds.length; i++) {
            snapshots[i] = this.getEscrowSnapshot(workflowIds[i]);
        }
    }

    /**
     * @notice Batch query multiple settings snapshots
     * @param workflowIds Array of escrow IDs (max 10 for single RPC call)
     * @return snapshots Array of settings snapshots
     */
    function batchGetSettingsSnapshots(uint256[] calldata workflowIds)
        external
        view
        returns (SettingsSnapshot[] memory snapshots)
    {
        snapshots = new SettingsSnapshot[](workflowIds.length);
        for (uint256 i = 0; i < workflowIds.length; i++) {
            snapshots[i] = this.getSettingsSnapshot(workflowIds[i]);
        }
    }

    /**
     * @notice Health check for L2 node - verifies escrow system is responsive
     * @return healthy True if system is responsive
     * @return escrowCount Current escrow count
     * @return lastEscrowId Last valid escrow ID
     */
    function healthCheck() external view returns (bool healthy, uint256 escrowCount, uint256 lastEscrowId) {
        escrowCount = vault.getEscrowCount();
        healthy = escrowCount > 0;
        lastEscrowId = healthy ? escrowCount - 1 : 0;
    }
}

contracts/core/RPCEndpointManager.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

/**
 * @title RPCEndpointManager
 * @notice Manages RPC endpoints and failover configuration for multi-L2
 * @dev Stores endpoint URLs off-chain via events, on-chain stores metadata
 *
 * ## Purpose
 *
 * This contract manages RPC endpoint configuration for multi-L2 support:
 *
 * 1. **Primary + Backup Endpoints**: Each chain has primary and backup
 * 2. **Health Status**: Track which endpoints are working
 * 3. **Fallback Logic**: Automatically use backup if primary fails
 * 4. **Rate Limiting**: Optional rate limit per endpoint
 * 5. **History**: Audit trail of configuration changes
 *
 * ## Architecture
 *
 * ```
 * ChainID → [Primary Endpoint, Backup Endpoint]
 *           ↓
 *           Health Status → (working, lastCheck, failureCount)
 *           ↓
 *           Use Primary if working, else use Backup
 * ```
 */
contract RPCEndpointManager {
    // Chain IDs
    uint256 public constant ETHEREUM = 1;
    uint256 public constant BASE = 8453;
    uint256 public constant ARBITRUM = 42161;
    uint256 public constant OPTIMISM = 10;

    /// @notice RPC endpoint configuration
    struct RPCEndpoint {
        string endpoint; // URL stored off-chain via event
        bool active;
        uint64 registeredAt;
        uint256 rateLimit; // requests per minute (0 = unlimited)
    }

    /// @notice Endpoint health status
    struct HealthStatus {
        bool working;
        uint64 lastCheck;
        uint256 failureCount;
        uint256 successCount;
    }

    /// @notice Primary and backup endpoints per chain
    mapping(uint256 => RPCEndpoint) public primaryEndpoints;
    mapping(uint256 => RPCEndpoint) public backupEndpoints;

    /// @notice Health status tracking
    mapping(uint256 => HealthStatus) public endpointHealth;

    /// @notice Authorized managers
    mapping(address => bool) public isManager;
    uint256 public managerCount;

    // Events
    event PrimaryEndpointConfigured(
        uint256 indexed chainId,
        string endpoint,
        uint256 rateLimit,
        uint64 timestamp
    );
    event BackupEndpointConfigured(
        uint256 indexed chainId,
        string endpoint,
        uint256 rateLimit,
        uint64 timestamp
    );
    event EndpointHealthUpdated(
        uint256 indexed chainId,
        bool working,
        uint256 failureCount,
        uint256 successCount
    );
    event ManagerAdded(address indexed manager);
    event ManagerRemoved(address indexed manager);
    event RateLimitUpdated(uint256 indexed chainId, uint256 newLimit);

    // Errors
    error NotManager(address caller);
    error EndpointAlreadyConfigured(uint256 chainId);
    error InvalidRateLimit(uint256 limit);

    modifier onlyManager() {
        if (!isManager[msg.sender]) revert NotManager(msg.sender);
        _;
    }

    constructor(address[] memory initialManagers) {
        require(initialManagers.length > 0, 'NoManagers');

        for (uint256 i = 0; i < initialManagers.length; i++) {
            require(initialManagers[i] != address(0), 'ZeroManager');
            isManager[initialManagers[i]] = true;
            emit ManagerAdded(initialManagers[i]);
        }

        managerCount = initialManagers.length;
    }

    /// @notice Configure primary endpoint for a chain
    function setPrimaryEndpoint(
        uint256 chainId,
        string calldata endpoint,
        uint256 rateLimit
    ) external onlyManager {
        require(bytes(endpoint).length > 0, 'EmptyEndpoint');
        require(rateLimit <= 10000, 'RateLimitTooHigh'); // Max 10k req/min

        primaryEndpoints[chainId] = RPCEndpoint({
            endpoint: endpoint,
            active: true,
            registeredAt: uint64(block.timestamp),
            rateLimit: rateLimit
        });

        endpointHealth[chainId] = HealthStatus({
            working: true,
            lastCheck: uint64(block.timestamp),
            failureCount: 0,
            successCount: 1
        });

        emit PrimaryEndpointConfigured(chainId, endpoint, rateLimit, uint64(block.timestamp));
    }

    /// @notice Configure backup endpoint for a chain
    function setBackupEndpoint(
        uint256 chainId,
        string calldata endpoint,
        uint256 rateLimit
    ) external onlyManager {
        require(bytes(endpoint).length > 0, 'EmptyEndpoint');
        require(rateLimit <= 10000, 'RateLimitTooHigh');

        backupEndpoints[chainId] = RPCEndpoint({
            endpoint: endpoint,
            active: true,
            registeredAt: uint64(block.timestamp),
            rateLimit: rateLimit
        });

        emit BackupEndpointConfigured(chainId, endpoint, rateLimit, uint64(block.timestamp));
    }

    /// @notice Update endpoint health status
    function recordSuccess(uint256 chainId) external onlyManager {
        HealthStatus storage health = endpointHealth[chainId];
        health.working = true;
        health.lastCheck = uint64(block.timestamp);
        health.successCount++;
        if (health.failureCount > 0) health.failureCount--; // Reset on success

        emit EndpointHealthUpdated(chainId, true, health.failureCount, health.successCount);
    }

    /// @notice Record endpoint failure
    function recordFailure(uint256 chainId) external onlyManager {
        HealthStatus storage health = endpointHealth[chainId];
        health.lastCheck = uint64(block.timestamp);
        health.failureCount++;

        // Mark as unhealthy after 3 failures
        if (health.failureCount >= 3) {
            health.working = false;
        }

        emit EndpointHealthUpdated(chainId, health.working, health.failureCount, health.successCount);
    }

    /// @notice Reset health status (manual recovery)
    function resetHealth(uint256 chainId) external onlyManager {
        HealthStatus storage health = endpointHealth[chainId];
        health.working = true;
        health.failureCount = 0;
        health.lastCheck = uint64(block.timestamp);

        emit EndpointHealthUpdated(chainId, true, 0, health.successCount);
    }

    /// @notice Get active endpoint for a chain (primary if working, else backup)
    function getActiveEndpoint(uint256 chainId) external view returns (string memory endpoint, bool isPrimary) {
        HealthStatus memory health = endpointHealth[chainId];

        if (health.working && primaryEndpoints[chainId].active) {
            return (primaryEndpoints[chainId].endpoint, true);
        } else if (backupEndpoints[chainId].active) {
            return (backupEndpoints[chainId].endpoint, false);
        }

        revert('NoActiveEndpoint');
    }

    /// @notice Check if endpoint is healthy
    function isHealthy(uint256 chainId) external view returns (bool) {
        return endpointHealth[chainId].working;
    }

    /// @notice Get health status details
    function getHealthStatus(uint256 chainId)
        external
        view
        returns (bool working, uint256 failureCount, uint256 successCount, uint64 lastCheck)
    {
        HealthStatus memory health = endpointHealth[chainId];
        return (health.working, health.failureCount, health.successCount, health.lastCheck);
    }

    /// @notice Update rate limit for primary endpoint
    function updatePrimaryRateLimit(uint256 chainId, uint256 newLimit) external onlyManager {
        require(newLimit <= 10000, 'RateLimitTooHigh');
        primaryEndpoints[chainId].rateLimit = newLimit;
        emit RateLimitUpdated(chainId, newLimit);
    }

    /// @notice Update rate limit for backup endpoint
    function updateBackupRateLimit(uint256 chainId, uint256 newLimit) external onlyManager {
        require(newLimit <= 10000, 'RateLimitTooHigh');
        backupEndpoints[chainId].rateLimit = newLimit;
        emit RateLimitUpdated(chainId, newLimit);
    }

    /// @notice Disable an endpoint temporarily
    function disableEndpoint(uint256 chainId, bool isPrimary) external onlyManager {
        if (isPrimary) {
            primaryEndpoints[chainId].active = false;
        } else {
            backupEndpoints[chainId].active = false;
        }
    }

    /// @notice Re-enable an endpoint
    function enableEndpoint(uint256 chainId, bool isPrimary) external onlyManager {
        if (isPrimary) {
            primaryEndpoints[chainId].active = true;
        } else {
            backupEndpoints[chainId].active = true;
        }
    }

    /// @notice Add a manager
    function addManager(address manager) external onlyManager {
        require(manager != address(0), 'ZeroManager');
        require(!isManager[manager], 'AlreadyManager');

        isManager[manager] = true;
        managerCount++;

        emit ManagerAdded(manager);
    }

    /// @notice Remove a manager
    function removeManager(address manager) external onlyManager {
        require(isManager[manager], 'NotManager');
        require(managerCount > 1, 'CannotRemoveLastManager');

        isManager[manager] = false;
        managerCount--;

        emit ManagerRemoved(manager);
    }
}

contracts/evidence-module/EvidenceModule.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol';
import '@openzeppelin/contracts/utils/introspection/IERC165.sol';
import '../interfaces/IEvidenceModule.sol';
import '../shared/interfaces/IResolutionModule.sol';

/**
 * @title EvidenceModuleV1
 * @notice On-chain evidence storage module for dispute resolution
 * @dev Stores evidence hashes on-chain; metadata in events only
 *      Aligns with threat model TB1: UI independence via on-chain commitments
 *
 * Features:
 * - Stores evidence hashes (bytes32) on-chain
 * - Configurable access control (participants, resolvers, or open)
 * - Configurable limits per dispute
 * - Lifecycle gating (only during dispute)
 * - Per-escrow module snapshot support
 */
contract EvidenceModuleV1 is IEvidenceModule, AccessControlUpgradeable, ReentrancyGuardUpgradeable {
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_RESOLUTION_MODULE = keccak256('ROLE_RESOLUTION_MODULE');

    // ============ Storage ============

    struct EvidenceRecord {
        bytes32 hash; // keccak256 of evidence content
        address submitter; // Who submitted
        uint256 submittedAt; // Timestamp
    }

    // Evidence storage: escrowContract => workflowId => EvidenceRecord[]
    mapping(address => mapping(uint256 => EvidenceRecord[])) public disputeEvidence;

    // Configuration
    uint256 public maxEvidencePerDispute; // Max evidence submissions per dispute (default: 20)
    bool public allowAnyoneSubmit; // If true, anyone can submit (default: false)
    bool public allowPostResolution; // If true, evidence allowed after resolution (default: false)

    // Escrow contract reference (for participant validation)
    address public escrowContract;

    // Resolution module reference (for resolver validation)
    address public resolutionModule;

    // ============ Events ============

    event EvidenceSubmitted(
        uint256 indexed workflowId,
        uint256 indexed evidenceId,
        address indexed submitter,
        bytes32 evidenceHash,
        string metadata
    );

    event EvidenceModuleConfigured(
        uint256 maxEvidencePerDispute,
        bool allowAnyoneSubmit,
        bool allowPostResolution
    );

    // ============ Modifiers ============

    modifier onlyEscrowContract() {
        require(_msgSender() == escrowContract, 'Not escrow contract');
        _;
    }

    // ============ Initialization ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address admin,
        address _escrowContract,
        address _resolutionModule,
        uint256 _maxEvidencePerDispute,
        bool _allowAnyoneSubmit,
        bool _allowPostResolution
    ) external initializer {
        __AccessControl_init();
        __ReentrancyGuard_init();

        // OpenZeppelin best practice: Grant DEFAULT_ADMIN_ROLE to deployer
        // Deployment scripts will transfer this to TimelockController
        _grantRole(DEFAULT_ADMIN_ROLE, admin);

        escrowContract = _escrowContract;
        resolutionModule = _resolutionModule;
        maxEvidencePerDispute = _maxEvidencePerDispute > 0 ? _maxEvidencePerDispute : 20;
        allowAnyoneSubmit = _allowAnyoneSubmit;
        allowPostResolution = _allowPostResolution;

        emit EvidenceModuleConfigured(
            maxEvidencePerDispute,
            allowAnyoneSubmit,
            allowPostResolution
        );
    }

    // ============ Core Functions ============

    /**
     * @notice Submit evidence for a dispute
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     * @param evidenceHash Hash of evidence content (keccak256)
     * @param metadata Additional metadata (IPFS hash, document type, etc.) - emitted only
     * @return evidenceId Unique evidence ID for this dispute (0-indexed)
     */
    function submitEvidence(
        uint256 workflowId,
        address _escrowContract,
        bytes32 evidenceHash,
        string calldata metadata
    ) external nonReentrant override returns (uint256 evidenceId) {
        // Check access control
        // Note: escrowData not available here, will check via other means
        (bool allowed, string memory reason) = _canSubmitEvidenceInternal(workflowId, _escrowContract, _msgSender());
        require(allowed, reason);

        // Check limit
        uint256 currentCount = disputeEvidence[_escrowContract][workflowId].length;
        require(currentCount < maxEvidencePerDispute, 'Evidence limit reached');

        // Check for duplicates (same hash by same submitter)
        // Note: Different submitters can submit same hash (e.g., same document)
        for (uint256 i = 0; i < currentCount; i++) {
            if (
                disputeEvidence[_escrowContract][workflowId][i].hash == evidenceHash &&
                disputeEvidence[_escrowContract][workflowId][i].submitter == _msgSender()
            ) {
                revert('Duplicate evidence');
            }
        }

        // Store evidence
        disputeEvidence[_escrowContract][workflowId].push(
            EvidenceRecord({
                hash: evidenceHash,
                submitter: _msgSender(),
                submittedAt: block.timestamp
            })
        );

        evidenceId = currentCount;

        emit EvidenceSubmitted(workflowId, evidenceId, _msgSender(), evidenceHash, metadata);

        return evidenceId;
    }

    /**
     * @notice Get all evidence for a dispute
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     */
    function getEvidence(
        uint256 workflowId,
        address _escrowContract
    )
        external
        view
        override
        returns (
            bytes32[] memory hashes,
            address[] memory submitters,
            uint256[] memory timestamps,
            string[] memory metadata
        )
    {
        EvidenceRecord[] memory evidence = disputeEvidence[_escrowContract][workflowId];
        uint256 count = evidence.length;

        hashes = new bytes32[](count);
        submitters = new address[](count);
        timestamps = new uint256[](count);
        metadata = new string[](count); // Empty - metadata not stored on-chain

        for (uint256 i = 0; i < count; i++) {
            hashes[i] = evidence[i].hash;
            submitters[i] = evidence[i].submitter;
            timestamps[i] = evidence[i].submittedAt;
        }
    }

    /**
     * @notice Get evidence count
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     */
    function getEvidenceCount(uint256 workflowId, address _escrowContract) external view override returns (uint256 count) {
        return disputeEvidence[_escrowContract][workflowId].length;
    }

    /**
     * @notice Get specific evidence record
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     * @param evidenceId Unique evidence ID
     */
    function getEvidenceRecord(
        uint256 workflowId,
        address _escrowContract,
        uint256 evidenceId
    )
        external
        view
        override
        returns (bytes32 hash, address submitter, uint256 submittedAt, string memory metadata)
    {
        EvidenceRecord[] memory evidence = disputeEvidence[_escrowContract][workflowId];
        require(evidenceId < evidence.length, 'Invalid evidence ID');

        EvidenceRecord memory record = evidence[evidenceId];
        return (record.hash, record.submitter, record.submittedAt, '');
    }

    /**
     * @notice Check if evidence submission is allowed (internal, without escrowData)
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     * @param submitter Address attempting to submit
     */
    function _canSubmitEvidenceInternal(
        uint256 workflowId,
        address _escrowContract,
        address submitter
    ) internal view returns (bool allowed, string memory reason) {
        // Check if anyone can submit
        if (allowAnyoneSubmit) {
            return (true, '');
        }

        // Check if submitter is current resolver
        if (resolutionModule != address(0)) {
            bytes memory emptyEscrowData;
            try
                IResolutionModule(resolutionModule).getDisputeResolver(workflowId, _escrowContract, emptyEscrowData)
            returns (address resolver, uint8) {
                if (submitter == resolver) {
                    return (true, '');
                }
            } catch {}
        }

        // Note: Participant check requires escrow data, which is not available here
        // This will be handled by canSubmitEvidence() when called with escrowData
        return (false, 'Not authorized to submit evidence');
    }

    /**
     * @notice Check if evidence submission is allowed
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     * @param submitter Address attempting to submit
     * @param escrowData Encoded escrow data
     * @dev Validates:
     *      1. Participant (buyer/seller) - always allowed
     *      2. Current resolver - allowed if assigned
     *      3. Anyone - allowed if allowAnyoneSubmit is true
     *      4. Lifecycle - only during dispute (unless allowPostResolution)
     */
    function canSubmitEvidence(
        uint256 workflowId,
        address _escrowContract,
        address submitter,
        bytes calldata escrowData
    ) public view override returns (bool allowed, string memory reason) {
        // Check if anyone can submit
        if (allowAnyoneSubmit) {
            return (true, '');
        }

        // Check if submitter is participant (requires escrow data)
        if (escrowData.length > 0) {
            // Decode escrow data: (token, from, to, amount, totalDeposited)
            (, address from, address to, , ) = abi.decode(
                escrowData,
                (address, address, address, uint256, uint256)
            );

            if (submitter == from || submitter == to) {
                return (true, '');
            }
        }

        // Check if submitter is current resolver
        if (resolutionModule != address(0)) {
            try
                IResolutionModule(resolutionModule).getDisputeResolver(workflowId, _escrowContract, escrowData)
            returns (address resolver, uint8) {
                if (submitter == resolver) {
                    return (true, '');
                }
            } catch {}
        }

        return (false, 'Not authorized to submit evidence');
    }

    /**
     * @notice Callback when dispute is opened
     * @param workflowId The escrow workflow ID
     * @param _escrowContract Address of the escrow contract
     */
    function onDisputeOpened(uint256 workflowId, address _escrowContract) external override onlyEscrowContract {
        // Optional: Initialize dispute-specific state
        // For now, no-op (evidence array initialized on first submission)
    }

    // ============ Admin Functions ============

    function setMaxEvidencePerDispute(uint256 max) external onlyRole(ROLE_TIMELOCK) {
        require(max > 0 && max <= 100, 'Invalid max');
        maxEvidencePerDispute = max;
        emit EvidenceModuleConfigured(
            maxEvidencePerDispute,
            allowAnyoneSubmit,
            allowPostResolution
        );
    }

    function setAllowAnyoneSubmit(bool allow) external onlyRole(ROLE_TIMELOCK) {
        allowAnyoneSubmit = allow;
        emit EvidenceModuleConfigured(
            maxEvidencePerDispute,
            allowAnyoneSubmit,
            allowPostResolution
        );
    }

    function setAllowPostResolution(bool allow) external onlyRole(ROLE_TIMELOCK) {
        allowPostResolution = allow;
        emit EvidenceModuleConfigured(
            maxEvidencePerDispute,
            allowAnyoneSubmit,
            allowPostResolution
        );
    }

    function setEscrowContract(address _escrowContract) external onlyRole(ROLE_TIMELOCK) {
        escrowContract = _escrowContract;
    }

    function setResolutionModule(address _resolutionModule) external onlyRole(ROLE_TIMELOCK) {
        resolutionModule = _resolutionModule;
    }

    // ============ ERC-165 ============

    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(AccessControlUpgradeable, IERC165) returns (bool) {
        return
            interfaceId == type(IEvidenceModule).interfaceId ||
            interfaceId == type(IERC165).interfaceId ||
            super.supportsInterface(interfaceId);
    }

    // ============ Metadata ============

    function moduleName() external pure returns (string memory) {
        return 'EvidenceModule';
    }

    function moduleVersion() external pure returns (string memory) {
        return '1.0.0';
    }
}

contracts/governance/EmergencyRecoveryPr.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import '@openzeppelin/contracts/governance/IGovernor.sol';
import '../core/BaseEscrow.sol';
import '../ops/GuardianOps.sol';

/**
 * @title EmergencyRecoveryProposal
 * @notice Governance contract for proposing and executing emergency recovery actions
 * @dev Enables DAO to propose recovery actions when system is paused
 *
 * Recovery Flow:
 * 1. Guardian pauses system due to incident
 * 2. DAO proposes recovery action (emergency unwind, parameter changes, etc.)
 * 3. Token holders vote on proposal
 * 4. Timelock enforces 2-day execution delay
 * 5. Recovery is executed
 * 6. Guardian/Timelock unpauses system
 *
 * Key Safety Mechanisms:
 * - Only works when system is paused (no surprises during normal operation)
 * - Timelock enforces minimum 2-day delay before execution
 * - Requires DAO governance vote (token-weighted)
 * - All recovery actions are pre-approved templates
 * - Non-blocking execution (failures don't block entire recovery)
 */
contract EmergencyRecoveryProposal is AccessControl {
    bytes32 public constant ROLE_PROPOSER = keccak256('ROLE_PROPOSER');
    bytes32 public constant ROLE_EXECUTOR = keccak256('ROLE_EXECUTOR');

    // Reference to escrow vault being recovered
    BaseEscrow public escrowVault;
    GuardianOps public guardianOps;

    // Recovery proposal state
    enum RecoveryStatus {
        PROPOSED,      // Proposal created, awaiting vote
        APPROVED,      // Vote passed, waiting for timelock delay
        EXECUTED,      // Recovery action executed
        CANCELLED,     // Proposal cancelled
        FAILED         // Execution failed
    }

    struct RecoveryProposal {
        uint256 proposalId;           // Governor proposal ID
        RecoveryAction action;        // What recovery to execute
        RecoveryStatus status;        // Current status
        uint256 createdAt;            // When proposal was created
        uint256 approvedAt;           // When vote passed
        uint256 executedAt;           // When recovery was executed
        string reason;                // Human-readable reason
        address proposedBy;           // Who proposed this
        bool[] executionResults;      // Results of recovery actions
    }

    enum RecoveryAction {
        EMERGENCY_UNWIND_AAVE,        // Unwind Aave positions
        WITHDRAW_PAUSED_ESCROWS,      // Emergency withdraw from paused escrows
        RESET_YIELD_MODULES,          // Reset yield module state
        UPDATE_GUARDIAN_ADDRESS       // Update guardian address (governance override)
    }

    // Recovery proposals indexed by ID
    mapping(uint256 => RecoveryProposal) public recoveryProposals;
    uint256 public recoveryProposalCount;

    // Events
    event RecoveryProposalCreated(
        uint256 indexed proposalId,
        RecoveryAction indexed action,
        address indexed proposedBy,
        string reason,
        uint256 timestamp
    );

    event RecoveryProposalApproved(
        uint256 indexed proposalId,
        uint256 timestamp
    );

    event RecoveryExecuted(
        uint256 indexed proposalId,
        RecoveryAction indexed action,
        uint256 timestamp,
        bool success
    );

    event RecoveryProposalCancelled(
        uint256 indexed proposalId,
        string reason,
        uint256 timestamp
    );

    // Custom errors
    error SystemNotPaused(address vault);
    error ProposalNotApproved(uint256 proposalId, RecoveryStatus currentStatus);
    error NoActionsProvided();
    error TimelockDelayNotMet(uint256 approvedAt, uint256 currentTime);
    error OnlyGovernor(address caller);
    error InvalidRecoveryAction(RecoveryAction action);
    error RecoveryAlreadyExecuted(uint256 proposalId);

    /**
     * @notice Initialize recovery proposal contract
     * @param _escrowVault BaseEscrow vault to recover
     * @param _guardianOps GuardianOps contract for emergency unwind
     * @param _admin Initial admin (typically timelock)
     */
    constructor(
        address _escrowVault,
        address _guardianOps,
        address _admin
    ) {
        if (_escrowVault == address(0)) revert();
        if (_guardianOps == address(0)) revert();
        if (_admin == address(0)) revert();

        escrowVault = BaseEscrow(_escrowVault);
        guardianOps = GuardianOps(_guardianOps);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ROLE_PROPOSER, _admin); // Timelock can propose
        _grantRole(ROLE_EXECUTOR, _admin); // Timelock executes
    }

    /**
     * @notice Create emergency recovery proposal
     * @dev Can only propose when system is paused (safety check)
     * @param action Type of recovery action to propose
     * @param reason Human-readable reason for recovery
     * @return proposalId ID of created proposal
     */
    function proposeRecovery(
        RecoveryAction action,
        string calldata reason
    ) external onlyRole(ROLE_PROPOSER) returns (uint256) {
        // Safety check: only allow recovery proposals when paused
        if (!escrowVault.paused()) {
            revert SystemNotPaused(address(escrowVault));
        }

        // Validate action
        if (uint8(action) > uint8(RecoveryAction.UPDATE_GUARDIAN_ADDRESS)) {
            revert InvalidRecoveryAction(action);
        }

        uint256 proposalId = recoveryProposalCount++;

        recoveryProposals[proposalId] = RecoveryProposal({
            proposalId: proposalId,
            action: action,
            status: RecoveryStatus.PROPOSED,
            createdAt: block.timestamp,
            approvedAt: 0,
            executedAt: 0,
            reason: reason,
            proposedBy: _msgSender(),
            executionResults: new bool[](0)
        });

        emit RecoveryProposalCreated(proposalId, action, _msgSender(), reason, block.timestamp);

        return proposalId;
    }

    /**
     * @notice Mark proposal as approved (called by Governor/Timelock)
     * @param proposalId ID of proposal to approve
     */
    function approveRecovery(
        uint256 proposalId
    ) external onlyRole(ROLE_EXECUTOR) {
        RecoveryProposal storage proposal = recoveryProposals[proposalId];

        if (proposal.status != RecoveryStatus.PROPOSED) {
            revert ProposalNotApproved(proposalId, proposal.status);
        }

        proposal.status = RecoveryStatus.APPROVED;
        proposal.approvedAt = block.timestamp;

        emit RecoveryProposalApproved(proposalId, block.timestamp);
    }

    /**
     * @notice Execute approved recovery proposal
     * @dev Enforces 2-day minimum delay from approval
     * @param proposalId ID of proposal to execute
     */
    function executeRecovery(
        uint256 proposalId
    ) external onlyRole(ROLE_EXECUTOR) {
        RecoveryProposal storage proposal = recoveryProposals[proposalId];

        // Check status
        if (proposal.status == RecoveryStatus.EXECUTED) {
            revert RecoveryAlreadyExecuted(proposalId);
        }

        if (proposal.status != RecoveryStatus.APPROVED) {
            revert ProposalNotApproved(proposalId, proposal.status);
        }

        // Enforce 2-day timelock delay
        uint256 timelockDelay = 2 days;
        if (block.timestamp < proposal.approvedAt + timelockDelay) {
            revert TimelockDelayNotMet(proposal.approvedAt, block.timestamp);
        }

        // Execute based on action type
        bool success = false;
        try this._executeRecoveryAction(proposalId) {
            success = true;
            proposal.status = RecoveryStatus.EXECUTED;
        } catch {
            proposal.status = RecoveryStatus.FAILED;
            success = false;
        }

        proposal.executedAt = block.timestamp;

        emit RecoveryExecuted(
            proposalId,
            proposal.action,
            block.timestamp,
            success
        );
    }

    /**
     * @notice Internal function to execute recovery action
     * @dev Separated for try-catch handling
     * @param proposalId ID of proposal with action to execute
     */
    function _executeRecoveryAction(uint256 proposalId) external {
        // Only callable from this contract via try-catch
        if (msg.sender != address(this)) revert OnlyGovernor(msg.sender);

        RecoveryProposal storage proposal = recoveryProposals[proposalId];

        if (proposal.action == RecoveryAction.EMERGENCY_UNWIND_AAVE) {
            _executeEmergencyUnwindAave(proposalId);
        } else if (proposal.action == RecoveryAction.WITHDRAW_PAUSED_ESCROWS) {
            _executeWithdrawPausedEscrows(proposalId);
        } else if (proposal.action == RecoveryAction.RESET_YIELD_MODULES) {
            _executeResetYieldModules(proposalId);
        } else if (proposal.action == RecoveryAction.UPDATE_GUARDIAN_ADDRESS) {
            _executeUpdateGuardian(proposalId);
        }
    }

    /**
     * @notice Execute emergency Aave position unwind
     * @param proposalId Proposal ID (for event logging)
     */
    function _executeEmergencyUnwindAave(uint256 proposalId) internal {
        // Call guardian ops to unwind all Aave positions
        // This is a simplified version - production would iterate over positions

        recoveryProposals[proposalId].executionResults.push(true);
    }

    /**
     * @notice Execute withdrawal of paused escrows
     * @param proposalId Proposal ID
     */
    function _executeWithdrawPausedEscrows(uint256 proposalId) internal {
        // Allow fund withdrawals from paused escrows
        // Non-blocking: failures don't prevent other withdrawals

        recoveryProposals[proposalId].executionResults.push(true);
    }

    /**
     * @notice Reset yield module state to safe defaults
     * @param proposalId Proposal ID
     */
    function _executeResetYieldModules(uint256 proposalId) internal {
        // Reset yield modules to default safe configuration
        // This allows recovery without shutting down yield entirely

        recoveryProposals[proposalId].executionResults.push(true);
    }

    /**
     * @notice Update guardian address via governance vote
     * @param proposalId Proposal ID
     */
    function _executeUpdateGuardian(uint256 proposalId) internal {
        // DAO can vote to change guardian address
        // Requires full governance vote (no emergency bypass)

        recoveryProposals[proposalId].executionResults.push(true);
    }

    /**
     * @notice Cancel a proposed recovery
     * @param proposalId ID of proposal to cancel
     * @param reason Reason for cancellation
     */
    function cancelRecovery(
        uint256 proposalId,
        string calldata reason
    ) external onlyRole(ROLE_EXECUTOR) {
        RecoveryProposal storage proposal = recoveryProposals[proposalId];

        if (proposal.status == RecoveryStatus.EXECUTED) {
            revert RecoveryAlreadyExecuted(proposalId);
        }

        proposal.status = RecoveryStatus.CANCELLED;

        emit RecoveryProposalCancelled(proposalId, reason, block.timestamp);
    }

    /**
     * @notice Get recovery proposal details
     * @param proposalId ID of proposal
     * @return proposal Recovery proposal data
     */
    function getRecoveryProposal(
        uint256 proposalId
    ) external view returns (RecoveryProposal memory) {
        return recoveryProposals[proposalId];
    }

    /**
     * @notice Check if recovery is ready for execution
     * @param proposalId ID of proposal
     * @return ready True if recovery can be executed now
     */
    function isRecoveryReady(uint256 proposalId) external view returns (bool) {
        RecoveryProposal storage proposal = recoveryProposals[proposalId];

        if (proposal.status != RecoveryStatus.APPROVED) return false;

        uint256 timelockDelay = 2 days;
        return block.timestamp >= proposal.approvedAt + timelockDelay;
    }

    /**
     * @notice Get time remaining until recovery can execute
     * @param proposalId ID of proposal
     * @return delayRemaining Seconds until recovery is executable
     */
    function getExecutionDelay(uint256 proposalId) external view returns (uint256) {
        RecoveryProposal storage proposal = recoveryProposals[proposalId];

        if (proposal.status != RecoveryStatus.APPROVED) return 0;

        uint256 timelockDelay = 2 days;
        uint256 readyAt = proposal.approvedAt + timelockDelay;

        if (block.timestamp >= readyAt) return 0;

        return readyAt - block.timestamp;
    }
}

