// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/governance/Governor.sol';
import '@openzeppelin/contracts/governance/extensions/GovernorSettings.sol';
import '@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol';
import '@openzeppelin/contracts/governance/extensions/GovernorVotes.sol';
import '@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol';
import '@openzeppelin/contracts/governance/TimelockController.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';

/**
 * @title GovGovernor
 * @notice OpenZeppelin Governor with TimelockControl for Sew Protocol DAO
 * @dev Combines multiple Governor extensions:
 * - GovernorSettings: voting delay, voting period, proposal threshold
 * - GovernorVotes: token-weighted voting
 * - GovernorTimelockControl: execution via TimelockController
 *
 * Quorum Calculation:
 * - Launch configuration uses an absolute quorum amount (e.g., 4,000,000 SEW).
 * - This avoids ambiguity around "circulating supply" definitions for quorum during launch.
 * - Non-circulating addresses are still tracked for transparency/APIs and future governance upgrades.
 *
 * Non-Circulating Token Tracking:
 * - Tracks addresses that hold non-circulating tokens (vesting, treasury, etc.)
 * - Used for external APIs (CoinGecko, CoinMarketCap) and transparency
 * - getCirculatingSupply() provides accurate circulating supply for reporting
 * - Can be migrated to circulating-based quorum later if desired (without losing tracking data)
 *
 * Configuration:
 * - Voting delay: 1 block (configurable, longer for mainnet)
 * - Voting period: ~1 week (configurable)
 * - Proposal threshold: 500k tokens (0.05% of supply, configurable)
 * - Quorum: Absolute amount (e.g., 4M tokens, configurable via governance)
 * - Timelock: 48h delay for all executions
 */
contract GovGovernor is
    Governor,
    GovernorSettings,
    GovernorCountingSimple,
    GovernorVotes,
    GovernorTimelockControl
{
    /// @notice Maximum number of non-circulating addresses (prevents DoS)
    uint256 public constant MAX_NON_CIRCULATING_ADDRESSES = 100;

    /// @notice Mapping of addresses that are considered non-circulating
    mapping(address => bool) public nonCirculatingAddresses;

    /// @notice Array of non-circulating addresses (for iteration)
    address[] public nonCirculatingAddressesList;

    /// @notice Event emitted when a non-circulating address is added
    event NonCirculatingAddressAdded(address indexed addr);

    /// @notice Event emitted when a non-circulating address is removed
    event NonCirculatingAddressRemoved(address indexed addr);

    /// @notice Absolute quorum amount in token units (e.g., 4,000,000e18 for 4M tokens).
    /// @dev Kept as `absoluteQuorum` for backwards compatibility with earlier naming.
    uint256 public absoluteQuorum;

    /// @notice Event emitted when absolute quorum amount is updated
    event AbsoluteQuorumUpdated(uint256 oldQuorum, uint256 newQuorum);

    // Custom errors
    error QuorumMustBePositive();
    error TooManyInitialAddresses(uint256 length, uint256 max);
    error ZeroAddress();
    error DuplicateAddress(address addr);
    error MaxAddressesReached();
    error AddressNotInList(address addr);
    error OnlyTimelock(address caller, address timelock);

    /**
     * @notice Deploy Governor with all extensions
     * @param token ERC20Votes token address (SewToken)
     * @param timelock TimelockController contract instance
     * @param votingDelayBlocks Voting delay in blocks
     * @param votingPeriodBlocks Voting period in blocks
     * @param proposalThresholdTokens Minimum tokens needed to propose
     * @param absoluteQuorumTokens Absolute quorum amount in token units (e.g., 4,000,000e18 for 4M tokens)
     * @param initialNonCirculatingAddresses Initial addresses to track for transparency/APIs (e.g., vesting contracts)
     */
    constructor(
        address token,
        TimelockController timelock,
        uint48 votingDelayBlocks,
        uint32 votingPeriodBlocks,
        uint256 proposalThresholdTokens,
        uint256 absoluteQuorumTokens,
        address[] memory initialNonCirculatingAddresses
    )
        Governor('Sew Protocol DAO')
        GovernorSettings(votingDelayBlocks, votingPeriodBlocks, proposalThresholdTokens)
        GovernorVotes(IVotes(token))
        GovernorTimelockControl(timelock)
    {
        if (absoluteQuorumTokens == 0) revert QuorumMustBePositive();
        absoluteQuorum = absoluteQuorumTokens;
        // Add initial non-circulating addresses
        uint256 length = initialNonCirculatingAddresses.length;
        if (length > MAX_NON_CIRCULATING_ADDRESSES) {
            revert TooManyInitialAddresses(length, MAX_NON_CIRCULATING_ADDRESSES);
        }

        for (uint256 i = 0; i < length; i++) {
            address addr = initialNonCirculatingAddresses[i];
            if (addr == address(0)) revert ZeroAddress();
            if (nonCirculatingAddresses[addr]) revert DuplicateAddress(addr);

            nonCirculatingAddresses[addr] = true;
            nonCirculatingAddressesList.push(addr);
            emit NonCirculatingAddressAdded(addr);
        }
    }

    /**
     * @notice Required overrides for multiple inheritance
     */
    function votingDelay() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingDelay();
    }

    function votingPeriod() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingPeriod();
    }

    function proposalThreshold()
        public
        view
        override(Governor, GovernorSettings)
        returns (uint256)
    {
        return super.proposalThreshold();
    }

    /**
     * @notice Return the absolute quorum amount.
     * @return Quorum amount in token units
     * @dev For launch, quorum is an absolute amount (e.g., 4M tokens).
     *      Non-circulating tracking is preserved for reporting and future upgrades.
     */
    function quorum(
        uint256 blockNumber
    ) public view override(Governor) returns (uint256) {
        blockNumber; // silence unused warning; absolute quorum is block-independent
        return absoluteQuorum;
    }

    /**
     * @notice Get circulating supply at a specific block number
     * @param blockNumber Block number to calculate circulating supply for
     * @return Circulating supply = total supply - sum of tokens in non-circulating addresses
     * @dev Used for external APIs (CoinGecko, CoinMarketCap) and transparency
     *      NOT used for quorum calculation (quorum uses `absoluteQuorum`)
     *      For current block: uses balanceOf() (more accurate, works even if not delegated)
     *      For historical blocks: uses getPastVotes() (limitation of ERC20Votes)
     */
    function getCirculatingSupply(uint256 blockNumber) public view returns (uint256) {
        IVotes token = token();
        uint256 totalSupply;
        if (blockNumber >= block.number) {
            // Current (or future) block: use live ERC20 totalSupply to avoid ERC5805FutureLookup
            totalSupply = IERC20(address(token)).totalSupply();
            blockNumber = block.number;
        } else {
            totalSupply = token.getPastTotalSupply(blockNumber);
        }
        uint256 nonCirculating = 0;

        uint256 length = nonCirculatingAddressesList.length;
        for (uint256 i = 0; i < length; i++) {
            address addr = nonCirculatingAddressesList[i];
            if (nonCirculatingAddresses[addr]) {
                if (blockNumber == block.number) {
                    // For current block, use balance (more accurate)
                    // Works even if address hasn't delegated
                    nonCirculating += IERC20(address(token)).balanceOf(addr);
                } else {
                    // For historical blocks, use voting power (only available historical data)
                    // Limitation: If address didn't delegate at that block, tokens won't be excluded
                    nonCirculating += token.getPastVotes(addr, blockNumber);
                }
            }
        }

        // Circulating supply = total supply - non-circulating
        // Use unchecked for gas efficiency (nonCirculating <= totalSupply by design)
        unchecked {
            return totalSupply - nonCirculating;
        }
    }

    /**
     * @notice Get current circulating supply
     * @return Current circulating supply
     */
    function getCurrentCirculatingSupply() public view returns (uint256) {
        return getCirculatingSupply(block.number);
    }

    /**
     * @notice Add a non-circulating address (e.g., vesting contract, locked tokens)
     * @param addr Address to mark as non-circulating
     * @dev Can only be called by the timelock (via governance proposal)
     * @dev Reverts if address is zero, already added, or would exceed MAX_NON_CIRCULATING_ADDRESSES
     */
    function addNonCirculatingAddress(address addr) external {
        if (_msgSender() != address(timelock())) {
            revert OnlyTimelock(_msgSender(), address(timelock()));
        }
        if (addr == address(0)) revert ZeroAddress();
        if (nonCirculatingAddresses[addr]) revert DuplicateAddress(addr);
        if (nonCirculatingAddressesList.length >= MAX_NON_CIRCULATING_ADDRESSES) {
            revert MaxAddressesReached();
        }

        nonCirculatingAddresses[addr] = true;
        nonCirculatingAddressesList.push(addr);
        emit NonCirculatingAddressAdded(addr);
    }

    /**
     * @notice Remove a non-circulating address
     * @param addr Address to remove from non-circulating list
     * @dev Can only be called by the timelock (via governance proposal)
     * @dev Removes from mapping and array (swaps with last element for gas efficiency)
     */
    function removeNonCirculatingAddress(address addr) external {
        if (_msgSender() != address(timelock())) {
            revert OnlyTimelock(_msgSender(), address(timelock()));
        }
        if (!nonCirculatingAddresses[addr]) revert AddressNotInList(addr);

        // Remove from mapping
        delete nonCirculatingAddresses[addr];

        // Remove from array (swap with last element and pop)
        uint256 length = nonCirculatingAddressesList.length;
        for (uint256 i = 0; i < length; i++) {
            if (nonCirculatingAddressesList[i] == addr) {
                // Swap with last element
                nonCirculatingAddressesList[i] = nonCirculatingAddressesList[length - 1];
                // Pop last element
                nonCirculatingAddressesList.pop();
                break;
            }
        }

        emit NonCirculatingAddressRemoved(addr);
    }

    /**
     * @notice Get the number of non-circulating addresses
     * @return Number of addresses marked as non-circulating
     */
    function getNonCirculatingAddressesCount() external view returns (uint256) {
        return nonCirculatingAddressesList.length;
    }

    /**
     * @notice Update absolute quorum amount
     * @param newQuorum New absolute quorum amount in tokens
     * @dev Can only be called by the timelock (via governance proposal)
     * @dev Reverts if new quorum is zero
     */
    function setAbsoluteQuorum(uint256 newQuorum) external {
        if (_msgSender() != address(timelock())) {
            revert OnlyTimelock(_msgSender(), address(timelock()));
        }
        if (newQuorum == 0) revert QuorumMustBePositive();

        uint256 oldQuorum = absoluteQuorum;
        absoluteQuorum = newQuorum;
        emit AbsoluteQuorumUpdated(oldQuorum, newQuorum);
    }

    function state(
        uint256 proposalId
    ) public view override(Governor, GovernorTimelockControl) returns (ProposalState) {
        return super.state(proposalId);
    }

    function propose(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        string memory description
    ) public override(Governor) returns (uint256) {
        return super.propose(targets, values, calldatas, description);
    }

    function queue(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) public override returns (uint256) {
        return super.queue(targets, values, calldatas, descriptionHash);
    }

    function execute(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) public payable override returns (uint256) {
        return super.execute(targets, values, calldatas, descriptionHash);
    }

    function cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) public override(Governor) returns (uint256) {
        return super.cancel(targets, values, calldatas, descriptionHash);
    }

    function proposalNeedsQueuing(
        uint256
    ) public view override(Governor, GovernorTimelockControl) returns (bool) {
        return super.proposalNeedsQueuing(0);
    }

    function _queueOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint48) {
        return super._queueOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    function _executeOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) {
        super._executeOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    function _cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint256) {
        return super._cancel(targets, values, calldatas, descriptionHash);
    }

    function _executor()
        internal
        view
        override(Governor, GovernorTimelockControl)
        returns (address)
    {
        return super._executor();
    }

    function supportsInterface(bytes4 interfaceId) public view override(Governor) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/governance/SlowLaneQueueActiva.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

/**
 * @title SlowLaneQueueActivate
 * @notice Abstract contract providing two-step queue/activate pattern for Slow lane governance
 * @dev Enforces 7-day delay for high-risk changes (module swaps, fee recipient, etc.)
 *
 * Usage:
 * 1. Inherit this contract
 * 2. Add storage for pending values (PendingAddress or PendingUint)
 * 3. Implement queueX() function calling _queueAddress() or _queueUint()
 * 4. Implement activateX() function calling _activateAddress() or _activateUint()
 *
 * Pattern:
 * - queueX() stores pending value and ETA (now + 7 days)
 * - activateX() checks ETA has passed, then applies the change
 * - This enforces 7-day delay on top of Timelock's 48h delay
 *
 * Example:
 * ```solidity
 * PendingAddress private _pendingFeeRecipient;
 *
 * function queueFeeRecipient(address newAddr) external onlyRole(ROLE_TIMELOCK) {
 *     _queueAddress(_pendingFeeRecipient, newAddr);
 *     emit FeeRecipientQueued(feeRecipient, newAddr, _pendingFeeRecipient.eta);
 * }
 *
 * function activateFeeRecipient() external onlyRole(ROLE_TIMELOCK) {
 *     address old = feeRecipient;
 *     feeRecipient = _activateAddress(_pendingFeeRecipient);
 *     emit FeeRecipientActivated(old, feeRecipient);
 * }
 * ```
 */
abstract contract SlowLaneQueueActivate {
    /// @notice Slow lane delay: 7 days
    uint256 public constant SLOW_DELAY = 7 days;

    /// @notice Pending address change with ETA
    struct PendingAddress {
        address value;
        uint64 eta; // Unix timestamp when activation is allowed
        bool exists;
    }

    /// @notice Pending uint256 change with ETA
    struct PendingUint {
        uint256 value;
        uint64 eta; // Unix timestamp when activation is allowed
        bool exists;
    }

    /// @notice Error thrown when trying to activate before ETA
    error NotReady(uint64 eta);

    /// @notice Error thrown when no pending change exists
    error NoPending();

    /// @notice Error thrown when value is invalid (e.g., zero address)
    error InvalidValue();

    /**
     * @notice Queue an address change
     * @param pending Storage reference to PendingAddress
     * @param newValue New address value to queue
     * @dev Sets pending value and ETA = now + SLOW_DELAY
     */
    function _queueAddress(PendingAddress storage pending, address newValue) internal {
        if (newValue == address(0)) {
            revert InvalidValue();
        }
        pending.value = newValue;
        pending.eta = uint64(block.timestamp + SLOW_DELAY); // forge-lint: disable-line(unsafe-typecast)
        pending.exists = true;
    }

    /**
     * @notice Activate a queued address change
     * @param pending Storage reference to PendingAddress
     * @return activatedValue The activated address value
     * @dev Reverts if no pending change or ETA not reached
     */
    function _activateAddress(PendingAddress storage pending) internal returns (address) {
        if (!pending.exists) {
            revert NoPending();
        }
        if (block.timestamp < pending.eta) {
            revert NotReady(pending.eta);
        }
        address value = pending.value;
        // Clear all fields
        pending.value = address(0);
        pending.eta = 0;
        pending.exists = false;
        return value;
    }

    /**
     * @notice Queue a uint256 change
     * @param pending Storage reference to PendingUint
     * @param newValue New uint256 value to queue
     * @dev Sets pending value and ETA = now + SLOW_DELAY
     */
    function _queueUint(PendingUint storage pending, uint256 newValue) internal {
        pending.value = newValue;
        pending.eta = uint64(block.timestamp + SLOW_DELAY); // forge-lint: disable-line(unsafe-typecast)
        pending.exists = true;
    }

    /**
     * @notice Activate a queued uint256 change
     * @param pending Storage reference to PendingUint
     * @return activatedValue The activated uint256 value
     * @dev Reverts if no pending change or ETA not reached
     */
    function _activateUint(PendingUint storage pending) internal returns (uint256) {
        if (!pending.exists) {
            revert NoPending();
        }
        if (block.timestamp < pending.eta) {
            revert NotReady(pending.eta);
        }
        uint256 value = pending.value;
        // Clear all fields
        pending.value = 0;
        pending.eta = 0;
        pending.exists = false;
        return value;
    }

    /**
     * @notice Get pending address value (if exists)
     * @param pending Storage reference to PendingAddress
     * @return value Pending address value
     * @return eta Timestamp when activation is allowed
     * @return exists Whether a pending change exists
     */
    function getPendingAddress(
        PendingAddress storage pending
    ) internal view returns (address value, uint64 eta, bool exists) {
        return (pending.value, pending.eta, pending.exists);
    }

    /**
     * @notice Get pending uint256 value (if exists)
     * @param pending Storage reference to PendingUint
     * @return value Pending uint256 value
     * @return eta Timestamp when activation is allowed
     * @return exists Whether a pending change exists
     */
    function getPendingUint(
        PendingUint storage pending
    ) internal view returns (uint256 value, uint64 eta, bool exists) {
        return (pending.value, pending.eta, pending.exists);
    }
}

contracts/guards/InvariantGuardedAaveYie.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import {IYieldGenerationModule} from '../interfaces/IYieldGenerationModule.sol';
import {EscrowSettings} from '../types/EscrowTypes.sol';
import {AaveYieldHandlingLibrary} from '../libraries/AaveYieldHandlingLibrary.sol';
import {InvariantGuardInternal} from './InvariantGuardInternal.sol';

/**
 * @title InvariantGuardedAaveYieldLibrary
 * @notice Singleton yield library with InvariantGuard protection for delegatecall pattern
 * @dev 
 *      This contract provides a security-enhanced alternative to the module pattern.
 *      It uses delegatecall to execute Aave operations in the context of the calling
 *      escrow contract, with invariant guards to prevent malicious storage modifications.
 *      
 *      KEY DIFFERENCES FROM MODULE PATTERN:
 *      - Singleton: One library instance serves MULTIPLE escrow contracts
 *      - Delegatecall: Executes in caller's storage context (not separate module storage)
 *      - InvariantGuard: Prevents unauthorized storage modifications during delegatecall
 *      
 *      ARCHITECTURE:
 *      - EscrowVault calls this library via delegatecall
 *      - Library executes Aave operations in EscrowVault's context
 *      - InvariantGuard validates no critical storage was modified
 *      
 *      SECURITY:
 *      - Protects: owner, pendingOwner, guardian, pendingGuardian, module pointers, feeAddress
 *      - Prevents: Ownership theft, module hijacking, fee manipulation via delegatecall
 *      
 *      VERSION: 1.0.0
 *      - First version of InvariantGuard-protected yield library
 *      - Follows semantic versioning for library releases
 */
abstract contract InvariantGuardedAaveYieldLibrary is InvariantGuardInternal {
    using AaveYieldHandlingLibrary for *;

    /**
     * @notice Library identification
     */
    string public constant LIBRARY_NAME = "InvariantGuardedAaveYieldLibrary";
    string public constant LIBRARY_VERSION = "1.0.0";
    bytes32 public constant PROTOCOL_ID = keccak256("aave-v3-guarded");

    /**
     * @notice Get library metadata
     * @return name Library name
     * @return version Library version (semantic versioning)
     * @return protocolId Protocol identifier
     */
    function getLibraryInfo()
        external
        pure
        returns (string memory name, string memory version, bytes32 protocolId)
    {
        return (LIBRARY_NAME, LIBRARY_VERSION, PROTOCOL_ID);
    }

    /**
     * @notice Get the critical storage slots that are protected by invariant guards
     * @return slots Array of protected storage slot positions
     * @dev These slots are validated before/after delegatecall to prevent tampering
     */
    function getProtectedSlots() external pure returns (bytes32[] memory slots) {
        return _getAllCriticalSlots();
    }

    /**
     * @notice Get owner-related storage slots (slots 0 and 1 in Ownable)
     * @return slots Array containing owner slot positions
     */
    function getOwnerSlots() external pure returns (bytes32[] memory slots) {
        return _getOwnerSlots();
    }

    /**
     * @notice Get module-related storage slots
     * @return slots Array containing module pointer slot positions
     */
    function getModuleSlots() external pure returns (bytes32[] memory slots) {
        return _getModuleSlots();
    }

    function _getOwnerSlots() internal pure returns (bytes32[] memory slots) {
        slots = new bytes32[](2);
        slots[0] = bytes32(uint256(0));
        slots[1] = bytes32(uint256(1));
    }

    function _getModuleSlots() internal pure returns (bytes32[] memory slots) {
        slots = new bytes32[](3);
        slots[0] = bytes32(keccak256('yieldGenerationModule'));
        slots[1] = bytes32(keccak256('yieldDistributionModule'));
        slots[2] = bytes32(keccak256('feeAddress'));
    }

    function _getAllCriticalSlots() internal pure returns (bytes32[] memory slots) {
        bytes32[] memory ownerSlots = _getOwnerSlots();
        bytes32[] memory moduleSlots = _getModuleSlots();

        slots = new bytes32[](ownerSlots.length + moduleSlots.length);

        for (uint256 i = 0; i < ownerSlots.length; i++) {
            slots[i] = ownerSlots[i];
        }
        for (uint256 i = 0; i < moduleSlots.length; i++) {
            slots[ownerSlots.length + i] = moduleSlots[i];
        }
    }

    /**
     * @notice Execute guarded yield withdrawal via delegatecall
     * @param workflowId The escrow ID
     * @param token Token address
     * @param amount Principal amount to withdraw
     * @param genModule Yield generation module
     * @param settings Escrow settings
     * @param scaledShares Current scaled shares for this escrow
     * @param aaveYieldLibrary Aave yield library address (for delegatecall)
     * @return result Withdrawal result with actual amount and success status
     * 
     * @dev Protects critical storage slots from modification during delegatecall
     *      If the delegated code tries to modify owner/module/fee slots, transaction reverts
     */
    function guardedYieldWithdrawal(
        uint256 workflowId,
        address token,
        uint256 amount,
        IYieldGenerationModule genModule,
        EscrowSettings memory settings,
        uint256 scaledShares,
        address aaveYieldLibrary
    ) internal returns (AaveYieldHandlingLibrary.WithdrawalResult memory) {
        bytes32[] memory protectedSlots = _getAllCriticalSlots();

        return
            _guardedYieldWithdrawal(
                workflowId,
                token,
                amount,
                genModule,
                settings,
                scaledShares,
                aaveYieldLibrary,
                protectedSlots
            );
    }

    function _guardedYieldWithdrawal(
        uint256 workflowId,
        address token,
        uint256 amount,
        IYieldGenerationModule genModule,
        EscrowSettings memory settings,
        uint256 scaledShares,
        address aaveYieldLibrary,
        bytes32[] memory protectedSlots
    )
        internal
        invariantStorage(protectedSlots)
        returns (AaveYieldHandlingLibrary.WithdrawalResult memory)
    {
        return
            AaveYieldHandlingLibrary.handleYieldWithdrawal(
                workflowId,
                token,
                amount,
                genModule,
                settings,
                scaledShares,
                aaveYieldLibrary
            );
    }

    /**
     * @notice Execute guarded yield deposit via delegatecall
     * @param workflowId The escrow ID
     * @param token Token address
     * @param amount Amount to deposit for yield
     * @param genModule Yield generation module
     * @param settings Escrow settings
     * @param aaveYieldLibrary Aave yield library address (for delegatecall)
     * @return result Deposit result with scaled shares and success status
     * 
     * @dev Protects critical storage slots from modification during delegatecall
     *      If the delegated code tries to modify owner/module/fee slots, transaction reverts
     */
    function guardedYieldDeposit(
        uint256 workflowId,
        address token,
        uint256 amount,
        IYieldGenerationModule genModule,
        EscrowSettings memory settings,
        address aaveYieldLibrary
    ) internal returns (AaveYieldHandlingLibrary.DepositResult memory) {
        bytes32[] memory protectedSlots = _getAllCriticalSlots();

        return
            _guardedYieldDeposit(
                workflowId,
                token,
                amount,
                genModule,
                settings,
                aaveYieldLibrary,
                protectedSlots
            );
    }

    function _guardedYieldDeposit(
        uint256 workflowId,
        address token,
        uint256 amount,
        IYieldGenerationModule genModule,
        EscrowSettings memory settings,
        address aaveYieldLibrary,
        bytes32[] memory protectedSlots
    )
        internal
        invariantStorage(protectedSlots)
        returns (AaveYieldHandlingLibrary.DepositResult memory)
    {
        return
            AaveYieldHandlingLibrary.handleYieldDeposit(
                workflowId,
                token,
                amount,
                genModule,
                settings,
                aaveYieldLibrary
            );
    }
}

contracts/guards/InvariantGuardHelper.so.content:
// SPDX-License-Identifier: CC0-1.0
pragma solidity ^0.8.20;

enum DeltaConstraint {
    NO_CHANGE,
    INCREASE_EXACT,
    INCREASE_MAX,
    INCREASE_MIN,
    DECREASE_EXACT,
    DECREASE_MAX,
    DECREASE_MIN
}

struct CodeInvariant {
    bytes32 beforeCodeHash;
    bytes32 afterCodeHash;
}

struct ValuePerPosition {
    uint256 beforeValue;
    uint256 afterValue;
    uint256 delta;
}

struct AddressInvariant {
    address beforeOwner;
    address afterOwner;
}

struct AccountArrayInvariant {
    address[] accountArray;
}

error LengthMismatch();
error UnsupportedInvariant();
error InvalidDeltaConstraint(DeltaConstraint deltaConstraint);
error ArrayTooLarge(uint256 length, uint256 maxLength);

library InvariantGuardHelper {
    uint256 internal constant MAX_PROTECTED_SLOTS = 0xffff;

    function _emptyArray(uint256 length) internal pure returns (uint256[] memory) {
        return new uint256[](length);
    }

    function _getBytes32ArrayLength(bytes32[] memory bytes32Array) internal pure returns (uint256) {
        return bytes32Array.length;
    }

    function _getUint256ArrayLength(uint256[] memory uint256Array) internal pure returns (uint256) {
        return uint256Array.length;
    }

    function _getAddressArrayLength(address[] memory addressArray) internal pure returns (uint256) {
        return addressArray.length;
    }

    function _revertIfArrayTooLarge(uint256 numPositions) internal pure {
        if (numPositions > MAX_PROTECTED_SLOTS) revert ArrayTooLarge(numPositions, MAX_PROTECTED_SLOTS);
    }

    function _isDeltaViolation(
        uint256 beforeValue,
        uint256 afterValue,
        uint256 expectedDelta,
        DeltaConstraint deltaConstraint
    ) internal pure returns (bool) {
        if (deltaConstraint == DeltaConstraint.NO_CHANGE) {
            return beforeValue != afterValue;
        } else if (deltaConstraint == DeltaConstraint.INCREASE_EXACT) {
            if (afterValue < beforeValue) return true;
            unchecked {
                return afterValue - beforeValue != expectedDelta;
            }
        } else if (deltaConstraint == DeltaConstraint.INCREASE_MAX) {
            if (afterValue < beforeValue) return true;
            unchecked {
                return afterValue - beforeValue > expectedDelta;
            }
        } else if (deltaConstraint == DeltaConstraint.INCREASE_MIN) {
            if (afterValue < beforeValue) return true;
            unchecked {
                return afterValue - beforeValue < expectedDelta;
            }
        } else if (deltaConstraint == DeltaConstraint.DECREASE_EXACT) {
            if (beforeValue < afterValue) return true;
            unchecked {
                return beforeValue - afterValue != expectedDelta;
            }
        } else if (deltaConstraint == DeltaConstraint.DECREASE_MAX) {
            if (beforeValue < afterValue) return true;
            unchecked {
                return beforeValue - afterValue > expectedDelta;
            }
        } else if (deltaConstraint == DeltaConstraint.DECREASE_MIN) {
            if (beforeValue < afterValue) return true;
            unchecked {
                return beforeValue - afterValue < expectedDelta;
            }
        } else {
            revert InvalidDeltaConstraint(deltaConstraint);
        }
    }

    function _validateDeltaArray(
        uint256[] memory beforeValueArray,
        uint256[] memory afterValueArray,
        uint256[] memory expectedDeltaArray,
        DeltaConstraint deltaConstraint
    ) internal pure returns (uint256, ValuePerPosition[] memory) {
        uint256 length = _getUint256ArrayLength(expectedDeltaArray);
        _revertIfArrayTooLarge(length);
        if (_getUint256ArrayLength(beforeValueArray) != length || _getUint256ArrayLength(afterValueArray) != length)
            revert LengthMismatch();
        bool valueMismatch;
        uint256 violationCount;
        ValuePerPosition[] memory violations = new ValuePerPosition[](length);
        for (uint256 i = 0; i < length; ) {
            valueMismatch = _isDeltaViolation(beforeValueArray[i], afterValueArray[i], expectedDeltaArray[i], deltaConstraint);
            assembly {
                violationCount := add(violationCount, valueMismatch)
            }
            violations[i] = ValuePerPosition(beforeValueArray[i], afterValueArray[i], expectedDeltaArray[i]);
            unchecked {
                ++i;
            }
        }
        return (violationCount, violations);
    }

    function _validateAddressArray(
        address[] memory beforeOwnerArray,
        address[] memory afterOwnerArray
    ) internal pure returns (uint256, AddressInvariant[] memory) {
        uint256 length = _getAddressArrayLength(afterOwnerArray);
        _revertIfArrayTooLarge(length);
        bool valueMismatch;
        uint256 violationCount;
        AddressInvariant[] memory violations = new AddressInvariant[](length);
        for (uint256 i = 0; i < length; ) {
            valueMismatch = beforeOwnerArray[i] != afterOwnerArray[i];
            assembly {
                violationCount := add(violationCount, valueMismatch)
            }
            violations[i] = AddressInvariant(beforeOwnerArray[i], afterOwnerArray[i]);
            unchecked {
                ++i;
            }
        }
        return (violationCount, violations);
    }
}

