// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../types/EscrowTypes.sol';

/**
 * @title DisputeManagementLibrary
 * @notice Library for dispute management logic to reduce BaseEscrow size
 */
library DisputeManagementLibrary {
    /**
     * @dev Check if a dispute has timed out
     * @param workflowId Escrow ID
     * @param escrowState Current escrow state
     * @param raisedTimestamp Timestamp when dispute was raised
     * @param maxDuration Maximum allowed dispute duration
     * @return timedOut True if timed out
     * @return timeRemaining Seconds until timeout
     */
    function isTimedOut(
        uint256 workflowId,
        EscrowState escrowState,
        uint256 raisedTimestamp,
        uint256 maxDuration
    ) internal view returns (bool timedOut, uint256 timeRemaining) {
        // Intentionally unused (kept for consistent call signatures / debugging)
        workflowId;

        if (escrowState != EscrowState.DISPUTED || raisedTimestamp == 0) {
            return (false, 0);
        }

        uint256 elapsed = block.timestamp - raisedTimestamp;
        if (elapsed >= maxDuration) {
            return (true, 0);
        }

        return (false, maxDuration - elapsed);
    }
}

contracts/libraries/DisputeRaiseLibrary..content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '../shared/interfaces/IIncentiveModule.sol';
import '../core/BaseEscrow.sol';

/**
 * @title DisputeRaiseLibrary
 * @notice Library for raiseDispute logic extraction
 * @dev Extracted from BaseEscrow to reduce contract size (Phase 1 size optimization)
 */
library DisputeRaiseLibrary {
    /**
     * @notice Call incentive module onDisputeOpened hook
     * @param incentiveModAddr Address of incentive module (from snapshot)
     * @param workflowId The escrow ID
     * @param token Token address
     * @param amountAfterFee Amount after fee
     * @param escrowFee Escrow fee in basis points
     * @param escrowFeeDenominator Fee denominator (10000)
     * @dev Returns whether to emit failure events (caller should emit if true)
     */
    function callIncentiveModuleHook(
        address incentiveModAddr,
        uint256 workflowId,
        address token,
        uint256 amountAfterFee,
        uint256 escrowFee,
        uint256 escrowFeeDenominator
    ) internal returns (bool shouldEmitFailure) {
        if (incentiveModAddr == address(0)) {
            return false; // No incentive module, no failure to emit
        }

        IIncentiveModule incentiveMod = IIncentiveModule(incentiveModAddr);

        // Calculate escrow fee: fee = amount * escrowFee / ESCROW_FEE_DENOMINATOR
        // Original amount = amountAfterFee + fee, so: fee = (amountAfterFee * escrowFee) / (ESCROW_FEE_DENOMINATOR - escrowFee)
        uint256 originalAmount = amountAfterFee +
            ((amountAfterFee * escrowFee) / (escrowFeeDenominator - escrowFee));
        uint256 escrowFeeAmount = (originalAmount * escrowFee) / escrowFeeDenominator;

        // Use low-level call to save bytecode (replaces try/catch)
        (bool success, ) = address(incentiveMod).call(
            abi.encodeWithSelector(
                IIncentiveModule.onDisputeOpened.selector,
                workflowId,
                address(this),
                token,
                originalAmount,
                escrowFeeAmount,
                0
            )
        );

        return !success; // Return true if call failed (caller should emit events)
    }
}

contracts/libraries/EscrowAccountingLibr.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/IERC20.sol';

library EscrowAccountingLibrary {
    function getDelta(
        address token,
        mapping(address => uint256) storage totalHeld,
        mapping(address => uint256) storage totalFees
    ) internal view returns (int256 delta) {
        uint256 actual = IERC20(token).balanceOf(address(this));
        uint256 expected = totalHeld[token] + totalFees[token];
        // In this system, token balances are expected to remain far below int256.max.
        return int256(actual) - int256(expected); // forge-lint: disable-line(unsafe-typecast)
    }

    function reconcile(
        address token,
        mapping(address => uint256) storage totalHeld,
        mapping(address => uint256) storage totalFees
    ) internal view returns (uint256 delta, bool hasDeficit) {
        uint256 actual = IERC20(token).balanceOf(address(this));
        uint256 expected = totalHeld[token] + totalFees[token];

        if (actual > expected) {
            return (actual - expected, false);
        } else if (actual < expected) {
            return (expected - actual, true);
        }
        return (0, false);
    }
}

