    /**
     * @notice Calculate and distribute resolver payments for a finalized dispute (IIncentiveModule interface)
     * @param workflowId Unique identifier for the dispute
     * @param token Token address for payment
     * @dev This is a wrapper that calls onDisputeResolved for backward compatibility
     *      Note: totalFees parameter from interface is ignored as fees are already recorded via recordEscrowFee/recordEscalationFee
     */
    function distributePayments(
        uint256 workflowId,
        address escrowContract,
        address token,
        uint256 /* totalFees */
    ) external virtual override onlyEscrowContract {
        // Delegate to onDisputeResolved for backward compatibility
        // Note: totalFees parameter is ignored as fees are already recorded via recordEscrowFee/recordEscalationFee
        onDisputeResolved(workflowId, escrowContract, token);
    }

    /**
     * @notice Calculate payments when dispute is resolved (pull pattern)
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param token Token address for payments
     * @dev Called by escrow contract when dispute is resolved
     *      Calculates payments and makes them claimable (pull pattern)
     *      HIGH-2: Escrow contract MUST transfer tokens to this contract BEFORE calling this function.
     *      The expected balance is tracked via recordEscrowFee/recordEscalationFee, and this function
     *      validates that actual balance >= expected balance. If tokens are not transferred, this will
     *      fail with InsufficientBalanceForFees error.
     */
    function onDisputeResolved(
        uint256 workflowId,
        address escrowContract,
        address token
    ) public onlyEscrowContract nonReentrant {
        if (token == address(0)) revert ZeroToken();
        if (paymentsCalculated[escrowContract][workflowId]) revert PaymentsAlreadyCalculated(workflowId);

        // CRIT-FIX: Enforce single payout token per dispute
        _requirePayoutToken(escrowContract, workflowId, token);

        // Gather data (imperative - state reads)
        ResolverRecord[] memory resolvers = disputeResolvers[escrowContract][workflowId];
        if (resolvers.length == 0) revert NoResolvers(workflowId);

        uint256 escrowFee = disputeEscrowFees[escrowContract][workflowId];
        uint256 escalationFees = disputeEscalationFees[escrowContract][workflowId];
        uint256 totalRecordedFees = escrowFee + escalationFees;

        // Check for stale fee recording (fees recorded too long ago)
        uint256 feeRecordedAt = feeRecordedTimestamp[escrowContract][workflowId];
        if (feeRecordedAt > 0 && block.timestamp > feeRecordedAt + MAX_FEE_RECORDING_AGE) {
            emit StaleFeeRecordingDetected(workflowId, feeRecordedAt, block.timestamp);
            // Continue anyway - escrow may have valid reason for delay
            // But this allows monitoring for potential issues
        }

        // CRIT-1/CRIT-3: Validate balance matches recorded fees (with tolerance for rounding)
        IERC20 tokenContract = IERC20(token);
        uint256 contractBalance = tokenContract.balanceOf(address(this));
        uint256 expectedBalance = disputeExpectedTokenBalance[escrowContract][workflowId];

        // Check that balance is sufficient for recorded fees
        if (contractBalance < totalRecordedFees) {
            // Emit detailed error for debugging transfer issues
            revert InsufficientBalanceForFees(totalRecordedFees, contractBalance);
        }

        // Check that balance matches expected (with tolerance for rounding/errors)
        // Allow small tolerance (0.01% = 1 basis point) for rounding errors
        uint256 tolerance = (expectedBalance * BALANCE_TOLERANCE_BPS) / BASIS_POINTS_DENOMINATOR;
        if (contractBalance > expectedBalance + tolerance) {
            // Balance exceeds expected - emit event for monitoring but allow to proceed
            // This could indicate direct token sends (attack attempt) or accounting error
            emit BalanceMismatchDetected(workflowId, token, expectedBalance, contractBalance);
            // Continue but use recorded fees for calculation, not inflated balance
        }

        // Clear expected balance tracking after validation
        delete disputeExpectedTokenBalance[escrowContract][workflowId];

        // Prepare input (functional data structure)
        PaymentInput memory input = PaymentInput({
            escrowFee: escrowFee,
            escalationFees: escalationFees,
            resolverSharePercentage: resolverSharePercentage,
            resolvers: resolvers,
            weights: weights
        });

        // Calculate payments (functional - pure library call)
        PaymentOutput memory output = calculatePaymentsWithVersion(input);

        // ============ Bounds Checking ============
        // Validate payment calculation results

        // 1. Array length validation
        if (output.resolvers.length != output.payments.length) {
            revert ArrayLengthMismatch(output.resolvers.length, output.payments.length); // Uses EscrowTypes.sol error
        }
        if (output.resolvers.length == 0) revert NoResolvers(workflowId);

        // 2. Total amount validation - resolver share cannot exceed total fees
        if (output.totalResolverShare > escrowFee + escalationFees) {
            revert ResolverShareExceedsTotalFees(output.totalResolverShare, escrowFee + escalationFees);
        }

        // 3. Individual payment validation
        uint256 calculatedTotal = 0;
        for (uint256 i = 0; i < output.payments.length; i++) {
            // Each payment must be non-negative and not exceed total
            if (output.payments[i] > output.totalResolverShare) {
                revert IndividualPaymentExceedsTotal(output.payments[i], output.totalResolverShare);
            }

            // Sum validation (check for overflow)
            uint256 previousTotal = calculatedTotal;
            calculatedTotal += output.payments[i];
            if (calculatedTotal < previousTotal) revert PaymentSumOverflow(previousTotal, output.payments[i]);
        }

        // 4. Sum validation - sum of individual payments should equal total
        if (calculatedTotal != output.totalResolverShare) {
            revert PaymentSumMismatch(calculatedTotal, output.totalResolverShare);
        }

        // 5. Resolver address validation
        for (uint256 i = 0; i < output.resolvers.length; i++) {
            if (output.resolvers[i] == address(0)) revert ZeroResolverAddress(i);
        }

        // 6. Maximum payment validation - no single payment should exceed reasonable bounds
        // (e.g., no single resolver should get more than 90% of total share)
        // Only apply this check when there are multiple resolvers
        // When there's only one resolver, they should legitimately get 100% of the share
        if (output.resolvers.length > 1) {
            uint256 maxSinglePayment = (output.totalResolverShare * MAX_SINGLE_PAYMENT_PERCENTAGE) /
                BASIS_POINTS_DENOMINATOR;
            for (uint256 i = 0; i < output.payments.length; i++) {
                if (output.payments[i] > maxSinglePayment) {
                    revert PaymentExceedsMaximumAllowed(output.payments[i], maxSinglePayment);
                }
            }
        }

        // 7. Minimum payment validation - if there are multiple resolvers, no payment should be 0
        // (unless explicitly allowed by the payment library)
        // Note: Zero payments are allowed but will be skipped in distribution

        // CRIT-1/CRIT-3: Additional check - resolver share cannot exceed what we actually have
        // Note: contractBalance was already checked above, but double-check here for safety
        if (contractBalance < output.totalResolverShare) {
            revert InsufficientBalanceForFees(output.totalResolverShare, contractBalance);
        }

        // Store claimable amounts (pull pattern - resolvers claim their payments)
        for (uint256 i = 0; i < output.resolvers.length; i++) {
            if (output.resolvers[i] != address(0) && output.payments[i] > 0) {
                claimablePayments[escrowContract][workflowId][output.resolvers[i]] = output.payments[i];
            }
        }

        // Mark as calculated (allows resolvers to claim)
        paymentsCalculated[escrowContract][workflowId] = true;
        disputePaymentsDistributed[escrowContract][workflowId] = true; // For backward compatibility

        // CRIT-2/CRIT-3: Clear fee tracking after successful payment calculation
        // Note: Keep fees in storage for view functions, but clear expected balance (already cleared above)
        // Consider clearing fees if needed, but keeping them for historical queries might be useful

        emit PaymentsCalculated(workflowId, token, output.totalResolverShare);
    }

    /**
     * @notice Claim payment for a resolved dispute (pull pattern)
     * @param workflowId The escrow transfer ID
     * @param token Token address for payment
     * @dev Resolvers call this to claim their payment
     *      Allows retry if initial transfer fails
     */
    function claimPayment(uint256 workflowId, address escrowContract, address token) external nonReentrant {
        if (token == address(0)) revert ZeroToken();
        if (!paymentsCalculated[escrowContract][workflowId]) revert PaymentsNotCalculated(workflowId);

        // CRIT-FIX: Validate token matches payout token
        address expectedToken = payoutToken[escrowContract][workflowId];
        if (expectedToken != address(0) && token != expectedToken) {
            revert InvalidPayoutToken(expectedToken, token);
        }

        uint256 amount = claimablePayments[escrowContract][workflowId][_msgSender()];
        if (amount == 0) revert NothingToClaim(workflowId, _msgSender());

        // Clear claimable amount before transfer (prevent reentrancy)
        delete claimablePayments[escrowContract][workflowId][_msgSender()];

        // Transfer payment (safeTransfer will revert on failure, restoring claimable amount is not needed
        // since the delete above will be reverted by the transaction revert)
        IERC20 tokenContract = IERC20(token);
        tokenContract.safeTransfer(_msgSender(), amount);

        emit PaymentClaimed(workflowId, _msgSender(), amount);
    }

    /**
     * @notice Enforce single payout token per dispute
     * @param workflowId Dispute ID
     * @param token Token address to check/enforce
     * @dev Sets payout token on first payment source (fee or bond), subsequent payments must match
     */
    function _enforceSinglePayoutToken(address escrowContract, uint256 workflowId, address token) internal {
        address p = payoutToken[escrowContract][workflowId];
        if (p == address(0)) {
            payoutToken[escrowContract][workflowId] = token;
        } else if (p != token) {
            revert InvalidPayoutToken(p, token);
        }
    }

    /**
     * @notice Calculate payments using current library with version detection
     * @param input Payment calculation input
     * @return output Payment calculation results
     * @dev Detects library version and calls appropriate function
     */
    function calculatePaymentsWithVersion(
        PaymentInput memory input
    ) internal view returns (PaymentOutput memory) {
        // Get library version
        string memory libVersion = IPaymentCalculationLibrary(currentPaymentLibrary).version();

        // For V1, use standard interface
        // Future versions can add version-specific handling here
        if (keccak256(bytes(libVersion)) == keccak256(bytes('1.0.0'))) {
            // V1: Standard interface call
            return IPaymentCalculationLibrary(currentPaymentLibrary).calculatePayments(input);
        } else {
            // Unknown version - try standard interface (extensible input should handle it)
            return IPaymentCalculationLibrary(currentPaymentLibrary).calculatePayments(input);
        }
    }

    // ============ Governance Functions ============

    /**
     * @notice Queue new payment calculation library (slow-lane, governance-controlled)
     * @param newLibrary Address of new library contract
     * @dev Validates library before queueing, 7-day delay before activation
     */
    function queuePaymentCalculationLibrary(address newLibrary) external onlyRole(ROLE_TIMELOCK) {
        if (newLibrary == address(0)) revert ZeroAddressField('paymentLibrary');
        if (!validateLibrary(newLibrary)) revert InvalidLibrary(newLibrary);

        _queueAddress(_pendingPaymentLibrary, newLibrary);
        emit PaymentLibraryQueued(currentPaymentLibrary, newLibrary, _pendingPaymentLibrary.eta);
    }

    /**
     * @notice Activate queued payment calculation library
     * @dev Reverts if 7-day delay has not elapsed
     */
    function activatePaymentCalculationLibrary() external onlyRole(ROLE_TIMELOCK) {
        address oldLibrary = currentPaymentLibrary;
        currentPaymentLibrary = _activateAddress(_pendingPaymentLibrary);

        emit PaymentLibraryActivated(oldLibrary, currentPaymentLibrary);
    }

    /**
     * @notice Rollback to previous library (emergency only)
     * @param previousLibrary Address of previous library
     * @dev Should be used only in emergencies
     */
    function rollbackToPreviousLibrary(address previousLibrary) external onlyRole(ROLE_TIMELOCK) {
        if (previousLibrary == address(0)) revert ZeroAddressField('paymentLibrary');
        if (!validateLibrary(previousLibrary)) revert InvalidLibrary(previousLibrary);

        currentPaymentLibrary = previousLibrary;
        emit PaymentLibraryRolledBack(previousLibrary);
    }

    /**
     * @notice Queue resolver share percentage change
     * @param newPercentage New percentage (basis points, e.g., 5000 = 50%)
     * @dev 7-day delay before activation
     */
    function queueResolverSharePercentage(uint256 newPercentage) external onlyRole(ROLE_TIMELOCK) {
        if (newPercentage > 10000) revert InvalidPercentage(newPercentage, 10000);

        _queueUint(_pendingResolverSharePercentage, newPercentage);
        emit ResolverSharePercentageQueued(
            resolverSharePercentage,
            newPercentage,
            _pendingResolverSharePercentage.eta
        );
    }

    /**
     * @notice Activate queued resolver share percentage
     * @dev Reverts if 7-day delay has not elapsed
     */
    function activateResolverSharePercentage() external onlyRole(ROLE_TIMELOCK) {
        uint256 oldPercentage = resolverSharePercentage;
        resolverSharePercentage = _activateUint(_pendingResolverSharePercentage);

        emit ResolverSharePercentageActivated(oldPercentage, resolverSharePercentage);
    }

    /**
     * @notice Queue weights change
     * @param newWeights New weight configuration
     * @dev 7-day delay before activation
     */
    function queueWeights(Weights memory newWeights) external onlyRole(ROLE_TIMELOCK) {
        if (newWeights.level0 == 0) revert InvalidWeight(0, newWeights.level0);
        if (newWeights.level1 == 0) revert InvalidWeight(1, newWeights.level1);
        if (newWeights.level2 == 0) revert InvalidWeight(2, newWeights.level2);

        _pendingWeights = PendingWeights({
            value: newWeights,
            eta: uint64(block.timestamp + SLOW_DELAY), // forge-lint: disable-line(unsafe-typecast)
            exists: true
        });

        emit WeightsQueued(weights, newWeights, _pendingWeights.eta);
    }

    /**
     * @notice Activate queued weights
     * @dev Reverts if 7-day delay has not elapsed
     */
    function activateWeights() external onlyRole(ROLE_TIMELOCK) {
        if (!_pendingWeights.exists) {
            revert NoPending();
        }
        if (block.timestamp < _pendingWeights.eta) {
            revert NotReady(_pendingWeights.eta);
        }

        Weights memory oldWeights = weights;
        weights = _pendingWeights.value;

        emit WeightsActivated(oldWeights, weights);

        // Clear pending
        delete _pendingWeights;
    }

    /**
     * @notice Register escrow contract
     * @param escrowContract Address of escrow contract
     * @dev Only registered contracts can call incentive functions
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert ZeroAddressField('escrowContract');
        registeredEscrowContracts[escrowContract] = true;
        emit EscrowContractRegistered(escrowContract);
    }

    /**
     * @notice Unregister escrow contract
     * @param escrowContract Address of escrow contract
     */
    function unregisterEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        registeredEscrowContracts[escrowContract] = false;
        emit EscrowContractUnregistered(escrowContract);
    }

    // ============ HIGH-3: Escrow Rate Limiting Functions ============

    /**
     * @notice Check and update rate limits for an escrow contract
     * @param escrow Escrow contract address
     * @param disputeCount Number of new disputes (typically 0 or 1)
     * @param feeAmount Fee amount to add to daily total
     * @dev Internal function called by fee recording functions
     */
    function _checkAndUpdateRateLimits(
        address escrow,
        uint256 disputeCount,
        uint256 feeAmount
    ) internal {
        EscrowRateLimit storage limit = escrowRateLimits[escrow];

        // Reset window if new day
        if (block.timestamp >= limit.windowStart + RATE_LIMIT_WINDOW) {
            limit.disputesToday = 0;
            limit.feesToday = 0;
            limit.windowStart = block.timestamp;
            emit EscrowRateLimitReset(escrow, block.timestamp);
        }

        // Check dispute rate limit
        if (disputeCount > 0) {
            uint256 newDisputeCount = limit.disputesToday + disputeCount;
            if (newDisputeCount > MAX_DISPUTES_PER_ESCROW_PER_DAY) {
                emit EscrowRateLimitExceededEvent(
                    escrow,
                    'disputes',
                    newDisputeCount,
                    MAX_DISPUTES_PER_ESCROW_PER_DAY
                );
                revert EscrowRateLimitExceeded(escrow, newDisputeCount, MAX_DISPUTES_PER_ESCROW_PER_DAY);
            }
            limit.disputesToday = newDisputeCount;
        }

        // Check fee rate limit
        if (feeAmount > 0) {
            uint256 newFeeTotal = limit.feesToday + feeAmount;
            if (newFeeTotal > MAX_FEES_PER_ESCROW_PER_DAY) {
                emit EscrowRateLimitExceededEvent(
                    escrow,
                    'fees',
                    newFeeTotal,
                    MAX_FEES_PER_ESCROW_PER_DAY
                );
                revert EscrowRateLimitExceeded(escrow, newFeeTotal, MAX_FEES_PER_ESCROW_PER_DAY);
            }
            limit.feesToday = newFeeTotal;
        }
    }

    /**
     * @notice Pause an escrow contract (emergency stop)
     * @param escrowContract Address of escrow contract to pause
     * @dev Only timelock can pause escrows. Paused escrows cannot call incentive functions.
     */
    function pauseEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (!registeredEscrowContracts[escrowContract]) revert NotRegisteredEscrowContract(escrowContract);
        escrowRateLimits[escrowContract].paused = true;
        emit EscrowPausedEvent(escrowContract, _msgSender());
    }

    /**
     * @notice Unpause an escrow contract
     * @param escrowContract Address of escrow contract to unpause
     * @dev Only timelock can unpause escrows
     */
    function unpauseEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        escrowRateLimits[escrowContract].paused = false;
        emit EscrowUnpausedEvent(escrowContract, _msgSender());
    }

    /**
     * @notice Reset rate limit window for an escrow (emergency override)
     * @param escrowContract Address of escrow contract
     * @dev Only timelock can reset rate limits. Use with caution - only for legitimate emergencies.
     */
    function resetEscrowRateLimit(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        EscrowRateLimit storage limit = escrowRateLimits[escrowContract];
        limit.disputesToday = 0;
        limit.feesToday = 0;
        limit.windowStart = block.timestamp;
        emit EscrowRateLimitReset(escrowContract, block.timestamp);
    }

    /**
     * @notice Get rate limit status for an escrow
     * @param escrowContract Address of escrow contract
     * @return disputesToday Current disputes in window
     * @return feesToday Current fees in window
     * @return windowStart Start timestamp of current window
     * @return paused Whether escrow is paused
     * @return windowEnd When current window expires
     */
    function getEscrowRateLimit(
        address escrowContract
    )
        external
        view
        returns (
            uint256 disputesToday,
            uint256 feesToday,
            uint256 windowStart,
            bool paused,
            uint256 windowEnd
        )
    {
        EscrowRateLimit storage limit = escrowRateLimits[escrowContract];
        return (
            limit.disputesToday,
            limit.feesToday,
            limit.windowStart,
            limit.paused,
            limit.windowStart + RATE_LIMIT_WINDOW
        );
    }

    // ============ HIGH-2: Fee Recording Management Functions ============

    /**
     * @notice Clear expected balance for a dispute (if transfer validation fails)
     * @param workflowId The escrow transfer ID
     * @param reason Reason for clearing (for event logging)
     * @dev Only timelock can clear fee recordings. Use when escrow fails to transfer tokens
     *      and dispute needs to be reset or cancelled.
     */
    function clearFeeRecording(uint256 workflowId, address escrow, string memory reason) external onlyRole(ROLE_TIMELOCK) {
        delete disputeExpectedTokenBalance[escrow][workflowId];
        delete feeRecordedTimestamp[escrow][workflowId];
        // Note: Keep disputeEscrowFees and disputeEscalationFees for historical record
        emit FeeRecordingCleared(workflowId, reason);
    }

    // ============ Validation Functions ============

    /**
     * @notice Validate a library before queueing
     * @param libAddress Library address to validate
     * @return valid True if library is valid
     */
    function validateLibrary(address libAddress) public view returns (bool) {
        if (libAddress.code.length == 0) return false;

        // Check interface compliance
        try IPaymentCalculationLibrary(libAddress).validate() returns (bool valid) {
            if (!valid) return false;
        } catch {
            return false;
        }

        // Test with sample input
        PaymentInput memory testInput = createTestInput();
        try IPaymentCalculationLibrary(libAddress).calculatePayments(testInput) returns (
            PaymentOutput memory
        ) {
            return true;
        } catch {
            return false;
        }
    }

    /**
     * @notice Create test input for validation
     * @return testInput Test payment input
     */
    function createTestInput() internal view returns (PaymentInput memory) {
        ResolverRecord[] memory resolvers = new ResolverRecord[](2);
        resolvers[0] = ResolverRecord({
            resolver: address(0x1),
            level: 0,
            timestamp: 0 // Timestamp not needed for calculation
        });
        resolvers[1] = ResolverRecord({
            resolver: address(0x2),
            level: 1,
            timestamp: 0 // Timestamp not needed for calculation
        });

        return
            PaymentInput({
                escrowFee: 1000,
                escalationFees: 500,
                resolverSharePercentage: resolverSharePercentage,
                resolvers: resolvers,
                weights: weights
            });
    }

    // ============ View Functions ============

    /**
     * @notice Get pending library change
     * @return libAddress Pending library address
     * @return eta Activation timestamp
     * @return exists Whether pending change exists
     */
    function getPendingPaymentLibrary()
        external
        view
        returns (address libAddress, uint64 eta, bool exists)
    {
        return getPendingAddress(_pendingPaymentLibrary);
    }

    /**
     * @notice Get pending resolver share percentage change
     * @return percentage Pending percentage
     * @return eta Activation timestamp
     * @return exists Whether pending change exists
     */
    function getPendingResolverSharePercentage()
        external
        view
        returns (uint256 percentage, uint64 eta, bool exists)
    {
        return getPendingUint(_pendingResolverSharePercentage);
    }

    /**
     * @notice Get pending weights change
     * @return pendingWeights Pending weights
     * @return eta Activation timestamp
     * @return exists Whether pending change exists
     */
    function getPendingWeights()
        external
        view
        returns (Weights memory pendingWeights, uint64 eta, bool exists)
    {
        return (_pendingWeights.value, _pendingWeights.eta, _pendingWeights.exists);
    }

    /**
     * @notice Get resolvers for a dispute
     * @param workflowId The escrow transfer ID
     * @return resolvers Array of resolver records
     */
    function getDisputeResolvers(
        uint256 workflowId,
        address escrowContract
    ) external view returns (ResolverRecord[] memory) {
        return disputeResolvers[escrowContract][workflowId];
    }

    /**
     * @notice Get fee information for a dispute
     * @param workflowId The escrow transfer ID
     * @return escrowFee Escrow fee
     * @return escalationFees Total escalation fees
     */
    function getDisputeFees(
        uint256 workflowId,
        address escrowContract
    ) external view returns (uint256 escrowFee, uint256 escalationFees) {
        return (disputeEscrowFees[escrowContract][workflowId], disputeEscalationFees[escrowContract][workflowId]);
    }

    /**
     * @notice Check if payments have been distributed for a dispute
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @return distributed True if payments have been distributed
     */
    function arePaymentsDistributed(uint256 workflowId, address escrowContract) external view returns (bool) {
        return disputePaymentsDistributed[escrowContract][workflowId];
    }

    /**
     * @notice Check if payments have been calculated for a dispute
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @return calculated True if payments have been calculated (claimable)
     */
    function arePaymentsCalculated(uint256 workflowId, address escrowContract) external view returns (bool) {
        return paymentsCalculated[escrowContract][workflowId];
    }

    /**
     * @notice Get claimable payment amount for a resolver
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param resolver Resolver address
     * @return amount Claimable amount (0 if nothing to claim)
     */
    function getClaimablePayment(
        uint256 workflowId,
        address escrowContract,
        address resolver
    ) external view override returns (uint256) {
        return claimablePayments[escrowContract][workflowId][resolver];
    }

    function _requirePayoutToken(address escrowContract, uint256 workflowId, address token) internal view {
        address p = payoutToken[escrowContract][workflowId];
        if (p != address(0) && p != token) {
            revert InvalidPayoutToken(p, token);
        }
    }

    /**
     * @notice ERC165 interface support
     * @param interfaceId The interface identifier
     * @return True if the contract supports the interface
     * @dev AccessControlUpgradeable already includes ERC165Upgradeable
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import './ResolverIncentiveModuleV1.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';

/**
 * @title ResolverIncentiveModuleV2
 * @notice DR v2 incentive module: appeal bonds + escalation cost curves
 * @dev Inherits V1 performance tracking, adds financial commitment via bonds:
 *      - Escalation requires depositing a bond (V2)
 *      - Bonds refunded if decision changes (appeal succeeds)
 *      - Bonds paid to prior round's resolvers if decision upheld (appeal fails)
 *      - No resolver capital at risk (DR v3 feature)
 */
contract ResolverIncentiveModuleV2 is ResolverIncentiveModuleV1 {
    using SafeERC20 for IERC20;

    // ============ DR v2 Structures ============

    struct AppealBondRecord {
        address depositor; // Who deposited the bond (for ERC20: escrow contract, for ETH: user)
        address escalatedBy; // Who initiated the escalation (always the user/escalator)
        uint256 amount; // Bond amount
        address token; // Token address (address(0) = ETH)
        uint256 depositedAt; // Timestamp
        bool distributed; // Whether bond has been refunded/paid
        bool refunded; // True = refunded to depositor, False = paid to resolvers
    }

    // ============ DR v2 State Variables ============

    // Appeal bond storage: escrowContract => workflowId => round => AppealBondRecord
    mapping(address => mapping(uint256 => mapping(uint8 => AppealBondRecord))) public appealBonds;

    // Observability metrics
    uint256 public totalBondsPosted;
    uint256 public totalBondsRefunded;
    uint256 public totalBondsPaidToResolvers;
    uint256 public totalBondsForfeited;

    // Escalation depth histogram: round => count
    mapping(uint8 => uint256) public escalationDepthHistogram;

    // Note: payoutToken mapping is inherited from V1

    // ============ Feature Support Constants ============

    /// @dev Feature ID for appeal bonds support
    bytes4 public constant FEATURE_APPEAL_BONDS = bytes4(keccak256("APPEAL_BONDS_V1"));

    /// @dev Feature ID for pull-based ERC20 bonds
    bytes4 public constant FEATURE_PULL_ERC20_BONDS = bytes4(keccak256("PULL_ERC20_BONDS_V1"));

    // ============ DR v2 Constructor ============

    constructor(
        address initialOwner,
        address initialLibrary
    ) ResolverIncentiveModuleV1(initialOwner, initialLibrary) {}

    // ============ DR v2 Events ============

    event AppealBondRecorded(
        uint256 indexed workflowId,
        uint8 round,
        address indexed depositor,
        uint256 amount,
        address token
    );

    event AppealBondRefunded(
        uint256 indexed workflowId,
        uint8 round,
        address indexed depositor,
        uint256 amount,
        address token
    );

    event AppealBondPaidToResolvers(
        uint256 indexed workflowId,
        uint8 round,
        address[] resolvers,
        uint256 totalAmount,
        address token
    );

    event AppealBondForfeited(
        uint256 indexed workflowId,
        uint8 round,
        uint256 amount,
        address token,
        string reason
    );

    // ============ IIncentiveModule V2 Implementation ============

    /**
     * @notice Get required appeal bond for escalation (V2)
     * @dev This function is a stub for interface compliance.
     *      The actual bond calculation is done in DecentralizedResolutionModule.
     *      Callers should use IResolutionModule.getRequiredAppealBond() instead.
     *      This function always reverts to prevent misuse.
     * @return bondAmount Always reverts - use resolution module instead
     * @return token Always reverts - use resolution module instead
     */
    function getRequiredAppealBond(
        uint256 /* workflowId */,
        address /* escrowContract */,
        uint8 /* fromRound */,
        uint8 /* toRound */
    ) external pure override returns (uint256 /* bondAmount */, address /* token */) {
        // This function exists in IIncentiveModule for interface compliance,
        // but the actual calculation is done in DecentralizedResolutionModule
        // to maintain consistency and avoid duplication.
        //
        // Escrow contracts should call IResolutionModule.getRequiredAppealBond() directly.
        revert('Use IResolutionModule.getRequiredAppealBond() instead');
    }

    /**
     * @notice Check if module supports a specific feature
     * @param featureId Feature identifier (bytes4 keccak256 hash)
     * @return supported Whether the feature is supported
     */
    function supportsFeature(bytes4 featureId) external pure override returns (bool supported) {
        return featureId == FEATURE_APPEAL_BONDS || featureId == FEATURE_PULL_ERC20_BONDS;
    }

    /**
     * @notice Record appeal bond payment (V2)
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param depositor Address that deposited bond (for ERC20: escrow contract, for ETH: user/escalator)
     * @param escalatedBy Address that initiated the escalation (always the user/escalator)
     * @param amount Bond amount
     * @param token Token address (address(0) = ETH)
     * @param round Round being appealed to
     * @dev For ETH bonds: MUST be payable and require(msg.value == amount)
     *      For ETH bonds, depositor MUST equal escalatedBy (user-funded)
     * @dev For ERC20 bonds: Pulls tokens via safeTransferFrom(depositor, address(this), amount)
     *      and reverts on transfer failure. Depositor is typically the escrow contract (escrow-funded),
     *      but escalatedBy tracks the actual escalator for metrics/accounting.
     */
    function recordAppealBond(
        uint256 workflowId,
        address escrowContract,
        address depositor,
        address escalatedBy,
        uint256 amount,
        address token,
        uint8 round
    ) external payable override onlyEscrowContract {
        require(depositor != address(0), 'Invalid depositor');
        require(escalatedBy != address(0), 'Invalid escalatedBy');
        require(amount > 0, 'Invalid amount');
        require(round > 0 && round <= 2, 'Invalid round');
        require(appealBonds[escrowContract][workflowId][round].amount == 0, 'Bond already exists');
        require(!appealBonds[escrowContract][workflowId][round].distributed, 'Bond already distributed');

        // Enforce custody: pull funds atomically
        if (token == address(0)) {
            // ETH bond: require exact msg.value match
            require(msg.value == amount, 'ETH amount mismatch');
            // For ETH bonds, depositor must be the escalator (user-funded)
            require(depositor == escalatedBy, 'Depositor must be escalator for ETH bonds');
            // ETH must be sent by the caller (escrow contract) which received it from user
            // require(depositor == msg.sender, 'Depositor must be caller'); // Removed restrictive check
            // Funds are automatically received via payable
        } else {
            // ERC20 bond: pull tokens from depositor (pull-based pattern)
            // This ensures atomicity: if this call reverts, no tokens move
            // Depositor must approve this contract (the incentive module) for ERC20 bonds
            // SECURITY: Prevent arbitrary transferFrom - depositor must be caller or trusted custodian
            // Since this function is onlyEscrowContract, we trust the caller to specify the correct depositor
            // (either themselves or a trusted intermediary like BondCollector).

            IERC20(token).safeTransferFrom(depositor, address(this), amount);
        }

        // Enforce single payout token per dispute (CRITICAL: prevents token-mixing in claimablePayments)
        _requirePayoutToken(escrowContract, workflowId, token);

        // Record bond with actual received amount
        appealBonds[escrowContract][workflowId][round] = AppealBondRecord({
            depositor: depositor,
            escalatedBy: escalatedBy,
            amount: amount,
            token: token,
            depositedAt: block.timestamp,
            distributed: false,
            refunded: false
        });

        // Update metrics
        totalBondsPosted += amount;
        escalationDepthHistogram[round]++;

        emit AppealBondRecorded(workflowId, round, depositor, amount, token);
    }

    /**
     * @notice Distribute appeal bond based on outcome (V2)
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param round Round that was appealed FROM (bond depositor appealed decision at this round)
     * @param outcomeFlipped Whether the appeal succeeded (decision changed)
     * @dev If outcomeFlipped = true: refund to depositor
     *      If outcomeFlipped = false: pay to resolvers from 'round'
     * @dev Protected by reentrancy guard to prevent reentrancy attacks
     */
    function distributeAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 round,
        bool outcomeFlipped
    ) external override onlyEscrowContract nonReentrant {
        // Validate round bounds
        require(round < 2, 'Invalid round - no higher round');

        // Bond was posted to escalate FROM round to round+1
        // So we look up the bond at round+1
        uint8 bondRound = round + 1;
        AppealBondRecord storage bond = appealBonds[escrowContract][workflowId][bondRound];

        require(bond.amount > 0, 'No bond recorded');
        require(!bond.distributed, 'Bond already distributed');

        bond.distributed = true;
        // Clear bond amount for gas refunds and "cannot reuse" clarity
        uint256 bondAmount = bond.amount;
        bond.amount = 0;

        if (outcomeFlipped) {
            // Appeal succeeded - refund to depositor
            _refundBond(workflowId, escrowContract, bondRound, bond, bondAmount);
        } else {
            // Appeal failed - pay to resolvers from prior round
            _payBondToResolvers(workflowId, escrowContract, round, bond, bondAmount);
        }
    }

    /**
     * @notice Forfeit an appeal bond to the protocol
     * @param workflowId Unique identifier for the dispute
     * @param round Round the bond was posted for
     * @param reason Reason for forfeiture
     */
    function forfeitAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 round,
        string calldata reason
    ) external onlyEscrowContract nonReentrant {
        AppealBondRecord storage bond = appealBonds[escrowContract][workflowId][round];
        require(bond.amount > 0, 'No bond recorded');
        require(!bond.distributed, 'Bond already distributed');

        bond.distributed = true;
        uint256 amount = bond.amount;
        bond.amount = 0;
        totalBondsForfeited += amount;

        emit AppealBondForfeited(workflowId, round, amount, bond.token, reason);
    }

    /**
     * @notice Get appeal bond record
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param round Round bond was posted for
     * @return bond Appeal bond record
     */
    function getAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 round
    ) external view returns (AppealBondRecord memory bond) {
        return appealBonds[escrowContract][workflowId][round];
    }

    /**
     * @notice Get observability metrics for V2 (bonds)
     */
    function getV2Metrics()
        external
        view
        returns (
            uint256 posted,
            uint256 refunded,
            uint256 paidToResolvers,
            uint256 forfeited
        )
    {
        return (
            totalBondsPosted,
            totalBondsRefunded,
            totalBondsPaidToResolvers,
            totalBondsForfeited
        );
    }

    /**
     * @notice Get escalation depth histogram
     */
    function getEscalationDepthHistogram()
        external
        view
        returns (
            uint256 round0,
            uint256 round1,
            uint256 round2
        )
    {
        return (
            escalationDepthHistogram[0],
            escalationDepthHistogram[1],
            escalationDepthHistogram[2]
        );
    }

    /**
     * @notice Check if an appeal bond exists for a dispute round
     */
    function hasAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 round
    ) external view returns (bool) {
        return appealBonds[escrowContract][workflowId][round].amount > 0;
    }

    // ============ Internal DR v2 Functions ============

    // Note: _requirePayoutToken is inherited from V1

    /**
     * @notice Refund bond to depositor
     */
    function _refundBond(
        uint256 workflowId,
        address escrowContract,
        uint8 bondRound,
        AppealBondRecord storage bond,
        uint256 bondAmount
    ) internal {
        bond.refunded = true;
        totalBondsRefunded += bondAmount;

        // Refund bond back to the escalator.
        // For ETH bonds: depositor == escalatedBy (user-funded)
        // For ERC20 bonds: depositor may be an intermediary custodian (e.g., BondCollector),
        // but escalatedBy is always the user who should receive the refund.
        address refundTo = bond.escalatedBy;

        if (bond.token == address(0)) {
            // ETH
            (bool success, ) = refundTo.call{value: bondAmount}('');
            require(success, 'ETH refund failed');
        } else {
            // ERC20
            IERC20(bond.token).safeTransfer(refundTo, bondAmount);
        }

        emit AppealBondRefunded(workflowId, bondRound, bond.depositor, bondAmount, bond.token);
    }

    /**
     * @notice Pay bond to resolvers from prior round
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param priorRound Round whose resolvers should receive bond
     * @param bond Bond record
     * @param bondAmount Bond amount (bond.amount is cleared before this call)
     * @dev Only increments totalBondsPaidToResolvers when actually paid to resolvers
     *      If no resolvers found, bond is retained by protocol (not counted as "paid")
     */
    function _payBondToResolvers(
        uint256 workflowId,
        address escrowContract,
        uint8 priorRound,
        AppealBondRecord storage bond,
        uint256 bondAmount
    ) internal {
        bond.refunded = false;

        // Get resolvers from prior round
        ResolverRecord[] storage resolvers = disputeResolvers[escrowContract][workflowId];

        // If no resolvers in storage (e.g., testing scenario), bond is retained by protocol
        if (resolvers.length == 0) {
            // Don't increment totalBondsPaidToResolvers - bond is not actually paid
            // Bond remains in contract as protocol revenue
            emit AppealBondPaidToResolvers(
                workflowId,
                priorRound,
                new address[](0),
                bondAmount,
                bond.token
            );
            return;
        }

        // Find resolvers who decided at priorRound
        address[] memory eligibleResolvers = new address[](resolvers.length);
        uint256 count = 0;

        for (uint256 i = 0; i < resolvers.length; i++) {
            if (resolvers[i].level == priorRound) {
                eligibleResolvers[count] = resolvers[i].resolver;
                count++;
            }
        }

        // If no resolvers found at this round, bond is retained by protocol
        if (count == 0) {
            // Don't increment totalBondsPaidToResolvers - bond is not actually paid
            emit AppealBondPaidToResolvers(
                workflowId,
                priorRound,
                new address[](0),
                bondAmount,
                bond.token
            );
            return;
        }

        // Actually pay to resolvers - increment metric only now
        totalBondsPaidToResolvers += bondAmount;

        // Distribute bond equally among resolvers from that round
        uint256 amountPerResolver = bondAmount / count;
        uint256 remainder = bondAmount % count; // Handle rounding error

        // Add to claimable payments for each resolver
        for (uint256 i = 0; i < count; i++) {
            address resolver = eligibleResolvers[i];
            if (resolver != address(0)) {
                uint256 payment = amountPerResolver;
                if (i < remainder) payment += 1; // Distribute remainder 1-wei each to first 'remainder' resolvers

                claimablePayments[escrowContract][workflowId][resolver] += payment;
            }
        }

        emit AppealBondPaidToResolvers(
            workflowId,
            priorRound,
            eligibleResolvers,
            bondAmount,
            bond.token
        );
    }
}

// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import './ISlashingModule.sol';
import './ResolverStakingModuleV1.sol';
import './InsurancePoolVault.sol';
import '@openzeppelin/contracts/access/AccessControl.sol';
import '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';

/**
 * @title ResolverSlashingModuleV1
 * @notice Real slashing implementation for DR v3 with conservative penalties
 * @dev Key Features:
 *      - Trigger types: missed accept, missed resolve, unresponsive
 *      - No reversal slashing initially (too harsh for early rollout)
 *      - Conservative penalty schedule: 2% (accept), 5% (resolve), 10% (unresponsive)
 *      - Waterfall: Resolver bond first, then senior coverage after exhaustion
 *      - Circuit breakers: Mass unavailability detection → throttle assignments
 *
 * Security Properties:
 *      1. Slashes never exceed caps (per-slash and per-period)
 *      2. No double slashing (one slash per offense)
 *      3. Freeze logic prevents withdrawal during slash processing
 *      4. Waterfall ordering: junior exhausted before senior exposed
 */
contract ResolverSlashingModuleV1 is ISlashingModule, AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ Custom Errors ============
    error ZeroAddress(string field);
    error AlreadySlashedForWorkflow(address escrowContract, uint256 workflowId, address resolver);
    error SlashNotPending(uint256 slashId, SlashStatus currentStatus);
    error AppealWindowOpen(uint256 slashId, uint256 appealDeadline, uint256 currentTime);
    error AppealWindowClosed(uint256 slashId, uint256 appealDeadline, uint256 currentTime);
    error NotResolver(address caller, address expectedResolver);
    error AlreadyAppealed(uint256 slashId);
    error AppealAlreadyResolved(uint256 appealId);
    error FraudSlashingNotEnabled();
    error InvalidBps(uint256 bps, uint256 maxBps);
    error CooldownNotPassed(uint256 availableAt, uint256 currentTime);
    error ZeroAmount();
    error SlashNotFound(uint256 slashId);

    // ============ Constants ============

    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');
    bytes32 public constant ROLE_RESOLUTION_MODULE = keccak256('ROLE_RESOLUTION_MODULE');

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant PRECISION = 1e18;

    // v3 objective slashing schedule (basis points)
    uint256 public constant PENALTY_MISSED_ACCEPT = 25; // 0.25% (25 bps)
    uint256 public constant PENALTY_MISSED_RESOLVE = 200; // 2% (200 bps)
    uint256 public constant PENALTY_REPEAT_RESOLVE = 500; // 5% (500 bps) - repeat missed resolve in same epoch
    uint256 public constant PENALTY_REVERSAL = 0; // 0 bps initially (use reputation/workload only)

    // Epoch-based slash caps (v3)
    uint256 public constant EPOCH_LENGTH = 7 days;
    uint256 public constant RESOLVER_SLASH_CAP_BPS = 2000; // 20% per resolver per epoch
    uint256 public constant SENIOR_SLASH_CAP_BPS = 1000; // 10% per senior per epoch

    // Legacy slash caps (kept for backward compatibility)
    uint256 public constant MAX_SLASH_PER_OFFENSE = 5000; // 50% max per slash
    uint256 public constant MAX_SLASH_PER_PERIOD = 10000; // 100% max per 30 days
    uint256 public constant SLASH_PERIOD = 30 days;

    // Circuit breaker thresholds
    uint256 public constant MASS_UNAVAILABILITY_THRESHOLD = 3000; // 30% of resolvers
    uint256 public constant CIRCUIT_BREAKER_COOLDOWN = 1 hours;

    // SEW burn handling:
    // Prefer reducing totalSupply via ERC20Burnable.burn(uint256) if the token supports it.
    // Fallback is a transfer to a well-known dead address (effective burn, but supply not reduced).
    address public constant DEAD_BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    // ============ State Variables ============

    ResolverStakingModuleV1 public stakingModule;
    InsurancePoolVault public insurancePoolVault;
    IERC20 public stableToken;

    bool public circuitBreakerActive;
    uint256 public lastCircuitBreakerTrigger;

    // Slash tracking
    uint256 private _nextSlashId;
    mapping(uint256 => SlashEvent) public slashEvents; // slashId => SlashEvent
    mapping(uint256 => SlashAppeal) public slashAppeals; // slashId => SlashAppeal

    // Prevent double slashing
    mapping(address => mapping(uint256 => mapping(address => bool))) public workflowSlashed; // escrowContract => workflowId => resolver => slashed

    // Per-resolver slash tracking (for caps)
    struct SlashPeriodTracker {
        uint256 periodStart;
        uint256 totalSlashedInPeriod;
    }
    mapping(address => SlashPeriodTracker) public slashTrackers;

    // v3 epoch-based slash tracking
    struct EpochSlashTracker {
        uint256 epochStart;
        uint256 totalSlashedInEpoch;
        uint256 lastSlashTime;
        uint8 slashCount; // Count of slashes in this epoch
    }
    mapping(address => EpochSlashTracker) public epochSlashTrackers;

    // Freeze tracking (prevents withdrawal during slash processing)
    mapping(address => uint256) public frozenUntil; // resolver => timestamp
    mapping(address => uint256) public freezeUntil; // resolver => timestamp (for insufficient bond)

    // v3 freeze durations
    uint256 public constant FREEZE_DURATION_SEVERE = 72 hours; // Severe event (missed resolve deadline)
    uint256 public constant FREEZE_DURATION_REPEATED = 7 days; // Repeated severe event within epoch
    uint256 public constant FREEZE_DURATION_LEGACY = 7 days; // Legacy freeze duration (backward compatibility)

    // Mass unavailability tracking
    struct UnavailabilityStats {
        uint256 totalResolvers;
        uint256 unavailableCount;
        uint256 lastUpdate;
    }
    UnavailabilityStats public unavailabilityStats;

    // Slash config (governance-controlled)
    SlashConfig public slashConfig;

    // ============ Events ============

    event SlashExecutedWithWaterfall(
        uint256 indexed slashId,
        address indexed resolver,
        address indexed senior,
        uint256 resolverSlashed,
        uint256 seniorSlashed,
        uint256 totalSlashed
    );
    event ResolverFrozen(address indexed resolver, uint256 frozenUntil);
    event ResolverUnfrozen(address indexed resolver);
    event MassUnavailabilityDetected(
        uint256 unavailableCount,
        uint256 totalResolvers,
        uint256 percentage
    );
    event CircuitBreakerActivated(string reason);
    event CircuitBreakerDeactivated();
    event SlashCapEnforced(
        address indexed resolver,
        uint256 requestedSlash,
        uint256 actualSlash,
        string reason
    );

    event SlashedSEWHandled(uint256 indexed workflowId, uint256 amount, bool supplyReduced);

    // ============ Initialization ============

    constructor(
        address initialOwner,
        address _stakingModule,
        address _insurancePoolVault,
        address _stableToken
    ) {
        if (_stakingModule == address(0)) revert ZeroAddress('stakingModule');
        if (_insurancePoolVault == address(0)) revert ZeroAddress('insurancePoolVault');
        if (_stableToken == address(0)) revert ZeroAddress('stableToken');

        // OpenZeppelin best practice: Grant DEFAULT_ADMIN_ROLE to deployer
        // Deployment scripts will transfer this to TimelockController
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);

        stakingModule = ResolverStakingModuleV1(_stakingModule);
        insurancePoolVault = InsurancePoolVault(_insurancePoolVault);
        stableToken = IERC20(_stableToken);

        // Note: ROLE_SLASHING_MODULE must be granted by vault admin after initialization
        // This is done in test setup and deployment scripts

        _nextSlashId = 1;
        circuitBreakerActive = false;

        // Initialize slash config with conservative defaults
        slashConfig = SlashConfig({
            timeoutSlashBps: PENALTY_MISSED_RESOLVE, // 200 bps (2%)
            reversalSlashBps: PENALTY_REVERSAL, // 0 bps initially (disabled)
            fraudSlashBps: 0, // Not implemented yet
            maxSlashPerPeriod: MAX_SLASH_PER_PERIOD,
            slashPeriod: SLASH_PERIOD,
            appealWindow: 3 days,
            appealBond: 100e18 // 100 USD
        });
    }

    // ============ Core Slashing Functions ============

    /**
     * @notice Propose a slash (not used in automated flow, for manual slashes)
     */
    function proposeSlash(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        SlashReason reason,
        bytes calldata evidence
    ) external override onlyRole(ROLE_TIMELOCK) returns (uint256 slashId) {
        if (workflowSlashed[escrowContract][workflowId][resolver]) {
            revert AlreadySlashedForWorkflow(escrowContract, workflowId, resolver);
        }

        slashId = _nextSlashId++;

        uint256 slashAmount = _calculateSlashAmount(resolver, reason);

        slashEvents[slashId] = SlashEvent({
            slashId: slashId,
            workflowId: workflowId,
            escrowContract: escrowContract,
            resolver: resolver,
            reason: reason,
            amount: slashAmount,
            proposedAt: block.timestamp,
            executedAt: 0,
            appealDeadline: block.timestamp + slashConfig.appealWindow,
            status: SlashStatus.PENDING,
            proposer: _msgSender(),
            evidence: evidence
        });

        emit SlashProposed(slashId, workflowId, resolver, reason, slashAmount, _msgSender());
        return slashId;
    }

    /**
     * @notice Execute a slash (with waterfall: resolver → senior)
     */
    function executeSlash(uint256 slashId) external override nonReentrant onlyRole(ROLE_TIMELOCK) {
        SlashEvent storage slashEvent = slashEvents[slashId];
        if (slashEvent.slashId == 0) revert SlashNotFound(slashId);

        if (slashEvent.status != SlashStatus.PENDING) revert SlashNotPending(slashId, slashEvent.status);
        if (block.timestamp <= slashEvent.appealDeadline) {
            revert AppealWindowOpen(slashId, slashEvent.appealDeadline, block.timestamp);
        }

        address resolver = slashEvent.resolver;
        uint256 slashAmount = slashEvent.amount;

        // Reset tracking before slash
        _currentSlashStableAmount = 0;
        _currentSlashSewAmount = 0;

        // Execute waterfall slash
        (uint256 resolverSlashed, uint256 seniorSlashed, address senior) = _executeWaterfallSlash(
            resolver,
            slashAmount
        );

        uint256 totalSlashed = resolverSlashed + seniorSlashed;

        // Update slash event
        slashEvent.status = SlashStatus.EXECUTED;
        slashEvent.executedAt = block.timestamp;

        // Mark as slashed
        workflowSlashed[slashEvent.escrowContract][slashEvent.workflowId][resolver] = true;

        // Freeze resolver
        _freezeResolver(resolver);

        // Distribute slashed funds (using actual token amounts received)
        SlashDistribution memory distribution = _distributeSlashedFunds(
            _currentSlashStableAmount,
            slashEvent.reason,
            slashEvent.workflowId
        );

        // Reset tracking after distribution
        _currentSlashStableAmount = 0;
        _currentSlashSewAmount = 0;

        emit SlashExecuted(slashId, resolver, totalSlashed, distribution);
        emit SlashExecutedWithWaterfall(
            slashId,
            resolver,
            senior,
            resolverSlashed,
            seniorSlashed,
            totalSlashed
        );
    }

    /**
     * @notice Appeal a slash
     */
    function appealSlash(
        uint256 slashId,
        string calldata reason,
        bytes calldata evidence
    ) external override nonReentrant {
        SlashEvent storage slashEvent = slashEvents[slashId];
        if (slashEvent.slashId == 0) revert SlashNotFound(slashId);

        if (slashEvent.status != SlashStatus.PENDING) revert SlashNotPending(slashId, slashEvent.status);
        if (block.timestamp > slashEvent.appealDeadline) {
            revert AppealWindowClosed(slashId, slashEvent.appealDeadline, block.timestamp);
        }
        if (_msgSender() != slashEvent.resolver) revert NotResolver(_msgSender(), slashEvent.resolver);
        if (slashAppeals[slashId].slashId != 0 && slashAppeals[slashId].slashId != 0 && slashAppeals[slashId].resolved) {
            revert AlreadyAppealed(slashId);
        }

        // Record appeal
        slashAppeals[slashId] = SlashAppeal({
            slashId: slashId,
            appellant: _msgSender(),
            appealBond: slashConfig.appealBond,
            appealedAt: block.timestamp,
            reason: reason,
            evidence: evidence,
            resolved: false,
            upheld: false
        });

        emit SlashAppealed(slashId, _msgSender(), slashConfig.appealBond, reason);
    }

    /**
     * @notice Resolve an appeal
     */
    function resolveAppeal(uint256 slashId, bool upheld) external override onlyRole(ROLE_TIMELOCK) {
        SlashAppeal storage appeal = slashAppeals[slashId];
        SlashEvent storage slashEvent = slashEvents[slashId];
        if (slashEvent.slashId == 0) revert SlashNotFound(slashId);

        if (appeal.resolved) revert AppealAlreadyResolved(slashId);
        if (slashEvent.status != SlashStatus.PENDING) revert SlashNotPending(slashId, slashEvent.status);

        appeal.resolved = true;
        appeal.upheld = upheld;

        if (!upheld) {
            // Appeal rejected, slash proceeds
            emit SlashAppealResolved(slashId, false, address(0), 0);
        } else {
            // Appeal accepted, cancel slash
            slashEvent.status = SlashStatus.REVERSED;
            emit SlashReversed(slashId, slashEvent.resolver, slashEvent.amount);
            emit SlashAppealResolved(slashId, true, slashEvent.resolver, slashEvent.amount);
        }
    }

    // ============ Automated Slashing (Called by Resolution Module) ============

    /**
     * @notice Slash for timeout (missed accept or missed resolve)
     * @param workflowId Dispute ID
     * @param escrowContract Related escrow contract
     * @param resolver Resolver who timed out
     * @param timeoutType 0 = accept, 1 = resolve
     */
    function slashForTimeout(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        uint8 timeoutType
    ) external override onlyRole(ROLE_RESOLUTION_MODULE) returns (uint256 slashId) {
        // Reset tracking before slash
        _currentSlashStableAmount = 0;
        _currentSlashSewAmount = 0;

        // Check if already slashed for this workflow
        if (workflowSlashed[escrowContract][workflowId][resolver]) {
            return 0; // Already slashed, skip
        }

        // Check circuit breaker
        if (circuitBreakerActive) {
            emit SlashCapEnforced(resolver, 0, 0, 'Circuit breaker active');
            return 0;
        }

        // Determine slash reason and amount
        SlashReason reason = (timeoutType == 0)
            ? SlashReason.TIMEOUT_ACCEPT
            : SlashReason.TIMEOUT_RESOLVE;

        uint256 slashAmount = _calculateSlashAmount(resolver, reason);

        // Check if slash would exceed caps
        slashAmount = _enforceSlashCaps(resolver, slashAmount);

        if (slashAmount == 0) {
            return 0; // Cap reached, skip slash
        }

        // Create slash event
        slashId = _nextSlashId++;

        slashEvents[slashId] = SlashEvent({
            slashId: slashId,
            workflowId: workflowId,
            escrowContract: escrowContract,
            resolver: resolver,
            reason: reason,
            amount: slashAmount,
            proposedAt: block.timestamp,
            executedAt: block.timestamp, // Auto-execute
            appealDeadline: 0, // No appeal for automated slashes
            status: SlashStatus.EXECUTED,
            proposer: _msgSender(),
            evidence: ''
        });

        // Execute waterfall slash immediately
        (uint256 resolverSlashed, uint256 seniorSlashed, address senior) = _executeWaterfallSlash(
            resolver,
            slashAmount
        );

        uint256 totalSlashed = resolverSlashed + seniorSlashed;

        // Mark as slashed
        workflowSlashed[escrowContract][workflowId][resolver] = true;

        // Freeze resolver
        _freezeResolver(resolver);

        // Distribute slashed funds (using actual token amounts received from staking module)
        SlashDistribution memory distribution = _distributeSlashedFunds(
            _currentSlashStableAmount,
            reason,
            workflowId
        );

        // Reset tracking after distribution
        _currentSlashStableAmount = 0;
        _currentSlashSewAmount = 0;

        // Update unavailability stats
        _updateUnavailabilityStats(resolver, true);

        emit SlashProposed(slashId, workflowId, resolver, reason, slashAmount, _msgSender());
        emit SlashExecuted(slashId, resolver, totalSlashed, distribution);
        emit SlashExecutedWithWaterfall(
            slashId,
            resolver,
            senior,
            resolverSlashed,
            seniorSlashed,
            totalSlashed
        );
        return slashId;
    }

