        emit SlashProposed(slashId, workflowId, resolver, reason, slashAmount, _msgSender());
        emit SlashExecuted(slashId, resolver, totalSlashed, distribution);
        emit SlashExecutedWithWaterfall(
            slashId,
            resolver,
            senior,
            resolverSlashed,
            seniorSlashed,
            totalSlashed
        );

        return slashId;
    }

    // ============ Internal Functions ============

    /**
     * @notice Execute waterfall slash: resolver bond first, then senior coverage
     * @return resolverSlashed Amount slashed from resolver
     * @return seniorSlashed Amount slashed from senior
     * @return senior Address of senior (if any)
     */
    function _executeWaterfallSlash(
        address resolver,
        uint256 slashAmount
    ) internal returns (uint256 resolverSlashed, uint256 seniorSlashed, address senior) {
        // Get resolver's stake info
        IStakingModule.StakeInfo memory stakeInfo = stakingModule.getStakeInfo(resolver);

        // Get delegation info (if junior)
        IStakingModule.DelegationInfo memory delegation;
        uint8 tier = stakingModule.resolverTier(resolver);

        if (tier == 0) {
            // Junior resolver - check for delegation
            delegation = _findDelegation(resolver);
        }

        // Calculate waterfall
        uint256 availableStake = stakeInfo.availableStake;

        if (slashAmount <= availableStake) {
            // Resolver's stake covers the slash
            resolverSlashed = slashAmount;
            seniorSlashed = 0;
            senior = address(0);

            // Slash resolver's stake (via staking module)
            _slashResolverStake(resolver, resolverSlashed);
        } else {
            // Resolver's stake exhausted, slash senior coverage
            resolverSlashed = availableStake;
            uint256 remaining = slashAmount - availableStake;

            if (delegation.active && remaining > 0) {
                // Slash from senior's coverage
                senior = delegation.delegatee;
                seniorSlashed = remaining;

                // Slash resolver's remaining stake
                if (resolverSlashed > 0) {
                    _slashResolverStake(resolver, resolverSlashed);
                }

                // Slash senior's coverage
                _slashSeniorCoverage(senior, seniorSlashed, resolver);
            } else {
                // No senior coverage, slash only what's available
                if (resolverSlashed > 0) {
                    _slashResolverStake(resolver, resolverSlashed);
                }
                seniorSlashed = 0;
                senior = address(0);
            }
        }
    }

    /**
     * @notice Calculate slash amount based on reason
     */
    function _calculateSlashAmount(
        address resolver,
        SlashReason reason
    ) internal view returns (uint256) {
        IStakingModule.StakeInfo memory stakeInfo = stakingModule.getStakeInfo(resolver);
        uint256 totalStake = stakeInfo.totalStake;

        uint256 penaltyBps;

        if (reason == SlashReason.TIMEOUT_ACCEPT) {
            penaltyBps = PENALTY_MISSED_ACCEPT; // 25 bps (0.25%)
        } else if (reason == SlashReason.TIMEOUT_RESOLVE) {
            // Check if this is a repeat offense in the same epoch
            EpochSlashTracker storage epochTracker = epochSlashTrackers[resolver];
            uint256 currentEpochStart = (block.timestamp / EPOCH_LENGTH) * EPOCH_LENGTH; // forge-lint: disable-line(divide-before-multiply)

            // If resolver already slashed in this epoch, use repeat penalty
            if (epochTracker.epochStart == currentEpochStart && epochTracker.slashCount > 0) {
                penaltyBps = PENALTY_REPEAT_RESOLVE; // 500 bps (5%) for repeat
            } else {
                penaltyBps = PENALTY_MISSED_RESOLVE; // 200 bps (2%) for first offense
            }
        } else if (reason == SlashReason.REVERSAL) {
            penaltyBps = slashConfig.reversalSlashBps;
        } else if (reason == SlashReason.FRAUD) {
            penaltyBps = slashConfig.fraudSlashBps;
        } else {
            penaltyBps = PENALTY_REPEAT_RESOLVE; // Use repeat penalty as fallback
        }

        uint256 slashAmount = (totalStake * penaltyBps) / BASIS_POINTS;

        // Enforce per-offense cap
        uint256 maxPerOffense = (totalStake * MAX_SLASH_PER_OFFENSE) / BASIS_POINTS;
        if (slashAmount > maxPerOffense) {
            slashAmount = maxPerOffense;
        }

        return slashAmount;
    }

    /**
     * @notice Enforce slash caps (per-period limit and per-epoch limit)
     */
    function _enforceSlashCaps(
        address resolver,
        uint256 requestedSlash
    ) internal returns (uint256 actualSlash) {
        SlashPeriodTracker storage tracker = slashTrackers[resolver];
        EpochSlashTracker storage epochTracker = epochSlashTrackers[resolver];

        // Check if new period
        if (block.timestamp >= tracker.periodStart + slashConfig.slashPeriod) {
            // Reset period
            tracker.periodStart = block.timestamp;
            tracker.totalSlashedInPeriod = 0;
        }

        // Check if new epoch (v3 epoch-based caps)
        uint256 currentEpochStart = (block.timestamp / EPOCH_LENGTH) * EPOCH_LENGTH; // forge-lint: disable-line(divide-before-multiply)
        if (epochTracker.epochStart != currentEpochStart) {
            // Reset epoch
            epochTracker.epochStart = currentEpochStart;
            epochTracker.totalSlashedInEpoch = 0;
            epochTracker.slashCount = 0;
        }

        // Get resolver's total stake and tier
        IStakingModule.StakeInfo memory stakeInfo = stakingModule.getStakeInfo(resolver);
        uint256 totalStake = stakeInfo.totalStake;
        uint8 tier = stakingModule.resolverTier(resolver);

        // Calculate max allowed in period (legacy cap)
        uint256 maxInPeriod = (totalStake * slashConfig.maxSlashPerPeriod) / BASIS_POINTS;
        uint256 remainingInPeriod = maxInPeriod > tracker.totalSlashedInPeriod
            ? maxInPeriod - tracker.totalSlashedInPeriod
            : 0;

        // Calculate max allowed in epoch (v3 cap)
        uint256 epochCapBps = (tier == 1) ? SENIOR_SLASH_CAP_BPS : RESOLVER_SLASH_CAP_BPS;
        uint256 maxInEpoch = (totalStake * epochCapBps) / BASIS_POINTS;
        uint256 remainingInEpoch = maxInEpoch > epochTracker.totalSlashedInEpoch
            ? maxInEpoch - epochTracker.totalSlashedInEpoch
            : 0;

        // Enforce both caps (use the more restrictive)
        uint256 maxAllowed = remainingInPeriod < remainingInEpoch ? remainingInPeriod : remainingInEpoch;

        if (requestedSlash > maxAllowed) {
            actualSlash = maxAllowed;
            string memory reason = remainingInPeriod < remainingInEpoch ? 'Period cap reached' : 'Epoch cap reached';
            emit SlashCapEnforced(resolver, requestedSlash, actualSlash, reason);
        } else {
            actualSlash = requestedSlash;
        }

        // Update trackers
        tracker.totalSlashedInPeriod += actualSlash;
        epochTracker.totalSlashedInEpoch += actualSlash;
        epochTracker.slashCount++;
        epochTracker.lastSlashTime = block.timestamp;
    }

    // Track slashed token amounts for distribution
    uint256 private _currentSlashStableAmount;
    uint256 private _currentSlashSewAmount;

    /**
     * @notice Slash resolver's stake (real implementation)
     */
    function _slashResolverStake(address resolver, uint256 amount) internal {
        if (amount == 0) return;

        // Call staking module to slash resolver's bond
        (uint256 stableSlashed, uint256 sewSlashed) = stakingModule.slash(resolver, amount);

        // Track amounts for distribution
        _currentSlashStableAmount += stableSlashed;
        _currentSlashSewAmount += sewSlashed;
    }

    /**
     * @notice Slash senior's coverage (real implementation)
     */
    function _slashSeniorCoverage(address senior, uint256 amount, address slashedFor) internal {
        if (amount == 0) return;

        // Call staking module to slash senior's coverage
        (uint256 stableSlashed, uint256 sewSlashed) = stakingModule.slashCoverage(
            senior,
            amount,
            slashedFor
        );

        // Track amounts for distribution
        _currentSlashStableAmount += stableSlashed;
        _currentSlashSewAmount += sewSlashed;
    }

    /**
     * @notice Find delegation for a resolver
     */
    function _findDelegation(
        address resolver
    ) internal view returns (IStakingModule.DelegationInfo memory) {
        // Access the public delegations mapping via low-level call
        (bool success, bytes memory data) = address(stakingModule).staticcall(
            abi.encodeWithSignature('delegations(address)', resolver)
        );

        if (success && data.length >= 128) {
            // Decode the tuple: (address senior, uint256 coverageAmount, uint256 delegatedAt, bool active)
            (address senior, uint256 coverageAmount, uint256 delegatedAt, bool active) = abi.decode(
                data,
                (address, uint256, uint256, bool)
            );

            if (active && senior != address(0)) {
                return
                    IStakingModule.DelegationInfo({
                        delegator: resolver,
                        delegatee: senior,
                        amount: coverageAmount,
                        delegatedAt: delegatedAt,
                        active: true
                    });
            }
        }

        return
            IStakingModule.DelegationInfo({
                delegator: resolver,
                delegatee: address(0),
                amount: 0,
                delegatedAt: 0,
                active: false
            });
    }

    /**
     * @notice Distribute slashed funds
     */
    function _distributeSlashedFunds(
        uint256 amount,
        SlashReason reason,
        uint256 workflowId
    ) internal returns (SlashDistribution memory distribution) {
        distribution.toInsurancePool = (amount * 5000) / BASIS_POINTS;
        distribution.toProtocol = (amount * 3000) / BASIS_POINTS;
        distribution.toCounterParty = 0;
        distribution.toSlashProposer = 0;

        // Transfer insurance pool portion to vault
        if (amount > 0 && distribution.toInsurancePool > 0 && address(insurancePoolVault) != address(0)) {
            stableToken.safeTransfer(address(insurancePoolVault), distribution.toInsurancePool);
            insurancePoolVault.recordDeposit(distribution.toInsurancePool, reason, workflowId, address(0));
        }

        // Burn any slashed SEW received from the staking module for this slash
        _handleSlashedSEW(workflowId);

        return distribution;
    }

    /**
     * @notice Handle slashed SEW from the staking module (burn)
     */
    function _handleSlashedSEW(uint256 workflowId) internal {
        uint256 amount = _currentSlashSewAmount;
        if (amount == 0) return;

        IERC20 sew = IERC20(stakingModule.sewToken());

        // Try to burn (preferred: reduces totalSupply)
        (bool ok, ) = address(sew).call(abi.encodeWithSignature('burn(uint256)', amount));
        if (ok) {
            emit SlashedSEWHandled(workflowId, amount, true);
            return;
        }

        // Fallback: transfer to dead address (effective burn)
        sew.safeTransfer(DEAD_BURN_ADDRESS, amount);
        emit SlashedSEWHandled(workflowId, amount, false);
    }

    /**
     * @notice Freeze resolver (prevents withdrawal during slash processing)
     */
    function _freezeResolver(address resolver) internal {
        EpochSlashTracker storage epochTracker = epochSlashTrackers[resolver];
        uint256 currentEpochStart = (block.timestamp / EPOCH_LENGTH) * EPOCH_LENGTH; // forge-lint: disable-line(divide-before-multiply)

        // Determine freeze duration based on context
        uint256 freezeDuration;

        // Check if this is a repeated offense in the same epoch
        if (epochTracker.epochStart == currentEpochStart && epochTracker.slashCount > 1) {
            freezeDuration = FREEZE_DURATION_REPEATED; // 7 days
        } else {
            freezeDuration = FREEZE_DURATION_SEVERE; // 72 hours
        }

        frozenUntil[resolver] = block.timestamp + freezeDuration;
        emit ResolverFrozen(resolver, frozenUntil[resolver]);
    }

    /**
     * @notice Update unavailability stats (for circuit breaker)
     */
    function _updateUnavailabilityStats(address /* resolver */, bool unavailable) internal {
        UnavailabilityStats storage stats = unavailabilityStats;
        stats.lastUpdate = block.timestamp;

        if (unavailable) {
            stats.unavailableCount++;
        }

        if (stats.totalResolvers > 0) {
            uint256 unavailablePercentage = (stats.unavailableCount * BASIS_POINTS) /
                stats.totalResolvers;

            if (unavailablePercentage >= MASS_UNAVAILABILITY_THRESHOLD) {
                _triggerCircuitBreaker('Mass unavailability detected');
                emit MassUnavailabilityDetected(
                    stats.unavailableCount,
                    stats.totalResolvers,
                    unavailablePercentage
                );
            }
        }
    }

    /**
     * @notice Trigger circuit breaker
     */
    function _triggerCircuitBreaker(string memory reason) internal {
        if (!circuitBreakerActive) {
            circuitBreakerActive = true;
            lastCircuitBreakerTrigger = block.timestamp;
            emit CircuitBreakerActivated(reason);
        }
    }

    // ============ Query Functions ============

    function getSlashEvent(uint256 slashId) external view override returns (SlashEvent memory) {
        return slashEvents[slashId];
    }

    function getSlashAppeal(uint256 slashId) external view override returns (SlashAppeal memory) {
        return slashAppeals[slashId];
    }

    function calculateSlashAmount(
        address resolver,
        SlashReason reason
    ) external view override returns (uint256) {
        return _calculateSlashAmount(resolver, reason);
    }

    function getSlashableStake(address resolver) external view override returns (uint256) {
        IStakingModule.StakeInfo memory stakeInfo = stakingModule.getStakeInfo(resolver);
        return stakeInfo.availableStake;
    }

    function getSlashedInPeriod(address resolver) external view override returns (uint256) {
        return slashTrackers[resolver].totalSlashedInPeriod;
    }

    function getSlashConfig() external view override returns (SlashConfig memory) {
        return slashConfig;
    }

    function canAppeal(uint256 slashId) external view override returns (bool) {
        SlashEvent storage slashEvent = slashEvents[slashId];
        return
            slashEvent.status == SlashStatus.PENDING &&
            block.timestamp <= slashEvent.appealDeadline &&
            slashAppeals[slashId].slashId == 0;
    }

    function canExecute(uint256 slashId) external view override returns (bool) {
        SlashEvent storage slashEvent = slashEvents[slashId];
        return
            slashEvent.status == SlashStatus.PENDING && block.timestamp > slashEvent.appealDeadline;
    }

    function getInsurancePoolBalance() external view override returns (uint256) {
        if (address(insurancePoolVault) != address(0)) {
            return insurancePoolVault.getTotalBalance();
        }
        return 0;
    }

    function isResolverFrozen(address resolver) external view returns (bool frozen, uint256 until) {
        frozen = block.timestamp < frozenUntil[resolver];
        until = frozenUntil[resolver];
    }

    // ============ Distribution Functions ============

    function calculateDistribution(
        uint256 amount,
        SlashReason /* reason */
    ) external pure override returns (SlashDistribution memory) {
        return SlashDistribution({
            toProtocol: (amount * 3000) / BASIS_POINTS,
            toCounterParty: 0,
            toInsurancePool: (amount * 5000) / BASIS_POINTS,
            toSlashProposer: 0
        });
    }

    function claimInsurancePayout(
        uint256 /* workflowId */,
        address /* to */,
        uint256 /* amount */
    ) external pure override {
        revert('Use InsurancePoolVault.proposePayout() instead');
    }

    // ============ Admin Functions ============

    function setSlashPercentage(SlashReason reason, uint256 bps) external override onlyRole(ROLE_TIMELOCK) {
        if (bps > BASIS_POINTS) revert InvalidBps(bps, BASIS_POINTS);

        uint256 oldBps;

        if (reason == SlashReason.TIMEOUT_ACCEPT || reason == SlashReason.TIMEOUT_RESOLVE) {
            oldBps = slashConfig.timeoutSlashBps;
            slashConfig.timeoutSlashBps = bps;
        } else if (reason == SlashReason.REVERSAL) {
            oldBps = slashConfig.reversalSlashBps;
            slashConfig.reversalSlashBps = bps;
        } else {
            oldBps = slashConfig.fraudSlashBps;
            slashConfig.fraudSlashBps = bps;
        }

        emit SlashConfigUpdated(reason, oldBps, bps);
    }

    function setMaxSlashPerPeriod(uint256 max, uint256 period) external override onlyRole(ROLE_TIMELOCK) {
        slashConfig.maxSlashPerPeriod = max;
        slashConfig.slashPeriod = period;
    }

    function setAppealWindow(uint256 window) external override onlyRole(ROLE_TIMELOCK) {
        slashConfig.appealWindow = window;
    }

    function setAppealBond(uint256 bond) external override onlyRole(ROLE_TIMELOCK) {
        slashConfig.appealBond = bond;
    }

    function fundInsurancePool(uint256 amount) external override {
        if (address(insurancePoolVault) != address(0)) {
            stableToken.safeTransferFrom(_msgSender(), address(this), amount);
            stableToken.safeTransfer(address(insurancePoolVault), amount);
            insurancePoolVault.recordDeposit(amount, SlashReason.TIMEOUT_ACCEPT, 0, address(0));
        }
    }

    /**
     * @notice Set insurance pool vault (governance)
     */
    function setInsurancePoolVault(address vault) external onlyRole(ROLE_TIMELOCK) {
        insurancePoolVault = InsurancePoolVault(vault);
    }

    function triggerCircuitBreaker(string memory reason) external override onlyRole(ROLE_TIMELOCK) {
        _triggerCircuitBreaker(reason);
    }

    function resetCircuitBreaker() external override onlyRole(ROLE_TIMELOCK) {
        uint256 availableAt = lastCircuitBreakerTrigger + CIRCUIT_BREAKER_COOLDOWN;
        if (block.timestamp < availableAt) {
            revert CooldownNotPassed(availableAt, block.timestamp);
        }
        circuitBreakerActive = false;
        emit CircuitBreakerDeactivated();
    }

    function unfreezeResolver(address resolver) external onlyRole(ROLE_TIMELOCK) {
        frozenUntil[resolver] = 0;
        emit ResolverUnfrozen(resolver);
    }

    function setUnavailabilityStats(
        uint256 totalResolvers,
        uint256 unavailableCount
    ) external onlyRole(ROLE_TIMELOCK) {
        unavailabilityStats.totalResolvers = totalResolvers;
        unavailabilityStats.unavailableCount = unavailableCount;
        unavailabilityStats.lastUpdate = block.timestamp;
    }
}

// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import './IStakingModule.sol';
import './BondValuationLibrary.sol';
import '@openzeppelin/contracts/access/AccessControl.sol';
import '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';

/**
 * @notice Minimal interface for burnable ERC20 tokens
 * @dev Used for burning SEW tokens when slashed
 */
interface IERC20Burnable {
    function burn(uint256 amount) external;
}

/**
 * @title ResolverStakingModuleV1
 * @notice Real staking implementation for DR v3 with mixed stable/SEW bonds
 * @dev Key Features:
 *      - ERC20 stablecoin staking (primary)
 *      - SEW token staking (custody, non-transferable while bonded)
 *      - Mix enforcement: 80% stable minimum, 20% SEW maximum (50% haircut)
 *      - Unbonding delays: 14 days (resolvers), 21 days (seniors)
 *      - Delegation coverage: M=3 multiplier, U=50% utilization
 *      - Coverage accounting: reservedCoverage <= availableCoverage
 *
 * Security Properties:
 *      1. Mix constraints always hold (80/20 rule)
 *      2. Reserved coverage never exceeds available coverage
 *      3. Withdrawals cannot bypass freeze/unbond delays
 *      4. Senior coverage only exposed after resolver exhausted
 */
contract ResolverStakingModuleV1 is IStakingModule, AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using BondValuationLibrary for *;

    // ============ Custom Errors ============
    error ZeroAddress(string field);
    error NoStake(address resolver);
    error ContractPaused();
    error ZeroStakeAmount();
    error InvalidBondMix(uint256 stableBps, uint256 sewBps);
    error BelowMinimumStake(address resolver, uint256 effectiveBond, uint256 minimumStake, uint8 tier);
    error ResolverFrozen(address resolver);
    error InsufficientStableBalance(address resolver, uint256 available, uint256 required);
    error InsufficientSEWBalance(address resolver, uint256 available, uint256 required);
    error NotActive(address resolver, StakeStatus status);
    error UnbondRequestPending(address resolver);
    error StakeLockedInDisputes(address resolver, uint256 lockedAmount);
    error CoverageAlreadyReserved(address resolver, uint256 reservedAmount);
    error MustUndelegateFirst(address resolver);
    error RemainingBondInvalidMix(uint256 stableBps, uint256 sewBps);
    error BelowMinimumAfterUnbond(address resolver, uint256 remainingBond, uint256 minimumStake, uint8 tier);
    error NoUnbondRequest(address resolver);
    error UnbondDelayNotPassed(address resolver, uint256 availableAt, uint256 currentTime);
    error CannotDelegateToSelf(address resolver);
    error OnlyResolversCanDelegate(address junior, uint8 tier);
    error MustDelegateToSenior(address senior, uint8 tier);
    error AlreadyDelegated(address junior);
    error JuniorNotActive(address junior, StakeStatus status);
    error SeniorNotActive(address senior, StakeStatus status);
    error InsufficientSeniorCoverage(address senior, uint256 available, uint256 required);
    error NotDelegated(address junior);
    error WrongSenior(address junior, address expected, address actual);
    error InsufficientAvailableStake(address resolver, uint256 available, uint256 required);
    error InsufficientBond(address resolver, uint256 effectiveBond, uint256 required);
    error InvalidTier(uint8 tier, uint8 maxTier);

    // ============ Constants ============

    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');
    bytes32 public constant ROLE_RESOLUTION_MODULE = keccak256('ROLE_RESOLUTION_MODULE');
    bytes32 public constant ROLE_SLASHING_MODULE = keccak256('ROLE_SLASHING_MODULE');

    uint256 public constant PRECISION = 1e18;
    uint256 public constant BASIS_POINTS = 10000;

    // Mix enforcement (from BondValuationLibrary)
    uint256 public constant MIN_STABLE_BPS = 8000; // 80%
    uint256 public constant MAX_SEW_BPS = 2000; // 20%

    // Unbonding delays
    uint256 public constant RESOLVER_UNBOND_DELAY = 14 days;
    uint256 public constant SENIOR_UNBOND_DELAY = 21 days;

    // Coverage parameters
    uint256 public constant COVERAGE_MULTIPLIER = 3; // M = 3x
    uint256 public constant UTILIZATION_BPS = 5000; // U = 50%

    // Capacity limits (v3)
    uint256 public constant MAX_ESCROW_PER_L0_CASE = 2000e18; // $2,000 max escrow per L0 case (18 decimals)
    uint256 public constant CAPACITY_MULTIPLIER = 4; // Max escrow = 4× resolverBond

    // Haircut for SEW
    uint256 public constant SEW_HAIRCUT_BPS = 5000; // 50% haircut

    // Token decimals
    uint8 public constant STABLE_DECIMALS = 6; // USDC
    uint8 public constant SEW_DECIMALS = 18; // SEW

    // ============ State Variables ============

    IERC20 public stableToken; // USDC or other stablecoin
    IERC20 public sewToken; // Protocol token

    bool public paused;

    // Minimum stakes per tier
    mapping(uint8 => uint256) public minimumStakes; // tier => min effective bond USD (18 decimals)

    // Bond composition per resolver
    struct BondComposition {
        uint256 stableAmount; // Amount of stablecoin staked
        uint256 sewAmount; // Amount of SEW staked
        uint256 effectiveBondUSD; // Cached effective bond value (18 decimals)
        uint256 lastUpdated; // Last time bond was updated
    }
    mapping(address => BondComposition) public resolverBonds;

    // Stake status tracking
    mapping(address => StakeStatus) public stakeStatus;

    // Unbonding requests
    struct UnbondRequest {
        uint256 stableAmount;
        uint256 sewAmount;
        uint256 availableAt;
        bool exists;
    }
    mapping(address => UnbondRequest) public unbondRequests;

    // Coverage tracking (for seniors)
    mapping(address => uint256) public reservedCoverage; // Senior => total coverage reserved by juniors

    // Delegation tracking (junior => senior)
    struct DelegationRecord {
        address senior;
        uint256 coverageAmount; // Amount of coverage reserved from senior
        uint256 delegatedAt;
        bool active;
    }
    mapping(address => DelegationRecord) public delegations;

    // Reverse mapping (senior => list of juniors)
    mapping(address => address[]) public seniorDelegates;
    mapping(address => mapping(address => uint256)) public seniorDelegateIndex;

    // Tier tracking
    mapping(address => uint8) public resolverTier; // 0 = resolver, 1 = senior

    // Locked stake tracking (for active disputes)
    mapping(address => mapping(uint256 => mapping(address => uint256))) public lockedStakes; // escrowContract => workflowId => resolver => locked amount
    mapping(address => uint256) public totalLockedStake; // Total locked across all disputes

    // Slashing module reference (for freeze checks)
    address public slashingModule;

    // ============ Events ============

    event BondDeposited(
        address indexed resolver,
        uint256 stableAmount,
        uint256 sewAmount,
        uint256 effectiveBondUSD
    );
    event BondWithdrawn(address indexed resolver, uint256 stableAmount, uint256 sewAmount);
    event UnbondRequested(
        address indexed resolver,
        uint256 stableAmount,
        uint256 sewAmount,
        uint256 availableAt
    );
    event UnbondCancelled(address indexed resolver);
    event CoverageReserved(address indexed junior, address indexed senior, uint256 amount);
    event CoverageReleased(address indexed junior, address indexed senior, uint256 amount);
    event BondRevalued(address indexed resolver, uint256 oldBond, uint256 newBond);
    event TierUpdated(address indexed resolver, uint8 oldTier, uint8 newTier);
    event BondSlashed(
        address indexed resolver,
        uint256 stableSlashed,
        uint256 sewSlashed,
        uint256 totalSlashed
    );
    event CoverageSlashed(address indexed senior, uint256 amount, address indexed slashedFor);

    // ============ Initialization ============

    constructor(address initialOwner, address _stableToken, address _sewToken) {
        if (_stableToken == address(0)) revert ZeroAddress('stableToken');
        if (_sewToken == address(0)) revert ZeroAddress('sewToken');

        // OpenZeppelin best practice: Grant DEFAULT_ADMIN_ROLE to deployer
        // Deployment scripts will transfer this to TimelockController
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);

        stableToken = IERC20(_stableToken);
        sewToken = IERC20(_sewToken);

        paused = false;

        // Set default minimum stakes (v3 launch-safe defaults)
        // Resolver: min $250, suggested operating bond $500
        minimumStakes[0] = 250e18; // Resolver: 250 USD (min)
        // Senior: min $25,000, recommended $50,000-$100,000
        minimumStakes[1] = 25000e18; // Senior: 25,000 USD (min)
    }

    // ============ Core Staking Functions ============

    /**
     * @notice Stake (interface compatibility - defaults to stable only)
     * @param amount Amount to stake (assumed to be stable)
     */
    function stake(uint256 amount) external {
        stakeWithMix(amount, 0);
    }

    /**
     * @notice Request unstake (interface compatibility)
     * @param amount Amount to unstake (withdraws proportionally from stable/SEW)
     */
    function requestUnstake(uint256 amount) external {
        address resolver = _msgSender();
        BondComposition storage bond = resolverBonds[resolver];

        // Calculate proportional withdrawal
        uint256 totalBond = bond.stableAmount + bond.sewAmount;
        if (totalBond == 0) revert NoStake(resolver);

        uint256 stableAmount = (bond.stableAmount * amount) / totalBond;
        uint256 sewAmount = (bond.sewAmount * amount) / totalBond;

        requestUnstakeWithMix(stableAmount, sewAmount);
    }

    /**
     * @notice Deposit bond (stable + SEW mix)
     * @param stableAmount Amount of stablecoin to deposit
     * @param sewAmount Amount of SEW to deposit
     * @dev Enforces 80/20 mix rule with 50% SEW haircut
     */
    function stakeWithMix(uint256 stableAmount, uint256 sewAmount) public nonReentrant {
        if (paused) revert ContractPaused();
        if (stableAmount == 0 && sewAmount == 0) revert ZeroStakeAmount();

        address resolver = _msgSender();
        BondComposition storage bond = resolverBonds[resolver];

        // Calculate new total amounts
        uint256 newStableTotal = bond.stableAmount + stableAmount;
        uint256 newSewTotal = bond.sewAmount + sewAmount;

        // Check mix enforcement (80% stable, 20% SEW with 50% haircut)
        (bool valid, uint256 stablePct, uint256 sewPct) = BondValuationLibrary.checkBondMix(
            newStableTotal,
            newSewTotal,
            PRECISION, // SEW price = $1 (oracle-free, conservative)
            SEW_HAIRCUT_BPS,
            STABLE_DECIMALS,
            SEW_DECIMALS
        );
        if (!valid) revert InvalidBondMix(stablePct, sewPct);

        // Calculate effective bond value
        uint256 effectiveBond = BondValuationLibrary.calculateEffectiveBondUSD(
            newStableTotal,
            newSewTotal,
            PRECISION, // SEW price = $1
            SEW_HAIRCUT_BPS,
            STABLE_DECIMALS,
            SEW_DECIMALS
        );

        // Check minimum stake for tier
        uint8 tier = resolverTier[resolver];
        if (effectiveBond < minimumStakes[tier]) {
            revert BelowMinimumStake(resolver, effectiveBond, minimumStakes[tier], tier);
        }

        // Transfer tokens
        if (stableAmount > 0) {
            stableToken.safeTransferFrom(resolver, address(this), stableAmount);
        }
        if (sewAmount > 0) {
            sewToken.safeTransferFrom(resolver, address(this), sewAmount);
        }

        // Update bond
        bond.stableAmount = newStableTotal;
        bond.sewAmount = newSewTotal;
        bond.effectiveBondUSD = effectiveBond;
        bond.lastUpdated = block.timestamp;

        // Update status
        if (stakeStatus[resolver] == StakeStatus.UNSTAKING) {
            stakeStatus[resolver] = StakeStatus.ACTIVE;
            delete unbondRequests[resolver];
        } else if (stakeStatus[resolver] != StakeStatus.ACTIVE) {
            stakeStatus[resolver] = StakeStatus.ACTIVE;
        }

        emit StakeDeposited(resolver, stableAmount, effectiveBond);
        emit BondDeposited(resolver, stableAmount, sewAmount, effectiveBond);
    }

    /**
     * @notice Request unbonding (starts delay timer)
     * @param stableAmount Amount of stable to unbond
     * @param sewAmount Amount of SEW to unbond
     * @dev Cannot unbond if coverage is reserved or stake is locked
     */
    function requestUnstakeWithMix(uint256 stableAmount, uint256 sewAmount) public nonReentrant {
        if (paused) revert ContractPaused();
        if (stableAmount == 0 && sewAmount == 0) revert ZeroStakeAmount();

        address resolver = _msgSender();

        // CRITICAL: Check if resolver is frozen (recent slash)
        if (isResolverFrozen(resolver)) revert ResolverFrozen(resolver);

        BondComposition storage bond = resolverBonds[resolver];

        if (bond.stableAmount < stableAmount) revert InsufficientStableBalance(resolver, bond.stableAmount, stableAmount);
        if (bond.sewAmount < sewAmount) revert InsufficientSEWBalance(resolver, bond.sewAmount, sewAmount);
        if (stakeStatus[resolver] != StakeStatus.ACTIVE) revert NotActive(resolver, stakeStatus[resolver]);
        if (unbondRequests[resolver].exists) revert UnbondRequestPending(resolver);

        // Check if resolver has locked stakes
        if (totalLockedStake[resolver] > 0) revert StakeLockedInDisputes(resolver, totalLockedStake[resolver]);

        // Check if resolver is a senior with reserved coverage
        if (resolverTier[resolver] == 1) {
            if (reservedCoverage[resolver] > 0) revert CoverageAlreadyReserved(resolver, reservedCoverage[resolver]);
        }

        // Check if resolver is a junior with delegation
        if (delegations[resolver].active) {
            revert MustUndelegateFirst(resolver);
        }

        // Calculate remaining bond after unbond
        uint256 remainingStable = bond.stableAmount - stableAmount;
        uint256 remainingSew = bond.sewAmount - sewAmount;

        // If not withdrawing everything, check mix is still valid
        if (remainingStable > 0 || remainingSew > 0) {
            (bool valid, , ) = BondValuationLibrary.checkBondMix(
                remainingStable,
                remainingSew,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );
            if (!valid) revert RemainingBondInvalidMix(0, 0); // Mix validation failed

            // Check remaining bond meets minimum
            uint256 remainingBond = BondValuationLibrary.calculateEffectiveBondUSD(
                remainingStable,
                remainingSew,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );
            uint8 tierCheck = resolverTier[resolver];
            if (remainingBond < minimumStakes[tierCheck]) {
                revert BelowMinimumAfterUnbond(resolver, remainingBond, minimumStakes[tierCheck], tierCheck);
            }
        }

        // Calculate unbond delay based on tier
        uint8 tier = resolverTier[resolver];
        uint256 delay = (tier == 1) ? SENIOR_UNBOND_DELAY : RESOLVER_UNBOND_DELAY;
        uint256 availableAt = block.timestamp + delay;

        // Create unbond request
        unbondRequests[resolver] = UnbondRequest({
            stableAmount: stableAmount,
            sewAmount: sewAmount,
            availableAt: availableAt,
            exists: true
        });

        stakeStatus[resolver] = StakeStatus.UNSTAKING;

        emit UnstakeRequested(resolver, stableAmount + sewAmount, availableAt);
        emit UnbondRequested(resolver, stableAmount, sewAmount, availableAt);
    }

    /**
     * @notice Cancel unbonding request
     */
    function cancelUnstake() external nonReentrant {
        address resolver = _msgSender();
        if (!unbondRequests[resolver].exists) revert NoUnbondRequest(resolver);

        uint256 amount = unbondRequests[resolver].stableAmount + unbondRequests[resolver].sewAmount;

        delete unbondRequests[resolver];
        stakeStatus[resolver] = StakeStatus.ACTIVE;

        emit UnstakeCancelled(resolver, amount);
        emit UnbondCancelled(resolver);
    }

    /**
     * @notice Complete unbonding after delay
     */
    function completeUnstake() external nonReentrant {
        address resolver = _msgSender();
        UnbondRequest storage request = unbondRequests[resolver];

        if (!request.exists) revert NoUnbondRequest(resolver);
        if (block.timestamp < request.availableAt) {
            revert UnbondDelayNotPassed(resolver, request.availableAt, block.timestamp);
        }

        uint256 stableAmount = request.stableAmount;
        uint256 sewAmount = request.sewAmount;

        BondComposition storage bond = resolverBonds[resolver];

        // Update bond
        bond.stableAmount -= stableAmount;
        bond.sewAmount -= sewAmount;

        // Recalculate effective bond
        if (bond.stableAmount > 0 || bond.sewAmount > 0) {
            bond.effectiveBondUSD = BondValuationLibrary.calculateEffectiveBondUSD(
                bond.stableAmount,
                bond.sewAmount,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );
        } else {
            bond.effectiveBondUSD = 0;
            stakeStatus[resolver] = StakeStatus.ACTIVE; // Reset to active (no stake)
        }
        bond.lastUpdated = block.timestamp;

        // Transfer tokens
        if (stableAmount > 0) {
            stableToken.safeTransfer(resolver, stableAmount);
        }
        if (sewAmount > 0) {
            sewToken.safeTransfer(resolver, sewAmount);
        }

        // Clear unbond request
        delete unbondRequests[resolver];

        emit StakeWithdrawn(resolver, stableAmount + sewAmount, bond.effectiveBondUSD);
        emit BondWithdrawn(resolver, stableAmount, sewAmount);
    }

    /**
     * @notice Emergency withdraw (admin only, for contract migration)
     * @param to Address to send tokens to
     */
    function emergencyWithdraw(address to) external onlyRole(ROLE_TIMELOCK) {
        address resolver = _msgSender();
        BondComposition storage bond = resolverBonds[resolver];

        uint256 stableAmount = bond.stableAmount;
        uint256 sewAmount = bond.sewAmount;
        uint256 totalAmount = stableAmount + sewAmount;

        if (totalAmount == 0) revert NoStake(resolver);

        // Clear bond
        bond.stableAmount = 0;
        bond.sewAmount = 0;
        bond.effectiveBondUSD = 0;
        bond.lastUpdated = block.timestamp;

        // Transfer tokens
        if (stableAmount > 0) {
            stableToken.safeTransfer(to, stableAmount);
        }
        if (sewAmount > 0) {
            sewToken.safeTransfer(to, sewAmount);
        }

        emit EmergencyWithdrawal(resolver, totalAmount, to);
    }

    // ============ Delegation Functions (Coverage) ============

    /**
     * @notice Junior delegates to senior for coverage (M=3, U=0.5)
     * @param senior Senior resolver to delegate to
     * @dev Junior needs coverage = juniorBond × M
     *      Senior provides coverage = seniorBond × U
     */
    function delegateStake(
        address senior,
        uint256 /* amount - unused, calculated automatically */
    ) external nonReentrant {
        if (paused) revert ContractPaused();

        address junior = _msgSender();
        if (junior == senior) revert CannotDelegateToSelf(junior);
        if (resolverTier[junior] != 0) revert OnlyResolversCanDelegate(junior, resolverTier[junior]);
        if (resolverTier[senior] != 1) revert MustDelegateToSenior(senior, resolverTier[senior]);
        if (delegations[junior].active) revert AlreadyDelegated(junior);
        if (stakeStatus[junior] != StakeStatus.ACTIVE) revert JuniorNotActive(junior, stakeStatus[junior]);
        if (stakeStatus[senior] != StakeStatus.ACTIVE) revert SeniorNotActive(senior, stakeStatus[senior]);

        // Calculate required coverage for junior
        BondComposition storage juniorBond = resolverBonds[junior];
        uint256 requiredCoverage = juniorBond.effectiveBondUSD * COVERAGE_MULTIPLIER;

        // Check senior has available coverage
        BondComposition storage seniorBond = resolverBonds[senior];
        uint256 seniorMaxCoverage = BondValuationLibrary.calculateMaxCoverage(
            seniorBond.effectiveBondUSD,
            UTILIZATION_BPS
        );
        uint256 seniorAvailableCoverage = seniorMaxCoverage - reservedCoverage[senior];

        if (seniorAvailableCoverage < requiredCoverage) {
            revert InsufficientSeniorCoverage(senior, seniorAvailableCoverage, requiredCoverage);
        }

        // Reserve coverage
        reservedCoverage[senior] += requiredCoverage;

        // Record delegation
        delegations[junior] = DelegationRecord({
            senior: senior,
            coverageAmount: requiredCoverage,
            delegatedAt: block.timestamp,
            active: true
        });

        // Add to senior's delegate list
        seniorDelegateIndex[senior][junior] = seniorDelegates[senior].length;
        seniorDelegates[senior].push(junior);

        emit StakeDelegated(junior, senior, requiredCoverage);
        emit CoverageReserved(junior, senior, requiredCoverage);
    }

    /**
     * @notice Junior undelegates from senior
     */
    function undelegateStake(address senior, uint256 /* amount - unused */) external nonReentrant {
        address junior = _msgSender();
        DelegationRecord storage delegation = delegations[junior];

        if (!delegation.active) revert NotDelegated(junior);
        if (delegation.senior != senior) revert WrongSenior(junior, delegation.senior, senior);

        // Check junior has no locked stakes
        if (totalLockedStake[junior] > 0) revert StakeLockedInDisputes(junior, totalLockedStake[junior]);

        uint256 coverageAmount = delegation.coverageAmount;

        // Release coverage
        reservedCoverage[senior] -= coverageAmount;

        // Remove from senior's delegate list
        uint256 index = seniorDelegateIndex[senior][junior];
        uint256 lastIndex = seniorDelegates[senior].length - 1;

        if (index != lastIndex) {
            address lastDelegate = seniorDelegates[senior][lastIndex];
            seniorDelegates[senior][index] = lastDelegate;
            seniorDelegateIndex[senior][lastDelegate] = index;
        }

        seniorDelegates[senior].pop();
        delete seniorDelegateIndex[senior][junior];

        // Clear delegation
        delete delegations[junior];

        emit StakeUndelegated(junior, senior, coverageAmount);
        emit CoverageReleased(junior, senior, coverageAmount);
    }

    // ============ Lifecycle Hooks (Called by Resolution Module) ============

    /**
     * @notice Lock stake when resolver is assigned to dispute
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param resolver Resolver address
     * @param stakeRequired Amount of stake required for this dispute (if 0, uses tier minimum)
     */
    function onResolverAssigned(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        uint256 stakeRequired
    ) external onlyRole(ROLE_RESOLUTION_MODULE) {
        // Lock minimum stake for tier if not specified
        uint256 lockAmount = stakeRequired;
        if (lockAmount == 0) {
            uint8 tier = resolverTier[resolver];
            lockAmount = minimumStakes[tier];
        }

        // Check resolver has sufficient available stake
        BondComposition storage bond = resolverBonds[resolver];
        uint256 availableStake = bond.effectiveBondUSD - totalLockedStake[resolver];
        if (availableStake < lockAmount) revert InsufficientAvailableStake(resolver, availableStake, lockAmount);

        // Lock stake
        lockedStakes[escrowContract][workflowId][resolver] = lockAmount;
        totalLockedStake[resolver] += lockAmount;

        emit StakeLocked(resolver, lockAmount, workflowId, 'Assignment');
    }

    /**
     * @notice Unlock stake when resolution is finalized
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param resolver Resolver address
     */
    function onResolutionFinalized(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        bool outcome
    ) external onlyRole(ROLE_RESOLUTION_MODULE) {
        outcome;
        uint256 lockedAmount = lockedStakes[escrowContract][workflowId][resolver];

        if (lockedAmount > 0) {
            // Unlock stake
            totalLockedStake[resolver] -= lockedAmount;
            delete lockedStakes[escrowContract][workflowId][resolver];

            emit StakeUnlocked(resolver, lockedAmount, workflowId);
        }
    }

    /**
     * @notice Unlock stake when dispute is escalated
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param resolver Prior round resolver
     */
    function onDisputeEscalated(
        uint256 workflowId,
        address escrowContract,
        address resolver
    ) external onlyRole(ROLE_RESOLUTION_MODULE) {
        uint256 lockedAmount = lockedStakes[escrowContract][workflowId][resolver];

        if (lockedAmount > 0) {
            // Unlock stake from prior resolver
            totalLockedStake[resolver] -= lockedAmount;
            delete lockedStakes[escrowContract][workflowId][resolver];

            emit StakeUnlocked(resolver, lockedAmount, workflowId);
        }
    }

    /**
     * @notice Lock stake for specific duration (manual lock)
     */
    function lockStake(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        uint256 amount,
        uint256 duration
    ) external onlyRole(ROLE_RESOLUTION_MODULE) {
        duration;
        BondComposition storage bond = resolverBonds[resolver];
        uint256 availableStake = bond.effectiveBondUSD - totalLockedStake[resolver];
        if (availableStake < amount) revert InsufficientAvailableStake(resolver, availableStake, amount);

        lockedStakes[escrowContract][workflowId][resolver] = amount;
        totalLockedStake[resolver] += amount;

        emit StakeLocked(resolver, amount, workflowId, 'Manual lock');
    }

    /**
     * @notice Unlock stake (manual unlock)
     */
    function unlockStake(
        uint256 workflowId,
        address escrowContract,
        address resolver
    ) external onlyRole(ROLE_RESOLUTION_MODULE) {
        uint256 lockedAmount = lockedStakes[escrowContract][workflowId][resolver];

        if (lockedAmount > 0) {
            totalLockedStake[resolver] -= lockedAmount;
            delete lockedStakes[escrowContract][workflowId][resolver];

            emit StakeUnlocked(resolver, lockedAmount, workflowId);
        }
    }

    // ============ Query Functions ============

    /**
     * @notice Get stake info for resolver
     */
    function getStakeInfo(address resolver) external view returns (StakeInfo memory info) {
        BondComposition storage bond = resolverBonds[resolver];
        DelegationRecord storage delegation = delegations[resolver];

        uint256 availableStake = bond.effectiveBondUSD > totalLockedStake[resolver]
            ? bond.effectiveBondUSD - totalLockedStake[resolver]
            : 0;

        info = StakeInfo({
            totalStake: bond.effectiveBondUSD,
            availableStake: availableStake,
            lockedStake: totalLockedStake[resolver],
            delegatedFrom: delegation.active ? delegation.coverageAmount : 0,
            delegatedTo: reservedCoverage[resolver],
            slashedAmount: 0, // Not implemented yet
            unstakeRequestedAt: unbondRequests[resolver].exists
                ? unbondRequests[resolver].availableAt
                : 0,
            unstakeAmount: unbondRequests[resolver].exists
                ? unbondRequests[resolver].stableAmount + unbondRequests[resolver].sewAmount
                : 0,
            status: stakeStatus[resolver]
        });
    }

    /**
     * @notice Check if resolver has sufficient stake
     */
    function isStakeSufficient(
        address resolver,
        uint256 required
    ) external view returns (bool sufficient) {
        BondComposition storage bond = resolverBonds[resolver];
        uint256 availableStake = bond.effectiveBondUSD > totalLockedStake[resolver]
            ? bond.effectiveBondUSD - totalLockedStake[resolver]
            : 0;

        sufficient = availableStake >= required;
    }

    /**
     * @notice Get available stake (not locked)
     */
    function getAvailableStake(address resolver) external view returns (uint256 available) {
        BondComposition storage bond = resolverBonds[resolver];
        available = bond.effectiveBondUSD > totalLockedStake[resolver]
            ? bond.effectiveBondUSD - totalLockedStake[resolver]
            : 0;
    }

    /**
     * @notice Get total effective stake (including delegation coverage)
     */
    function getEffectiveStake(address resolver) external view returns (uint256 effective) {
        BondComposition storage bond = resolverBonds[resolver];
        DelegationRecord storage delegation = delegations[resolver];

        effective = bond.effectiveBondUSD;

        // Add coverage from senior if delegated
        if (delegation.active) {
            effective += delegation.coverageAmount;
        }
    }

    /**
     * @notice Get delegation info
     */
    function getDelegationInfo(
        address delegator,
        address delegatee
    ) external view returns (DelegationInfo memory info) {
        DelegationRecord storage delegation = delegations[delegator];

        if (delegation.active && delegation.senior == delegatee) {
            info = DelegationInfo({
                delegator: delegator,
                delegatee: delegatee,
                amount: delegation.coverageAmount,
                delegatedAt: delegation.delegatedAt,
                active: true
            });
        } else {
            info = DelegationInfo({
                delegator: delegator,
                delegatee: delegatee,
                amount: 0,
                delegatedAt: 0,
                active: false
            });
        }
    }

    /**
     * @notice Get minimum stake for tier
     */
    function getMinimumStake(uint8 tier) external view returns (uint256 minimum) {
        return minimumStakes[tier];
    }

    /**
     * @notice Get max escrow per L0 case for a resolver (v3 capacity limit)
     * @param resolver Resolver address
     * @return maxEscrow Max escrow value (18 decimals) = min($2,000, 4× resolverBond)
     * @dev v3: Capacity gating forces high-value cases to flow only to resolvers with higher bond
     */
    function getMaxEscrowPerCase(address resolver) external view returns (uint256 maxEscrow) {
        BondComposition storage bond = resolverBonds[resolver];
        uint256 bondBasedLimit = bond.effectiveBondUSD * CAPACITY_MULTIPLIER;
        maxEscrow = bondBasedLimit < MAX_ESCROW_PER_L0_CASE ? bondBasedLimit : MAX_ESCROW_PER_L0_CASE;
        return maxEscrow;
    }

    /**
     * @notice Get stake token (returns stable token)
     */
    function getStakeToken() external view returns (address token) {
        return address(stableToken);
    }

    /**
     * @notice Check if paused
     */
    function isPaused() external view returns (bool) {
        return paused;
    }

    /**
     * @notice Get bond composition
     */
    function getBondComposition(
        address resolver
    )
        external
        view
        returns (
            uint256 stableAmount,
            uint256 sewAmount,
            uint256 effectiveBondUSD,
            uint256 stablePct,
            uint256 sewPct
        )
    {
        BondComposition storage bond = resolverBonds[resolver];
        stableAmount = bond.stableAmount;
        sewAmount = bond.sewAmount;
        effectiveBondUSD = bond.effectiveBondUSD;

        if (effectiveBondUSD > 0) {
            (, stablePct, sewPct) = BondValuationLibrary.checkBondMix(
                stableAmount,
                sewAmount,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );
        }
    }

    /**
     * @notice Get senior's coverage stats
     */
    function getSeniorCoverageStats(
        address senior
    )
        external
        view
        returns (
            uint256 maxCoverage,
            uint256 reservedCoverageAmount,
            uint256 availableCoverage,
            uint256 numDelegates
        )
    {
        BondComposition storage bond = resolverBonds[senior];
        maxCoverage = BondValuationLibrary.calculateMaxCoverage(
            bond.effectiveBondUSD,
            UTILIZATION_BPS
        );
        reservedCoverageAmount = reservedCoverage[senior];
        availableCoverage = maxCoverage > reservedCoverageAmount
            ? maxCoverage - reservedCoverageAmount
            : 0;
        numDelegates = seniorDelegates[senior].length;
    }

    // ============ Slashing Functions ============

    /**
     * @notice Slash resolver's bond (called by slashing module)
     * @param resolver Address of resolver to slash
     * @param amount Amount to slash (in USD, 18 decimals)
     * @return stableSlashed Amount of stable slashed
     * @return sewSlashed Amount of SEW slashed
     */
    function slash(
        address resolver,
        uint256 amount
    ) external onlyRole(ROLE_SLASHING_MODULE) returns (uint256 stableSlashed, uint256 sewSlashed) {
        BondComposition storage bond = resolverBonds[resolver];

        // Clamp amount to available bond (prevents underflow after multiple slashes)
        if (amount > bond.effectiveBondUSD) {
            amount = bond.effectiveBondUSD;
        }
        if (bond.effectiveBondUSD == 0 || amount == 0) {
            revert InsufficientBond(resolver, bond.effectiveBondUSD, amount);
        }

        // Calculate proportional slash from stable and SEW
        uint256 totalBond = bond.effectiveBondUSD;

        // Calculate proportional slash from stable and SEW
        // Slash proportionally based on effective bond value
        if (totalBond > 0) {
            // Calculate stable slash (in stable's native units, then convert)
            uint256 stableValueUSD = BondValuationLibrary.calculateEffectiveBondUSD(
                bond.stableAmount,
                0,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );

            if (stableValueUSD > 0 && bond.stableAmount > 0) {
                // Proportional: stableSlashed = (stableValueUSD / totalBond) * amount
                // Convert back to stable units
                stableSlashed = (bond.stableAmount * amount) / totalBond;
                if (stableSlashed > bond.stableAmount) stableSlashed = bond.stableAmount;
            }

            if (bond.sewAmount > 0) {
                // SEW value = totalBond - stableValueUSD
                uint256 sewValueUSD = totalBond - stableValueUSD;
                if (sewValueUSD > 0) {
                    sewSlashed = (bond.sewAmount * amount) / totalBond;
                    if (sewSlashed > bond.sewAmount) sewSlashed = bond.sewAmount;
                }
            }
        }

        // Update bond
        bond.stableAmount -= stableSlashed;
        bond.sewAmount -= sewSlashed;

        // Recalculate effectiveBondUSD from remaining amounts (ensures consistency)
        if (bond.stableAmount > 0 || bond.sewAmount > 0) {
            bond.effectiveBondUSD = BondValuationLibrary.calculateEffectiveBondUSD(
                bond.stableAmount,
                bond.sewAmount,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );
        } else {
            bond.effectiveBondUSD = 0;
        }

        bond.lastUpdated = block.timestamp;

        // Transfer slashed stable to slashing module
        if (stableSlashed > 0) {
            if (slashingModule == address(0)) revert ZeroAddress('slashingModule');
            stableToken.safeTransfer(slashingModule, stableSlashed);
        }
        // Burn slashed SEW tokens (deflationary)
        // Transfer to slashing module first, then it burns
        if (sewSlashed > 0) {
            if (slashingModule == address(0)) revert ZeroAddress('slashingModule');
            sewToken.safeTransfer(slashingModule, sewSlashed);
        }

        emit BondSlashed(resolver, stableSlashed, sewSlashed, amount);
    }

    /**
     * @notice Slash senior's coverage (called by slashing module)
     * @param senior Address of senior to slash
     * @param amount Amount to slash (in USD, 18 decimals)
     * @param slashedFor Address of junior this slash is for
     * @return stableSlashed Amount of stable slashed
     * @return sewSlashed Amount of SEW slashed
     */
    function slashCoverage(
        address senior,
        uint256 amount,
        address slashedFor
    ) external onlyRole(ROLE_SLASHING_MODULE) returns (uint256 stableSlashed, uint256 sewSlashed) {
        BondComposition storage bond = resolverBonds[senior];

        // Clamp amount to available bond (prevents underflow after multiple slashes)
        if (amount > bond.effectiveBondUSD) {
            amount = bond.effectiveBondUSD;
        }
        if (bond.effectiveBondUSD == 0 || amount == 0) {
            revert InsufficientBond(senior, bond.effectiveBondUSD, amount);
        }

        // Calculate proportional slash (same as slash())
        uint256 totalBond = bond.effectiveBondUSD;

        if (totalBond > 0) {
            uint256 stableValueUSD = BondValuationLibrary.calculateEffectiveBondUSD(
                bond.stableAmount,
                0,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );

            if (stableValueUSD > 0 && bond.stableAmount > 0) {
                stableSlashed = (bond.stableAmount * amount) / totalBond;
                if (stableSlashed > bond.stableAmount) stableSlashed = bond.stableAmount;
            }

            if (bond.sewAmount > 0) {
                uint256 sewValueUSD = totalBond - stableValueUSD;
                if (sewValueUSD > 0) {
                    sewSlashed = (bond.sewAmount * amount) / totalBond;
                    if (sewSlashed > bond.sewAmount) sewSlashed = bond.sewAmount;
                }
            }
        }

        // Update bond
        bond.stableAmount -= stableSlashed;
        bond.sewAmount -= sewSlashed;

        // Recalculate effectiveBondUSD from remaining amounts (ensures consistency)
        if (bond.stableAmount > 0 || bond.sewAmount > 0) {
            bond.effectiveBondUSD = BondValuationLibrary.calculateEffectiveBondUSD(
                bond.stableAmount,
                bond.sewAmount,
                PRECISION,
                SEW_HAIRCUT_BPS,
                STABLE_DECIMALS,
                SEW_DECIMALS
            );
        } else {
            bond.effectiveBondUSD = 0;
        }

        bond.lastUpdated = block.timestamp;

        // Also reduce reserved coverage if this senior was providing coverage
        if (reservedCoverage[senior] > 0) {
            uint256 coverageReduction = amount;
            if (coverageReduction > reservedCoverage[senior]) {
                coverageReduction = reservedCoverage[senior];
            }
            reservedCoverage[senior] -= coverageReduction;
        }

        // Transfer slashed stable to slashing module
        if (stableSlashed > 0) {
            if (slashingModule == address(0)) revert ZeroAddress('slashingModule');
            stableToken.safeTransfer(slashingModule, stableSlashed);
        }
        // Transfer slashed SEW tokens to slashing module (for burning)
        if (sewSlashed > 0) {
            if (slashingModule == address(0)) revert ZeroAddress('slashingModule');
            sewToken.safeTransfer(slashingModule, sewSlashed);
        }

        emit CoverageSlashed(senior, amount, slashedFor);
        emit BondSlashed(senior, stableSlashed, sewSlashed, amount);
    }

    /**
     * @notice Check if resolver is frozen (by slashing module)
     * @param resolver Address to check
     * @return frozen True if frozen
     */
    function isResolverFrozen(address resolver) public view returns (bool frozen) {
        if (slashingModule == address(0)) return false;

        // Call slashing module to check freeze status
        (bool success, bytes memory data) = slashingModule.staticcall(
            abi.encodeWithSignature('isResolverFrozen(address)', resolver)
        );

        if (success && data.length >= 32) {
            frozen = abi.decode(data, (bool));
        }
    }

    // ============ Admin Functions ============

    /**
     * @notice Set minimum stake for tier
     */
    function setMinimumStake(uint8 tier, uint256 minimum) external onlyRole(ROLE_TIMELOCK) {
        uint256 oldMinimum = minimumStakes[tier];
        minimumStakes[tier] = minimum;
        emit MinimumStakeUpdated(tier, oldMinimum, minimum);
    }

    /**
     * @notice Set unstake period (not used in this version, delays are constants)
     */
    function setUnstakePeriod(uint256 period) external onlyRole(ROLE_TIMELOCK) {
        // No-op: Delays are constants in this version
        emit UnstakePeriodUpdated(0, period);
    }

    /**
     * @notice Pause staking
     */
    function pause(string memory reason) external onlyRole(ROLE_TIMELOCK) {
        paused = true;
        emit EmergencyPaused(_msgSender(), reason);
    }

    /**
     * @notice Unpause staking
     */
    function unpause() external onlyRole(ROLE_TIMELOCK) {
        paused = false;
        emit EmergencyUnpaused(_msgSender());
    }

    /**
     * @notice Set resolver tier (0 = resolver, 1 = senior)
     */
    function setResolverTier(address resolver, uint8 tier) external onlyRole(ROLE_TIMELOCK) {
        if (tier > 1) revert InvalidTier(tier, 1);
        uint8 oldTier = resolverTier[resolver];
        resolverTier[resolver] = tier;
        emit TierUpdated(resolver, oldTier, tier);
    }

    /**
     * @notice Set resolution module address
     */
    function setResolutionModule(address module) external onlyRole(ROLE_TIMELOCK) {
        _grantRole(ROLE_RESOLUTION_MODULE, module);
    }

    /**
     * @notice Set slashing module address
     */
    function setSlashingModule(address module) external onlyRole(ROLE_TIMELOCK) {
        slashingModule = module;
        _grantRole(ROLE_SLASHING_MODULE, module);
    }
}

