// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import '../shared/interfaces/IResolutionModule.sol';
import '../types/EscrowTypes.sol';

/**
 * @title SettlementOps
 * @notice External contract for settlement execution operations
 * @dev Extracted from BaseEscrow to reduce contract size
 *
 *      Key design principles:
 *      - Compute → Apply: Returns settlement result, BaseEscrow applies to state
 *      - No callbacks: Does not write to BaseEscrow state
 *      - View-ish: Could be view functions but may query modules
 *
 *      Pattern:
 *      BaseEscrow calls: executeResolution(...) or executePendingSettlement(...)
 *      SettlementOps returns: (shouldExecute, isRelease, appealDeadline, isFinalRound)
 *      BaseEscrow applies: Updates state and executes transfer
 */
contract SettlementOps is AccessControl {
    // ============ Role Constants ============
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // ============ Custom Errors ============
    error ZeroOwner();
    // PendingSettlement struct (matches BaseEscrow.PendingSettlement)
    // Note: This must match BaseEscrow.PendingSettlement exactly
    struct SettlementPendingSettlement {
        bool exists;
        bool isRelease;
        uint256 appealDeadline;
        bytes32 resolutionHash;
    }
    /**
     * @dev Result of resolution execution computation
     */
    struct ResolutionResult {
        bool shouldExecute; // Whether resolution should execute immediately
        bool isRelease; // True to release, false to cancel
        uint256 appealDeadline; // Appeal deadline timestamp (0 if immediate)
        bool isFinalRound; // Whether this is the final round (no appeal window)
    }

    /**
     * @notice Constructor for SettlementOps
     * @param initialOwner Address that will receive DEFAULT_ADMIN_ROLE (for initial setup only)
     */
    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        // ROLE_TIMELOCK gates registerEscrowContract(), so initialOwner must have it for initial setup.
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    /**
     * @notice Register an escrow contract (grants it ROLE_ESCROW_CONTRACT)
     * @param escrowContract Address of the escrow contract
     * @dev Only ROLE_TIMELOCK can register escrow contracts (governance-controlled)
     */
    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidAddress(ADDR_ESCROW_CONTRACT, escrowContract);
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    /**
     * @notice Action plan for settlement automation
     * @dev Returned by computeNextAction() to guide BaseEscrow._applyActionPlan()
     */
    struct ActionPlan {
        uint8 action; // 0 = none, 1 = release, 2 = cancel, 3 = set pending
        bool isRelease; // If action == 3 (set pending)
        uint256 appealDeadline; // If action == 3
        bytes32 resolutionHash; // If action == 3
        bool needsFinalization; // Whether to call finalizeDispute on resolution module
    }

    /**
     * @notice Compute resolution execution parameters
     * @param resolutionModule Address of the resolution module
     * @param workflowId Escrow workflow ID
     * @param isRelease True to release to recipient, false to cancel/refund to sender
     * @param timeoutConfig Global timeout configuration
     * @return result Resolution execution result
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      BaseEscrow will apply the result after receiving it.
     *      Only authorized escrow contracts can call this function
     */
    function computeResolutionExecution(
        address resolutionModule,
        uint256 workflowId,
        bool isRelease,
        TimeoutConfig memory timeoutConfig
    ) external view onlyRole(ROLE_ESCROW_CONTRACT) returns (ResolutionResult memory result) {
        result.isRelease = isRelease;
        result.shouldExecute = false;
        result.appealDeadline = 0;
        result.isFinalRound = false;

        // Query appeal deadline from resolution module
        // For DecentralizedResolutionModule, this is stored in DisputeMetadata.appealDeadline[currentRound]
        // For other modules, fall back to timeoutConfig.appealWindowDuration
        if (resolutionModule == address(0)) {
            // No resolution module - use global appeal window duration
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
            return result;
        }

        // Validate module is still a valid contract before calling
        if (resolutionModule.code.length == 0) {
            // Module no longer exists - fallback to global appeal window duration
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
            return result;
        }

        // Try to get appeal deadline and current round from module
        // Use staticcall to query view function
        (bool success, bytes memory data) = resolutionModule.staticcall(
            abi.encodeWithSignature('getAppealDeadlineAndRound(uint256,address)', workflowId, _msgSender())
        );

        if (success && data.length > 0) {
            // Decode return values: (uint256 appealDeadline, uint8 currentRound, bool isFinalRound)
            (result.appealDeadline, , result.isFinalRound) = abi.decode(data, (uint256, uint8, bool));
        } else {
            // Module doesn't support getAppealDeadlineAndRound - fallback to global config
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
        }

        // If final round (MAX_ROUND), execute immediately (no appeal window)
        if (result.isFinalRound) {
            result.shouldExecute = true;
        } else if (result.appealDeadline == 0) {
            // If not final and no deadline provided, use global config
            result.appealDeadline = block.timestamp + timeoutConfig.appealWindowDuration;
            if (result.appealDeadline == 0) {
                result.shouldExecute = true;
            }
        }

        return result;
    }

    /**
     * @notice Compute pending settlement execution check
     * @param workflowId Escrow workflow ID
     * @param pending Pending settlement data
     * @param escrowState Current escrow state
     * @return canExecute Whether settlement can be executed
     * @return isRelease True if pending release, false if pending cancel
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      Only authorized escrow contracts can call this function
     */
    function computePendingSettlementExecution(
        uint256 workflowId,
        SettlementPendingSettlement memory pending,
        EscrowState escrowState
    ) external view onlyRole(ROLE_ESCROW_CONTRACT) returns (bool canExecute, bool isRelease) {
        // Intentionally unused (kept for interface/telemetry parity with other ops functions)
        workflowId;

        // Verify pending settlement exists
        if (!pending.exists) {
            return (false, false);
        }

        // Verify appeal window has expired
        if (block.timestamp < pending.appealDeadline) {
            return (false, false);
        }

        // Verify state is still DISPUTED (not already executed or escalated)
        if (escrowState != EscrowState.DISPUTED) {
            return (false, false);
        }

        return (true, pending.isRelease);
    }

    /**
     * @notice Compute timed actions (auto-release or auto-cancel)
     * @param et Escrow transfer data
     * @param pending Pending settlement data
     * @return actionType 0 = none, 1 = auto-release, 2 = auto-cancel, 3 = pending settlement
     * @return isRelease True if release action, false if cancel
     * @dev This function is "compute-only" - it does NOT modify BaseEscrow state.
     *      Only authorized escrow contracts can call this function
     */
    function computeTimedActions(
        uint256 /* workflowId */,
        EscrowTransfer memory et,
        SettlementPendingSettlement memory pending,
        TimeoutConfig memory /* timeoutConfig */
    ) external view returns (uint8 actionType, bool isRelease) {
        // Check for pending settlement execution (appeal window enforcement)
        if (
            pending.exists &&
            block.timestamp >= pending.appealDeadline &&
            et.escrowState == EscrowState.DISPUTED
        ) {
            return (3, pending.isRelease);
        }

        // Check for auto-release/auto-cancel (only for PENDING state)
        if (et.escrowState != EscrowState.PENDING) {
            return (0, false);
        }

        if (et.autoReleaseTime > 0 && block.timestamp >= et.autoReleaseTime) {
            return (1, true);
        } else if (et.autoCancelTime > 0 && block.timestamp >= et.autoCancelTime) {
            return (2, false);
        }

        return (0, false);
    }
}

contracts/ops/YieldOps.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts/access/AccessControl.sol';
import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import '../libraries/ResolverLogicLibrary.sol';

/**
 * @title YieldOps
 * @notice External contract for yield withdrawal and distribution operations
 */
contract YieldOps is AccessControl {
    using SafeERC20 for IERC20;

    // ============ Custom Errors ============
    error ZeroOwner();
    error FeeRecipientCannotBeZero();
    error ProtocolFeeExceedsMaximum(uint256 feeBps, uint256 maxFeeBps);
    error InternalOnly(address caller);
    error DistributionFailed(uint256 workflowId, address token, uint256 amount);
    error InvalidRecipient(address recipient);
    error TransferFailed(address recipient, uint256 amount);

    // ============ Role Constants ============
    bytes32 public constant ROLE_GUARDIAN = keccak256('ROLE_GUARDIAN');
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');
    bytes32 public constant ROLE_ESCROW_CONTRACT = keccak256('ROLE_ESCROW_CONTRACT');

    // ============ Constants ============
    uint256 public constant MAX_PROTOCOL_FEE_BPS = 3000;

    // Events
    event YieldWithdrawn(uint256 indexed workflowId, address indexed token, uint256 yieldAmount);
    event YieldDistributed(uint256 indexed workflowId, address indexed token, uint256 yieldAmount);
    event YieldDistributionFailed(uint256 indexed workflowId, address indexed token, uint256 yieldAmount, string reason);
    event YieldProtocolFeeCollected(uint256 indexed workflowId, address indexed token, uint256 yieldAmount, uint256 protocolFeeAmount);
    event YieldRecoveredToFeeAddress(uint256 indexed workflowId, address indexed token, uint256 yieldAmount, address indexed feeRecipient);
    event TokensRecovered(address indexed token, address indexed to, uint256 amount);

    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert ZeroOwner();
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(ROLE_TIMELOCK, initialOwner);
    }

    function registerEscrowContract(address escrowContract) external onlyRole(ROLE_TIMELOCK) {
        if (escrowContract == address(0)) revert InvalidRecipient(address(0));
        _grantRole(ROLE_ESCROW_CONTRACT, escrowContract);
    }

    struct YieldResult {
        uint256 actualAmount;
        uint256 yield;
        uint256 yieldDistributed;
        bool success;
        string failureReason;
    }

    struct DistributionResult {
        bool success;
        uint256 distributedAmount;
        string failureReason;
    }

    /**
     * @notice Distribute yield that has already been withdrawn.
     */
    function distributeWithdrawnYield(
        IYieldDistributionModule distModule,
        uint256 workflowId,
        address token,
        uint256 yieldAmount,
        uint256 protocolFeeBps,
        address feeRecipient,
        bytes memory distributionData
    ) external onlyRole(ROLE_ESCROW_CONTRACT) returns (DistributionResult memory result) {
        address escrowContract = _msgSender();
        result.success = true;
        result.distributedAmount = 0;
        result.failureReason = '';

        if (yieldAmount == 0) return result;

        uint256 protocolFeeAmount = 0;
        uint256 yieldToDistribute = yieldAmount;

        if (protocolFeeBps > 0) {
            if (feeRecipient == address(0)) revert FeeRecipientCannotBeZero();
            if (protocolFeeBps > MAX_PROTOCOL_FEE_BPS) revert ProtocolFeeExceedsMaximum(protocolFeeBps, MAX_PROTOCOL_FEE_BPS);
            protocolFeeAmount = (yieldAmount * protocolFeeBps) / 10000;
            if (protocolFeeAmount > 0) {
                yieldToDistribute = yieldAmount - protocolFeeAmount;
                IERC20(token).safeTransfer(feeRecipient, protocolFeeAmount);
                emit YieldProtocolFeeCollected(workflowId, token, yieldAmount, protocolFeeAmount);
            }
        }

        if (yieldToDistribute > 0 && address(distModule) != address(0)) {
            try this._distributeYieldInternal(distModule, workflowId, escrowContract, token, yieldToDistribute, distributionData) {
                emit YieldDistributed(workflowId, token, yieldToDistribute);
                result.distributedAmount = yieldToDistribute;
                return result;
            } catch Error(string memory reason) {
                result.failureReason = reason;
                emit YieldDistributionFailed(workflowId, token, yieldToDistribute, reason);
            } catch {
                result.failureReason = 'Unknown error';
                emit YieldDistributionFailed(workflowId, token, yieldToDistribute, 'Unknown error');
            }

            if (feeRecipient != address(0)) {
                IERC20(token).safeTransfer(feeRecipient, yieldToDistribute);
                emit YieldRecoveredToFeeAddress(workflowId, token, yieldToDistribute, feeRecipient);
                result.success = false;
                result.distributedAmount = yieldToDistribute;
                return result;
            }
            result.success = false;
            return result;
        }

        if (yieldToDistribute > 0 && feeRecipient != address(0)) {
            IERC20(token).safeTransfer(feeRecipient, yieldToDistribute);
            emit YieldRecoveredToFeeAddress(workflowId, token, yieldToDistribute, feeRecipient);
            result.distributedAmount = yieldToDistribute;
            return result;
        }

        if (yieldToDistribute > 0) {
            result.success = true;
            result.failureReason = 'No distribution module and no fee recipient';
        }

        return result;
    }

    /**
     * @notice Handle yield withdrawal
     */
    function handleYield(
        IYieldGenerationModule genModule,
        IYieldDistributionModule /* distModule */,
        uint256 workflowId,
        address token,
        uint256 amount,
        uint256 /* protocolFeeBps */,
        address /* feeRecipient */,
        bytes memory /* distributionData */
    ) external onlyRole(ROLE_ESCROW_CONTRACT) returns (YieldResult memory result) {
        address escrowContract = _msgSender();
        result.actualAmount = amount;
        result.yield = 0;
        result.yieldDistributed = 0;
        result.success = true;
        result.failureReason = '';

        if (address(genModule) == address(0)) return result;

        uint256 balBefore = IERC20(token).balanceOf(address(this));

        try genModule.withdrawWithYield(workflowId, token, amount, escrowContract) returns (
            bool withdrawSuccess,
            uint256 actualAmountWithdrawn,
            uint256 /* yieldGenerated */
        ) {
            uint256 balAfter = IERC20(token).balanceOf(address(this));
            uint256 received = balAfter > balBefore ? balAfter - balBefore : 0;

            if (withdrawSuccess) {
                result.actualAmount = actualAmountWithdrawn;
                if (actualAmountWithdrawn > amount) {
                    result.yield = actualAmountWithdrawn - amount;
                    emit YieldWithdrawn(workflowId, token, result.yield);
                }

                // CRIT-2 FIX: Forward any tokens actually received to the caller (Vault)
                // This maintains the Push Model while being robust to module behavior
                if (received > 0) {
                    IERC20(token).safeTransfer(escrowContract, received);
                }
            } else {
                result.success = false;
                result.failureReason = 'Yield generation module returned false';
            }
        } catch Error(string memory reason) {
            result.success = false;
            result.failureReason = reason;
            emit YieldDistributionFailed(workflowId, token, 0, reason);
        } catch {
            result.success = false;
            result.failureReason = 'Yield withdrawal failed';
            emit YieldDistributionFailed(workflowId, token, 0, 'Yield withdrawal failed');
        }

        return result;
    }

    function _distributeYieldInternal(
        IYieldDistributionModule distModule,
        uint256 workflowId,
        address escrowContract,
        address token,
        uint256 yieldAmount,
        bytes memory distributionData
    ) public {
        if (_msgSender() != address(this)) revert InternalOnly(_msgSender());
        if (yieldAmount == 0) return;
        IERC20(token).safeTransfer(address(distModule), yieldAmount);
        (bool success, uint256 distributedAmount) = distModule.distributeYield(workflowId, escrowContract, token, yieldAmount, distributionData);
        if (!success) revert DistributionFailed(workflowId, token, yieldAmount);
        if (distributedAmount < yieldAmount) {
             emit YieldDistributionFailed(workflowId, token, yieldAmount - distributedAmount, 'Partial distribution');
        }
    }

    function recoverTokens(address token, address to, uint256 amount) external onlyRole(ROLE_GUARDIAN) {
        if (to == address(0)) revert InvalidRecipient(to);
        if (token == address(0)) {
            (bool success, ) = payable(to).call{value: amount}('');
            if (!success) revert TransferFailed(to, amount);
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
        emit TokensRecovered(token, to, amount);
    }
}

contracts/registry/ModuleRegistry.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/access/AccessControl.sol';
import '@openzeppelin/contracts/utils/introspection/IERC165.sol';
import '../interfaces/IModuleRegistry.sol';
import '../interfaces/IYieldGenerationModule.sol';
import '../interfaces/IYieldDistributionModule.sol';
import '../shared/interfaces/IResolutionModule.sol';
import '../types/EscrowTypes.sol';

/**
 * @title ModuleRegistry
 * @notice Simple module registry - allowlist + metadata for safety and UX
 * @dev Registry validates and tracks approved modules by type.
 *      Not a marketplace - just an allowlist with metadata for safety.
 */
contract ModuleRegistry is AccessControl, IModuleRegistry {
    bytes32 public constant ROLE_TIMELOCK = keccak256('ROLE_TIMELOCK');

    // Mapping: moduleType => module => metadata
    mapping(ModuleType => mapping(address => ModuleMetadata)) private _modules;

    // Mapping: moduleType => array of active module addresses (for enumeration)
    mapping(ModuleType => address[]) private _moduleList;

    // Errors
    error RegistryNotAContract(address module);
    error ModuleAlreadyExists(ModuleType moduleType, address module);
    error InvalidInterface(ModuleType moduleType, address module);
    error ModuleNotFound(ModuleType moduleType, address module);
    error InvalidStatusTransition(ModuleType moduleType, address module, ModuleStatus current, ModuleStatus requested);

    /**
     * @notice Deploy ModuleRegistry with initial admin
     * @param initialAdmin Initial admin address (typically timelock)
     */
    constructor(address initialAdmin) {
        if (initialAdmin == address(0)) revert InvalidAddress(ADDR_INITIAL_ADMIN, initialAdmin);
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(ROLE_TIMELOCK, initialAdmin);
    }

    /**
     * @notice Check if a module is approved and active
     * @param moduleType Type of module
     * @param module Module address
     * @return approved True if module is approved and active
     */
    function isApproved(ModuleType moduleType, address module) external view override returns (bool approved) {
        ModuleMetadata memory meta = _modules[moduleType][module];
        return meta.status == ModuleStatus.ACTIVE;
    }

    /**
     * @notice Get metadata for a module
     * @param moduleType Type of module
     * @param module Module address
     * @return metadata Module metadata (will have empty name if not registered)
     */
    function getMetadata(ModuleType moduleType, address module)
        external
        view
        override
        returns (ModuleMetadata memory metadata)
    {
        return _modules[moduleType][module];
    }

    /**
     * @notice Enumerate all active modules of a given type
     * @param moduleType Type of module
     * @return modules Array of active module addresses
     */
    function enumerateModules(ModuleType moduleType) external view override returns (address[] memory modules) {
        return _moduleList[moduleType];
    }

    /**
     * @notice Add a module to the registry
     * @param moduleType Type of module
     * @param module Module address
     * @param metadata Module metadata
     * @dev Only timelock can add modules. Validates interface and contract status.
     */
    function addModule(
        ModuleType moduleType,
        address module,
        ModuleMetadata calldata metadata
    ) external onlyRole(ROLE_TIMELOCK) {
        if (module.code.length == 0) revert RegistryNotAContract(module);

        // Check if module already exists (must be deprecated to re-add)
        ModuleMetadata memory existing = _modules[moduleType][module];
        if (existing.status == ModuleStatus.ACTIVE) {
            revert ModuleAlreadyExists(moduleType, module);
        }

        // Validate interface
        if (moduleType == ModuleType.YIELD_GENERATION) {
            if (!IERC165(module).supportsInterface(type(IYieldGenerationModule).interfaceId)) {
                revert InvalidInterface(moduleType, module);
            }
        } else if (moduleType == ModuleType.YIELD_DISTRIBUTION) {
            if (!IERC165(module).supportsInterface(type(IYieldDistributionModule).interfaceId)) {
                revert InvalidInterface(moduleType, module);
            }
        } else if (moduleType == ModuleType.RESOLUTION) {
            if (!IERC165(module).supportsInterface(type(IResolutionModule).interfaceId)) {
                revert InvalidInterface(moduleType, module);
            }
        }

        // Store metadata
        _modules[moduleType][module] = metadata;

        // Add to list if active
        if (metadata.status == ModuleStatus.ACTIVE) {
            _moduleList[moduleType].push(module);
        }

        emit ModuleAdded(moduleType, module, metadata.name, metadata.version);
    }

    /**
     * @notice Deprecate a module (mark as deprecated, don't remove)
     * @param moduleType Type of module
     * @param module Module address
     * @dev Only timelock can deprecate. Deprecated modules cannot be used as defaults.
     */
    function deprecateModule(ModuleType moduleType, address module) external onlyRole(ROLE_TIMELOCK) {
        ModuleMetadata memory existing = _modules[moduleType][module];
        if (existing.status != ModuleStatus.ACTIVE) {
            revert InvalidStatusTransition(moduleType, module, existing.status, ModuleStatus.DEPRECATED);
        }

        // Update status
        _modules[moduleType][module].status = ModuleStatus.DEPRECATED;

        // Remove from active list (find and remove)
        address[] storage list = _moduleList[moduleType];
        for (uint256 i = 0; i < list.length; i++) {
            if (list[i] == module) {
                // Swap with last and pop
                list[i] = list[list.length - 1];
                list.pop();
                break;
            }
        }

        emit ModuleDeprecated(moduleType, module);
    }

}

contracts/shared/governance/SlowLaneQueu.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

/**
 * @title SlowLaneQueueActivateUpgradeable
 * @notice Upgradeable version of SlowLaneQueueActivate
 * @dev Same functionality as SlowLaneQueueActivate, compatible with upgradeable contracts
 *      No storage, so fully compatible with upgradeable pattern
 *
 * Usage:
 * 1. Inherit this contract
 * 2. Add storage for pending values (PendingAddress or PendingUint)
 * 3. Implement queueX() function calling _queueAddress() or _queueUint()
 * 4. Implement activateX() function calling _activateAddress() or _activateUint()
 *
 * Pattern:
 * - queueX() stores pending value and ETA (now + 7 days)
 * - activateX() checks ETA has passed, then applies the change
 * - This enforces 7-day delay on top of Timelock's 48h delay
 *
 * Example:
 * ```solidity
 * PendingAddress private _pendingFeeRecipient;
 *
 * function queueFeeRecipient(address newAddr) external onlyRole(ROLE_TIMELOCK) {
 *     _queueAddress(_pendingFeeRecipient, newAddr);
 *     emit FeeRecipientQueued(feeRecipient, newAddr, _pendingFeeRecipient.eta);
 * }
 *
 * function activateFeeRecipient() external onlyRole(ROLE_TIMELOCK) {
 *     address old = feeRecipient;
 *     feeRecipient = _activateAddress(_pendingFeeRecipient);
 *     emit FeeRecipientActivated(old, feeRecipient);
 * }
 * ```
 */
abstract contract SlowLaneQueueActivateUpgradeable {
    /// @notice Slow lane delay: 7 days
    uint256 public constant SLOW_DELAY = 7 days;

    /// @notice Pending address change with ETA
    struct PendingAddress {
        address value;
        uint64 eta; // Unix timestamp when activation is allowed
        bool exists;
    }

    /// @notice Pending uint256 change with ETA
    struct PendingUint {
        uint256 value;
        uint64 eta; // Unix timestamp when activation is allowed
        bool exists;
    }

    /// @notice Error thrown when trying to activate before ETA
    error NotReady(uint64 eta);

    /// @notice Error thrown when no pending change exists
    error NoPending();

    /// @notice Error thrown when value is invalid (e.g., zero address)
    error InvalidValue();

    /**
     * @notice Queue an address change
     * @param pending Storage reference to PendingAddress
     * @param newValue New address value to queue
     * @dev Sets pending value and ETA = now + SLOW_DELAY
     */
    function _queueAddress(PendingAddress storage pending, address newValue) internal {
        if (newValue == address(0)) {
            revert InvalidValue();
        }
        pending.value = newValue;
        pending.eta = uint64(block.timestamp + SLOW_DELAY); // forge-lint: disable-line(unsafe-typecast)
        pending.exists = true;
    }

    /**
     * @notice Activate a queued address change
     * @param pending Storage reference to PendingAddress
     * @return activatedValue The activated address value
     * @dev Reverts if no pending change or ETA not reached
     */
    function _activateAddress(PendingAddress storage pending) internal returns (address) {
        if (!pending.exists) {
            revert NoPending();
        }
        if (block.timestamp < pending.eta) {
            revert NotReady(pending.eta);
        }
        address value = pending.value;
        // Clear all fields
        pending.value = address(0);
        pending.eta = 0;
        pending.exists = false;
        return value;
    }

    /**
     * @notice Queue a uint256 change
     * @param pending Storage reference to PendingUint
     * @param newValue New uint256 value to queue
     * @dev Sets pending value and ETA = now + SLOW_DELAY
     */
    function _queueUint(PendingUint storage pending, uint256 newValue) internal {
        pending.value = newValue;
        pending.eta = uint64(block.timestamp + SLOW_DELAY); // forge-lint: disable-line(unsafe-typecast)
        pending.exists = true;
    }

    /**
     * @notice Activate a queued uint256 change
     * @param pending Storage reference to PendingUint
     * @return activatedValue The activated uint256 value
     * @dev Reverts if no pending change or ETA not reached
     */
    function _activateUint(PendingUint storage pending) internal returns (uint256) {
        if (!pending.exists) {
            revert NoPending();
        }
        if (block.timestamp < pending.eta) {
            revert NotReady(pending.eta);
        }
        uint256 value = pending.value;
        // Clear all fields
        pending.value = 0;
        pending.eta = 0;
        pending.exists = false;
        return value;
    }

    /**
     * @notice Get pending address value (if exists)
     * @param pending Storage reference to PendingAddress
     * @return value Pending address value
     * @return eta Timestamp when activation is allowed
     * @return exists Whether a pending change exists
     */
    function getPendingAddress(
        PendingAddress storage pending
    ) internal view returns (address value, uint64 eta, bool exists) {
        return (pending.value, pending.eta, pending.exists);
    }

    /**
     * @notice Get pending uint256 value (if exists)
     * @param pending Storage reference to PendingUint
     * @return value Pending uint256 value
     * @return eta Timestamp when activation is allowed
     * @return exists Whether a pending change exists
     */
    function getPendingUint(
        PendingUint storage pending
    ) internal view returns (uint256 value, uint64 eta, bool exists) {
        return (pending.value, pending.eta, pending.exists);
    }
}

